/// Project one absolute window-grid selection onto exactly its owning split pane. The renderer
/// translates the range to pane-local content coordinates at paint time. Keeping this policy pure
/// prevents platform adapters from drifting on whether macOS/Linux split selections are visible.
fn attach_selection_to_owner(
    panes: &mut [ExtraPanePaint],
    owner: Option<&str>,
    selection: Option<(CellPos, CellPos)>,
) {
    let (Some(owner), Some(selection)) = (owner, selection) else {
        return;
    };
    if let Some(pane) = panes.iter_mut().find(|pane| pane.session_id == owner) {
        pane.selection = Some(selection);
    }
}

/// Re-export the stress-mode enum so the binary can parse `--stress <mode>` without
/// reaching into a private module.
pub use scene::StressMode;

