    fn role_transition_grid(cols: usize, rows: usize) -> GridSnapshot {
        let cell = Cell {
            text: " ".to_string(),
            fg: Color::Named {
                name: NamedColor::Foreground,
            },
            bg: Color::Named {
                name: NamedColor::Background,
            },
            bold: false,
            italic: false,
            underline: UnderlineStyle::None,
            inverse: false,
            strikeout: false,
            dim: false,
            hidden: false,
            width: 1,
        };
        GridSnapshot {
            version: crate::sync::SUPPORTED_VERSION,
            generation: SessionGeneration("gen-C".to_string()),
            revision: Revision(1),
            base_revision: Revision(0),
            cols,
            rows,
            rows_cells: vec![vec![cell; cols]; rows],
            cursor_line: 0,
            cursor_col: 0,
            cursor_visible: true,
            cursor_shape: CursorShape::Block,
            alt_screen: false,
            app_cursor: false,
            bracketed_paste: false,
            focus_reporting: false,
            mouse_report: false,
            mouse_drag: false,
            mouse_motion: false,
            mouse_sgr: false,
        }
    }

    fn role_transition_app(shared: Arc<Shared>, session_id: &str) -> App {
        App::new(
            shared,
            session_id.to_string(),
            DEFAULT_WINDOW_TITLE.to_string(),
            None,
            None,
            false,
            None,
            None,
            None,
            None,
            None,
            None,
            None,
            None,
            None,
        )
    }

    fn replay_attached_sessions(
        initial: &[&str],
        requests: &[ClientRequest],
    ) -> std::collections::BTreeSet<String> {
        let mut attached: std::collections::BTreeSet<String> =
            initial.iter().map(|id| (*id).to_string()).collect();
        for request in requests {
            match request {
                ClientRequest::Attach { id, .. } => {
                    attached.insert(id.clone());
                }
                ClientRequest::Detach { id } => {
                    attached.remove(id);
                }
                _ => {}
            }
        }
        attached
    }

    #[test]
    fn diag_a_over_b_pipe_c_split_c_down_keeps_b() {
        // User repro: build `A/B | C`, then split C down. Expected `A/B | C/D`; bug reported `A | C/D`.
        // Chain: A=root; split A right -> C (right col); split A down -> B (left col stacked); split C
        // down -> D. Active follows the last child created.
        use RendererTabSplitAxis::{Down, Right};
        let tabs = vec![
            plain_tab("A", false),
            split_child("C", "A", Right, false),
            split_child("B", "A", Down, false),
            split_child("D", "C", Down, true),
        ];
        let layout = compute_split_layout(&strip(tabs), 40, 20).expect("layout");
        let ids: std::collections::BTreeSet<_> =
            layout.panes.iter().map(|p| p.session_id.clone()).collect();
        eprintln!("DIAG panes:");
        for p in &layout.panes {
            eprintln!(
                "  {} region=(c{},r{},{}x{}) active={}",
                p.session_id, p.region.col, p.region.row, p.region.cols, p.region.rows, p.active
            );
        }
        assert!(
            ids.contains("sid-B"),
            "B must survive splitting C; got {ids:?}"
        );
        assert_eq!(layout.panes.len(), 4, "all four panes present");
    }

    /// Split order independence (user repro): A│B then split A-down then B-down WORKS, but B-down then
    /// A-down used to not paint. Both orders must yield the same 2×2 with all four panes visible.
    #[test]
    fn split_layout_is_independent_of_child_creation_order() {
        use RendererTabSplitAxis::{Down, Right};
        let order_a_then_b = vec![
            plain_tab("A", false),
            split_child("B", "A", Right, false),
            split_child("C", "A", Down, false),
            split_child("D", "B", Down, true),
        ];
        let order_b_then_a = vec![
            plain_tab("A", false),
            split_child("B", "A", Right, false),
            split_child("D", "B", Down, false),
            split_child("C", "A", Down, true),
        ];
        for (label, tabs) in [("A_then_B", order_a_then_b), ("B_then_A", order_b_then_a)] {
            let layout = compute_split_layout(&strip(tabs), 40, 20).expect("layout");
            let nonzero = layout
                .panes
                .iter()
                .filter(|p| p.region.cols > 0 && p.region.rows > 0)
                .count();
            assert_eq!(layout.panes.len(), 4, "{label}: all four panes present");
            assert_eq!(nonzero, 4, "{label}: all four panes visible");
        }
    }

    #[test]
    fn set_strip_then_attach_promotes_fourth_pane_without_detaching_its_live_role() {
        use RendererTabSplitAxis::{Down, Right};

        let shared = Shared::with_test_outbound();
        shared.set_active_session("sid-C");
        *shared.grid.lock().unwrap() = Some(Arc::new(role_transition_grid(120, 38)));
        let mut app = role_transition_app(shared.clone(), "sid-C");

        // Existing A | B/C layout with C primary. This seeds the UI-owned cache with A+B.
        let before = strip(vec![
            plain_tab("A", false),
            split_child("B", "A", Right, false),
            split_child("C", "B", Down, true),
        ]);
        app.handle_user_event(UserEvent::SetTabStrip {
            tab_strip: Some(before),
        });
        shared.drain_test_requests();
        assert_eq!(
            app.pane_cache_dims
                .keys()
                .cloned()
                .collect::<std::collections::BTreeSet<_>>(),
            ["sid-A".to_string(), "sid-B".to_string()]
                .into_iter()
                .collect()
        );

        // Product foreground order is SetTabStrip FIRST: D is briefly a non-primary cache pane
        // because C is still the primary storage id.
        let four = strip(vec![
            plain_tab("A", false),
            split_child("B", "A", Right, false),
            split_child("C", "B", Down, false),
            split_child("D", "C", Right, true),
        ]);
        app.handle_user_event(UserEvent::SetTabStrip {
            tab_strip: Some(four),
        });
        let strip_requests = shared.drain_test_requests();
        assert!(
            strip_requests.iter().any(
                |request| matches!(request, ClientRequest::Attach { id, want_raw_output: false } if id == "sid-D")
            ),
            "SetTabStrip temporarily attaches the new D pane"
        );
        assert!(app.pane_cache_dims.contains_key("sid-D"));

        let layout = app.current_split_layout().expect("four-pane layout");
        let content_dims = |id: &str| {
            let region = layout
                .panes
                .iter()
                .find(|pane| pane.session_id == id)
                .unwrap_or_else(|| panic!("missing {id} pane"))
                .region;
            let content = pane_content_region(region);
            (content.cols, content.rows)
        };
        let c_content_dims = content_dims("sid-C");
        let d_content_dims = content_dims("sid-D");
        assert_eq!(
            c_content_dims, d_content_dims,
            "regression setup must cover the equal-size old/new-primary transition"
        );
        assert_ne!(d_content_dims, (120, 38));

        // AttachSession then promotes D. The same synchronous transition must demote still-visible C
        // into the cache and remove D's stale Pane role WITHOUT Detach(D). Detach is per session, not
        // per role, so the old behavior froze D forever after its initial blank baseline.
        app.attach_session_with_window_dims("sid-D".to_string(), Some((120, 38)));
        let transition = shared.drain_test_requests();
        assert!(
            !transition
                .iter()
                .any(|request| matches!(request, ClientRequest::Detach { id } if id == "sid-D")),
            "removing D's old Pane role must not detach the now-active D"
        );
        assert!(
            !transition
                .iter()
                .any(|request| matches!(request, ClientRequest::Detach { id } if id == "sid-C")),
            "still-visible old primary C must be demoted, not detached"
        );
        assert!(
            transition.iter().any(
                |request| matches!(request, ClientRequest::Attach { id, want_raw_output: false } if id == "sid-C")
            ),
            "old primary C is immediately attached as a cached visible pane"
        );
        assert!(
            transition.iter().any(
                |request| matches!(request, ClientRequest::Attach { id, want_raw_output: false } if id == "sid-D")
            ),
            "D is attached for its active role"
        );
        let d_resizes: Vec<(u16, u16)> = transition
            .iter()
            .filter_map(|request| match request {
                ClientRequest::Resize { id, cols, rows } if id == "sid-D" => Some((*cols, *rows)),
                _ => None,
            })
            .collect();
        assert_eq!(
            d_resizes,
            vec![d_content_dims],
            "promoted D must receive its pane-content geometry, never the full window"
        );
        assert_eq!(app.primary_pane_dims, Some(d_content_dims));
        assert_eq!(app.session_id, "sid-D");
        assert_eq!(shared.active_snapshot().id, "sid-D");
        assert!(!app.pane_cache_dims.contains_key("sid-D"));
        assert!(app.pane_cache_dims.contains_key("sid-C"));
        assert_eq!(
            shared
                .pane_ids()
                .into_iter()
                .collect::<std::collections::BTreeSet<_>>(),
            [
                "sid-A".to_string(),
                "sid-B".to_string(),
                "sid-C".to_string()
            ]
            .into_iter()
            .collect()
        );
    }

    #[test]
    fn attach_first_split_stash_revive_and_outer_resize_keep_every_visible_pty_attached_and_sized()
    {
        use RendererTabSplitAxis::Right;

        const FIRST_WINDOW: (u16, u16) = (120, 38);
        const RESIZED_WINDOW: (u16, u16) = (160, 50);

        let shared = Shared::with_test_outbound();
        shared.set_active_session("sid-A");
        *shared.grid.lock().unwrap() = Some(Arc::new(role_transition_grid(
            usize::from(FIRST_WINDOW.0),
            usize::from(FIRST_WINDOW.1),
        )));
        let mut app = role_transition_app(shared.clone(), "sid-A");
        app.handle_user_event(UserEvent::SetTabStrip {
            tab_strip: Some(strip(vec![plain_tab("A", true)])),
        });
        shared.drain_test_requests();

        let split = strip(vec![
            plain_tab("A", false),
            split_child("B", "A", Right, true),
        ]);
        let first_layout = compute_split_layout(&split, FIRST_WINDOW.0, FIRST_WINDOW.1)
            .expect("first split layout");
        let first_dims = |id: &str| {
            let pane = first_layout
                .panes
                .iter()
                .find(|pane| pane.session_id == id)
                .unwrap_or_else(|| panic!("missing {id}"));
            let content = pane_content_region_for_layout(pane.region, first_layout.panes.len());
            (content.cols, content.rows)
        };

        // React split/revive currently foregrounds the destination session BEFORE publishing the
        // replacement strip. The old one-pane strip must not create a transient cache role that is
        // immediately detached yet still remembered as attached.
        app.attach_session_with_window_dims("sid-B".to_string(), Some(FIRST_WINDOW));
        let mut split_requests = shared.drain_test_requests();
        *shared.grid.lock().unwrap() = Some(Arc::new(role_transition_grid(
            usize::from(FIRST_WINDOW.0),
            usize::from(FIRST_WINDOW.1),
        )));
        app.handle_user_event(UserEvent::SetTabStrip {
            tab_strip: Some(split.clone()),
        });
        app.sync_primary_resize();
        split_requests.extend(shared.drain_test_requests());

        let source_attach = split_requests
            .iter()
            .rposition(
                |request| matches!(request, ClientRequest::Attach { id, .. } if id == "sid-A"),
            )
            .expect("source pane is reattached");
        let source_resize = split_requests[source_attach + 1..]
            .iter()
            .position(|request| {
                matches!(
                    request,
                    ClientRequest::Resize { id, cols, rows }
                        if id == "sid-A" && (*cols, *rows) == first_dims("sid-A")
                )
            })
            .map(|offset| source_attach + 1 + offset)
            .unwrap_or_else(|| {
                panic!(
                "source pane must be resized after its notification-safe Attach: {split_requests:?}"
            )
            });
        assert!(
            split_requests[source_resize + 1..].iter().any(
                |request| matches!(request, ClientRequest::Snapshot { id } if id == "sid-A")
            ),
            "new cache panes need a final pane-sized baseline after Attach+Resize: {split_requests:?}",
        );
        assert!(
            app.pending_resize_refit_at.is_some(),
            "a structural split must arm the settled all-pane snapshot"
        );
        app.pending_resize_refit_at = Some(std::time::Instant::now());
        assert!(app.flush_resize_refit_if_due());
        let split_refit = shared.drain_test_requests();
        for id in ["sid-A", "sid-B"] {
            assert!(split_refit.iter().any(
                |request| matches!(request, ClientRequest::Snapshot { id: request_id } if request_id == id)
            ));
        }
        split_requests.extend(split_refit);

        assert_eq!(
            replay_attached_sessions(&["sid-A"], &split_requests),
            ["sid-A".to_string(), "sid-B".to_string()]
                .into_iter()
                .collect(),
            "after an attach-first split, both visible pane forwarders must be live; requests={split_requests:?}",
        );
        for id in ["sid-A", "sid-B"] {
            let expected = first_dims(id);
            assert!(
                split_requests.iter().any(|request| matches!(
                    request,
                    ClientRequest::Resize { id: request_id, cols, rows }
                        if request_id == id && (*cols, *rows) == expected
                )),
                "split must resize {id} to {expected:?}; requests={split_requests:?}",
            );
        }

        // Stashing the active B pane switches to survivor A before publishing the one-pane strip.
        // A must expand to the complete window and B must be the only forwarder detached.
        app.attach_session_with_window_dims("sid-A".to_string(), Some(FIRST_WINDOW));
        let mut stash_requests = shared.drain_test_requests();
        *shared.grid.lock().unwrap() = Some(Arc::new(role_transition_grid(
            usize::from(FIRST_WINDOW.0),
            usize::from(FIRST_WINDOW.1),
        )));
        app.handle_user_event(UserEvent::SetTabStrip {
            tab_strip: Some(strip(vec![plain_tab("A", true)])),
        });
        app.sync_primary_resize();
        stash_requests.extend(shared.drain_test_requests());
        assert!(
            app.pending_resize_refit_at.is_some(),
            "stash geometry change must arm the settled refit"
        );
        app.pending_resize_refit_at = Some(std::time::Instant::now());
        assert!(app.flush_resize_refit_if_due());
        stash_requests.extend(shared.drain_test_requests());
        assert_eq!(
            replay_attached_sessions(&["sid-A", "sid-B"], &stash_requests),
            ["sid-A".to_string()].into_iter().collect(),
            "stash must leave only the survivor attached; requests={stash_requests:?}",
        );
        assert!(stash_requests.iter().any(|request| matches!(
            request,
            ClientRequest::Resize { id, cols, rows }
                if id == "sid-A" && (*cols, *rows) == FIRST_WINDOW
        )));
        assert!(stash_requests
            .iter()
            .any(|request| matches!(request, ClientRequest::Snapshot { id } if id == "sid-A")));

        // Revive uses the same attach-first ordering as a fresh split. Both sessions must be live
        // again and must return to their split content dimensions.
        app.attach_session_with_window_dims("sid-B".to_string(), Some(FIRST_WINDOW));
        let mut revive_requests = shared.drain_test_requests();
        *shared.grid.lock().unwrap() = Some(Arc::new(role_transition_grid(
            usize::from(FIRST_WINDOW.0),
            usize::from(FIRST_WINDOW.1),
        )));
        app.handle_user_event(UserEvent::SetTabStrip {
            tab_strip: Some(split.clone()),
        });
        app.sync_primary_resize();
        revive_requests.extend(shared.drain_test_requests());
        assert!(
            app.pending_resize_refit_at.is_some(),
            "revive geometry change must arm the settled refit"
        );
        app.pending_resize_refit_at = Some(std::time::Instant::now());
        assert!(app.flush_resize_refit_if_due());
        revive_requests.extend(shared.drain_test_requests());
        assert_eq!(
            replay_attached_sessions(&["sid-A"], &revive_requests),
            ["sid-A".to_string(), "sid-B".to_string()]
                .into_iter()
                .collect(),
            "revive must reattach both visible panes; requests={revive_requests:?}",
        );
        for id in ["sid-A", "sid-B"] {
            let expected = first_dims(id);
            assert!(revive_requests.iter().any(|request| matches!(
                request,
                ClientRequest::Resize { id: request_id, cols, rows }
                    if request_id == id && (*cols, *rows) == expected
            )));
            assert!(revive_requests.iter().any(
                |request| matches!(request, ClientRequest::Snapshot { id: request_id } if request_id == id)
            ));
        }

        // A later outer-window resize must update BOTH the primary and the pre-existing cached pane.
        *shared.grid.lock().unwrap() = Some(Arc::new(role_transition_grid(
            usize::from(RESIZED_WINDOW.0),
            usize::from(RESIZED_WINDOW.1),
        )));
        app.send_resize(RESIZED_WINDOW);
        app.sync_pane_cache();
        let mut outer_resize_requests = shared.drain_test_requests();
        let resized_layout = compute_split_layout(&split, RESIZED_WINDOW.0, RESIZED_WINDOW.1)
            .expect("resized split layout");
        for id in ["sid-A", "sid-B"] {
            let pane = resized_layout
                .panes
                .iter()
                .find(|pane| pane.session_id == id)
                .unwrap_or_else(|| panic!("missing resized {id}"));
            let content = pane_content_region_for_layout(pane.region, resized_layout.panes.len());
            let expected = (content.cols, content.rows);
            assert!(
                outer_resize_requests.iter().any(|request| matches!(
                    request,
                    ClientRequest::Resize { id: request_id, cols, rows }
                        if request_id == id && (*cols, *rows) == expected
                )),
                "outer resize must update {id} to {expected:?}; requests={outer_resize_requests:?}"
            );
        }
        // The real HostEvent::Resized path arms this settled refit after the coalesced Resize.
        // Flush it here to prove both panes receive final authoritative baselines even when neither
        // shell emits output after the outer-window resize.
        app.schedule_resize_refit();
        app.pending_resize_refit_at = Some(std::time::Instant::now());
        assert!(app.flush_resize_refit_if_due());
        outer_resize_requests.extend(shared.drain_test_requests());
        for id in ["sid-A", "sid-B"] {
            assert!(
                outer_resize_requests.iter().any(
                    |request| matches!(request, ClientRequest::Snapshot { id: request_id } if request_id == id)
                ),
                "outer resize must settle {id} with a final Snapshot; requests={outer_resize_requests:?}"
            );
        }
        assert_eq!(
            replay_attached_sessions(&["sid-A", "sid-B"], &outer_resize_requests),
            ["sid-A".to_string(), "sid-B".to_string()]
                .into_iter()
                .collect(),
            "outer resize/refit must not disturb either visible forwarder"
        );
    }

    #[test]
    fn pane_cache_teardown_never_detaches_primary_or_sibling_roles() {
        let shared = Shared::with_test_outbound();
        shared.set_active_session("primary");
        let mut app = role_transition_app(shared.clone(), "primary");
        app.sibling_id = Some("sibling".to_string());
        app.pane_cache_dims.insert("primary".to_string(), (10, 5));
        app.pane_cache_dims.insert("sibling".to_string(), (10, 5));
        app.pane_cache_dims.insert("gone".to_string(), (10, 5));
        shared.set_pane_sessions(&["primary", "sibling", "gone"]);

        // No strip means wanted is empty: only the truly-gone pane may lose its daemon forwarder.
        app.sync_pane_cache();
        let requests = shared.drain_test_requests();
        assert!(requests
            .iter()
            .any(|request| matches!(request, ClientRequest::Detach { id } if id == "gone")));
        assert!(
            !requests.iter().any(
                |request| matches!(request, ClientRequest::Detach { id } if id == "primary" || id == "sibling")
            ),
            "cache teardown cannot cancel another live renderer role: {requests:?}"
        );
    }

    #[test]
    fn every_four_pane_branching_chain_paints_all_four_panes() {
        // Regression: a pane split MORE THAN ONCE (e.g. split right, then split down) used to drop every
        // child after the first, so the 4th pane was generated but never painted until another pane was
        // closed. place_split_chain now visits ALL children of each pane. Each entry: (label, tabs).
        use RendererTabSplitAxis::{Down, Right};
        let cases: Vec<(&str, Vec<RendererTab>)> = vec![
            // A│B│C then split A down -> (A/D)│B│C
            (
                "ABC_splitA_down",
                vec![
                    plain_tab("A", false),
                    split_child("B", "A", Right, false),
                    split_child("C", "B", Right, false),
                    split_child("D", "A", Down, true),
                ],
            ),
            // A│B│C then split C down -> A│B│(C/D)
            (
                "ABC_splitC_down",
                vec![
                    plain_tab("A", false),
                    split_child("B", "A", Right, false),
                    split_child("C", "B", Right, false),
                    split_child("D", "C", Down, true),
                ],
            ),
            // A│B│C then split B down -> A│(B/D)│C
            (
                "ABC_splitB_down",
                vec![
                    plain_tab("A", false),
                    split_child("B", "A", Right, false),
                    split_child("C", "B", Right, false),
                    split_child("D", "B", Down, true),
                ],
            ),
            // A/B/C then split A right -> (A│D)/B/C
            (
                "ABC_rows_splitA_right",
                vec![
                    plain_tab("A", false),
                    split_child("B", "A", Down, false),
                    split_child("C", "B", Down, false),
                    split_child("D", "A", Right, true),
                ],
            ),
            // A│(B/C) then split A down -> (A/D)│(B/C)
            (
                "leftMain_splitA_down",
                vec![
                    plain_tab("A", false),
                    split_child("B", "A", Right, false),
                    split_child("C", "B", Down, false),
                    split_child("D", "A", Down, true),
                ],
            ),
        ];
        let mut broken = Vec::new();
        for (label, tabs) in cases {
            let layout = compute_split_layout(&strip(tabs), 40, 20).expect("layout");
            let n = layout.panes.len();
            let nonzero = layout
                .panes
                .iter()
                .filter(|p| p.region.cols > 0 && p.region.rows > 0)
                .count();
            eprintln!("CHAIN {label}: {n} panes, {nonzero} with nonzero region");
            for p in &layout.panes {
                eprintln!(
                    "    {} ({}x{} @ c{},r{})",
                    p.session_id, p.region.cols, p.region.rows, p.region.col, p.region.row
                );
            }
            if n != 4 || nonzero != 4 {
                broken.push(label);
            }
        }
        assert!(
            broken.is_empty(),
            "these 4-pane chains lose a pane (invisible until another is killed): {broken:?}"
        );
    }

    #[test]
    fn newly_split_child_session_finds_the_child_added_since_the_previous_strip() {
        use RendererTabSplitAxis::Right;
        // Previous strip: A | B (B is the split child). New strip adds C split from B.
        let old = strip(vec![
            plain_tab("A", false),
            split_child("B", "A", Right, false),
        ]);
        let new = strip(vec![
            plain_tab("A", false),
            split_child("B", "A", Right, false),
            split_child("C", "B", Right, true),
        ]);
        assert_eq!(
            newly_split_child_session(Some(&old), &new),
            Some("sid-C"),
            "the child absent from the previous strip is the freshly split pane"
        );
    }

    #[test]
    fn newly_split_child_session_ignores_a_plain_tab_switch_or_close() {
        use RendererTabSplitAxis::Right;
        let old = strip(vec![
            plain_tab("A", true),
            split_child("B", "A", Right, false),
        ]);
        // Same tabs, active flag flipped (a focus switch) — no NEW child appeared.
        let switched = strip(vec![
            plain_tab("A", false),
            split_child("B", "A", Right, true),
        ]);
        assert_eq!(newly_split_child_session(Some(&old), &switched), None);
        // A close (B removed) introduces no new child either.
        let closed = strip(vec![plain_tab("A", true)]);
        assert_eq!(newly_split_child_session(Some(&old), &closed), None);
    }

    #[test]
    fn four_grid_tiles_without_overlap_and_covers_grid() {
        // Same chain as the diag repro (A/B | C, split C down → FourGrid 2×2). Assert the four regions
        // are pairwise non-overlapping and together cover every cell except the divider rows/cols.
        use RendererTabSplitAxis::{Down, Right};
        let (cols, rows) = (40u16, 20u16);
        let tabs = vec![
            plain_tab("A", false),
            split_child("C", "A", Right, false),
            split_child("B", "A", Down, false),
            split_child("D", "C", Down, true),
        ];
        let layout = compute_split_layout(&strip(tabs), cols, rows).expect("layout");
        assert_eq!(layout.panes.len(), 4, "FourGrid has four panes");

        // Pairwise non-overlap.
        let r: Vec<_> = layout.panes.iter().map(|p| p.region).collect();
        let overlaps = |a: &RendererPaneRegion, b: &RendererPaneRegion| -> bool {
            let ax2 = a.col + a.cols;
            let ay2 = a.row + a.rows;
            let bx2 = b.col + b.cols;
            let by2 = b.row + b.rows;
            a.col < bx2 && b.col < ax2 && a.row < by2 && b.row < ay2
        };
        for i in 0..r.len() {
            for j in (i + 1)..r.len() {
                assert!(
                    !overlaps(&r[i], &r[j]),
                    "regions {i} and {j} overlap: {:?} {:?}",
                    r[i],
                    r[j]
                );
            }
        }

        // Coverage: every cell is owned by exactly one pane, except divider cells (owned by none). The
        // 2×2 has its shared vertical cut plus TWO independent horizontal cuts (one per column), so
        // height changes in one column do not move the other column's divider.
        let mut owned_cells = 0usize;
        for cx in 0..cols {
            for cy in 0..rows {
                let owners = r
                    .iter()
                    .filter(|p| {
                        cx >= p.col && cx < p.col + p.cols && cy >= p.row && cy < p.row + p.rows
                    })
                    .count();
                assert!(owners <= 1, "cell ({cx},{cy}) owned by {owners} panes (>1)");
                owned_cells += owners;
            }
        }
        assert!(
            (cols as usize * rows as usize) - owned_cells > 0,
            "a 2×2 grid must have divider cells"
        );
        // Independent heights: two horizontal dividers (left column's, right column's), not one shared.
        let horizontal_dividers = layout.dividers.iter().filter(|d| d.glyph == '-').count();
        assert_eq!(
            horizontal_dividers, 2,
            "each column has its own horizontal divider (independent heights)"
        );
    }

    #[test]
    fn four_grid_right_column_height_is_independent_of_the_left() {
        // 2×2: A(TL) | C(TR); B = bottom-left (split-down from A); D = bottom-right (split-down from C).
        // Dragging the RIGHT column's row divider (keyed to D, the bottom-right tab) must change ONLY
        // the right column's row split — the left column (A/B) stays put. This is the unbundled height.
        use RendererTabSplitAxis::{Down, Right};
        let (cols, rows) = (40u16, 20u16);
        let tabs = vec![
            plain_tab("A", false),
            split_child("C", "A", Right, false),
            split_child("B", "A", Down, false),
            split_child("D", "C", Down, true),
        ];
        let s = strip(tabs);
        // Default ratios: both columns split evenly, so the two bottom panes share a row.
        let base = compute_split_layout(&s, cols, rows).expect("layout");
        let bot = |l: &RendererSplitLayout, sid: &str| {
            l.panes.iter().find(|p| p.session_id == sid).unwrap().region
        };
        let (a0, b0) = (bot(&base, "sid-A"), bot(&base, "sid-B"));
        // Make the RIGHT column's top pane (C) much taller by setting D's first-share large.
        let mut ratios = SplitRatios::default();
        ratios.set_first_share("D", 0.8);
        let dragged = compute_split_layout_with(&s, cols, rows, &ratios).expect("layout");
        // Right column moved: C taller, D shorter than the even baseline.
        assert!(
            bot(&dragged, "sid-C").rows > bot(&base, "sid-C").rows,
            "right column's top pane should grow"
        );
        assert!(
            bot(&dragged, "sid-D").rows < bot(&base, "sid-D").rows,
            "right column's bottom pane should shrink"
        );
        // LEFT column unchanged — independence proven.
        assert_eq!(
            bot(&dragged, "sid-A"),
            a0,
            "left column top pane must not move"
        );
        assert_eq!(
            bot(&dragged, "sid-B"),
            b0,
            "left column bottom pane must not move"
        );
    }

    #[test]
    fn four_grid_renders_full_top_row_revive_order() {
        use RendererTabSplitAxis::{Down, Right};
        let tabs = vec![
            plain_tab("A", false),
            split_child("B", "A", Down, false),
            split_child("D", "A", Right, true),
            split_child("C", "B", Right, false),
        ];
        let layout = compute_split_layout(&strip(tabs), 40, 20).expect("layout");
        assert_eq!(layout.panes.len(), 4, "revived fourth pane is visible");
        let by_id = |id: &str| {
            layout
                .panes
                .iter()
                .find(|p| p.session_id == format!("sid-{id}"))
                .unwrap()
                .region
        };
        let a = by_id("A");
        let d = by_id("D");
        let b = by_id("B");
        let c = by_id("C");
        assert_eq!(a.row, d.row, "revived pane shares the original top row");
        assert!(d.col > a.col, "revived pane is to the right of the top row");
        assert_eq!(b.row, c.row, "existing bottom pair stays in the bottom row");
        assert!(
            c.col > b.col,
            "existing bottom-right pane stays to the right"
        );
        assert!(b.row > a.row, "bottom row remains below the top row");
    }

    #[test]
    fn per_mille_round_trips_through_first_share() {
        // Exact midpoint and the persisted band edges survive a per-mille -> share -> per-mille trip.
        for pm in [0u16, 100, 250, 500, 640, 900, 1000] {
            let share = per_mille_to_first_share(pm);
            assert_eq!(first_share_to_per_mille(share), pm, "round-trip for {pm}");
        }
        // 500 per-mille is exactly the historical even split.
        assert_eq!(per_mille_to_first_share(500), DEFAULT_SPLIT_RATIO);
        // Out-of-range input is clamped to the 0..=1000 band before conversion.
        assert_eq!(per_mille_to_first_share(5000), 1.0);
        assert_eq!(first_share_to_per_mille(2.0), 1000);
        assert_eq!(first_share_to_per_mille(-1.0), 0);
    }

    #[test]
    fn hydrate_adopts_persisted_ratios_and_skips_the_dragged_child() {
        let s = strip(vec![
            plain_tab("src", false),
            split_child_with_ratio("a", "src", RendererTabSplitAxis::Right, Some(640)),
            split_child_with_ratio("b", "src", RendererTabSplitAxis::Down, Some(300)),
            // No persisted ratio: hydration must leave it to fall through to the default.
            split_child_with_ratio("c", "src", RendererTabSplitAxis::Right, None),
        ]);

        // No active drag: every tab with a persisted ratio is adopted; the unset one stays default.
        let mut ratios = SplitRatios::default();
        hydrate_split_ratios(&mut ratios, &s, None);
        assert_eq!(ratios.first_share("a"), per_mille_to_first_share(640));
        assert_eq!(ratios.first_share("b"), per_mille_to_first_share(300));
        assert_eq!(ratios.first_share("c"), DEFAULT_SPLIT_RATIO);

        // A live drag on "a" must NOT be clobbered: the in-flight value wins over the strip refresh.
        let mut dragging_ratios = SplitRatios::default();
        dragging_ratios.set_first_share("a", 0.8);
        hydrate_split_ratios(&mut dragging_ratios, &s, Some("a"));
        assert_eq!(dragging_ratios.first_share("a"), 0.8);
        // Other children still hydrate normally while "a" is held.
        assert_eq!(
            dragging_ratios.first_share("b"),
            per_mille_to_first_share(300)
        );
    }

    #[test]
    fn right_split_computes_left_right_regions_and_divider() {
        let tabs = vec![
            plain_tab("src", false),
            split_child("child", "src", RendererTabSplitAxis::Right, true),
        ];
        let frame = compute_split_frame(&tabs, "child", 21, 10).expect("frame");
        assert_eq!(frame.axis, RendererTabSplitAxis::Right);
        assert_eq!(frame.source_tab_id, "src");
        assert_eq!(frame.child_tab_id, "child");
        // (21-1)/2 = 10 columns left, divider at col 10, 10 columns right.
        assert_eq!(
            frame.first,
            RendererPaneRegion {
                col: 0,
                row: 0,
                cols: 10,
                rows: 10
            }
        );
        assert_eq!(
            frame.second,
            RendererPaneRegion {
                col: 11,
                row: 0,
                cols: 10,
                rows: 10
            }
        );
        assert_eq!(
            frame.divider,
            RendererSplitDivider {
                col: 10,
                row: 0,
                length: 10,
                glyph: '|'
            }
        );
    }

