    #[test]
    fn pane_session_id_resolves_present_tab_and_misses_absent() {
        let s = strip(vec![plain_tab("src", true), plain_tab("other", false)]);
        assert_eq!(pane_session_id(&s, "src"), Some("sid-src"));
        assert_eq!(pane_session_id(&s, "other"), Some("sid-other"));
        assert_eq!(pane_session_id(&s, "ghost"), None);
    }

    #[test]
    fn active_child_split_resolves_inactive_source_session() {
        // Active tab is the child → inactive pane is the source tab; its session is the attach target.
        let s = strip(vec![
            plain_tab("src", false),
            split_child("child", "src", RendererTabSplitAxis::Right, true),
        ]);
        let frame = active_split_frame(Some(&s), 21, 10).expect("frame");
        assert_eq!(active_pane_tab_id(&frame), "child");
        assert_eq!(inactive_pane_tab_id(&frame), "src");
        assert_eq!(active_pane_session_id(&frame, &s), Some("sid-child"));
        assert_eq!(inactive_pane_session_id(&frame, &s), Some("sid-src"));
        // active_split_frame caches the inactive session on the frame for the placeholder.
        assert_eq!(frame.inactive_session_id.as_deref(), Some("sid-src"));
    }

    #[test]
    fn active_source_split_resolves_inactive_child_session() {
        // Active tab is the source → inactive pane is the child tab; its session is the attach target.
        let s = strip(vec![
            plain_tab("top", true),
            split_child("bot", "top", RendererTabSplitAxis::Down, false),
        ]);
        let frame = active_split_frame(Some(&s), 12, 9).expect("frame");
        assert_eq!(active_pane_tab_id(&frame), "top");
        assert_eq!(inactive_pane_tab_id(&frame), "bot");
        assert_eq!(active_pane_session_id(&frame, &s), Some("sid-top"));
        assert_eq!(inactive_pane_session_id(&frame, &s), Some("sid-bot"));
        assert_eq!(frame.inactive_session_id.as_deref(), Some("sid-bot"));
    }

    #[test]
    fn missing_sibling_session_returns_no_attach_target() {
        // The source tab paired by `compute_split_frame` exists, but a strip whose source tab carries an
        // empty/absent session must not invent one. Here we drop the source from the strip used for the
        // session lookup: the pairing still resolves the tab id, but no session is found → None.
        let tabs = vec![
            plain_tab("src", false),
            split_child("child", "src", RendererTabSplitAxis::Right, true),
        ];
        let frame = compute_split_frame(&tabs, "child", 21, 10).expect("frame");
        // A strip that has the child but NOT the source (sibling) tab.
        let lookup = strip(vec![split_child(
            "child",
            "src",
            RendererTabSplitAxis::Right,
            true,
        )]);
        assert_eq!(inactive_pane_tab_id(&frame), "src");
        assert_eq!(inactive_pane_session_id(&frame, &lookup), None);
    }

    // --- session-id pane focus: write routing across an N-pane layout ---

    #[test]
    fn session_focus_none_targets_active_session() {
        // The default `None` focus targets the active session, with or without a layout — the no-split
        // and active-pane write paths stay byte-identical.
        assert_eq!(
            focused_session_write_target(None, "sid-active", None),
            "sid-active"
        );
        let s = strip(vec![
            plain_tab("src", false),
            split_child("child", "src", RendererTabSplitAxis::Right, true),
        ]);
        let layout = compute_split_layout(&s, 21, 10).expect("layout");
        assert_eq!(
            focused_session_write_target(None, "sid-active", Some(&layout)),
            "sid-active"
        );
    }

    #[test]
    fn session_focus_routes_to_each_focused_pane_session() {
        // A three-pane layout: src (left), mid (top-right), bot (bottom-right, active). Focusing each
        // non-active pane's session routes the write there; focusing the active pane's own session also
        // resolves to it.
        let tabs = vec![
            plain_tab("src", false),
            split_child("mid", "src", RendererTabSplitAxis::Right, false),
            split_child("bot", "mid", RendererTabSplitAxis::Down, true),
        ];
        let layout = compute_split_layout(&strip(tabs), 21, 10).expect("layout");
        assert_eq!(
            focused_session_write_target(Some("sid-src"), "sid-bot", Some(&layout)),
            "sid-src"
        );
        assert_eq!(
            focused_session_write_target(Some("sid-mid"), "sid-bot", Some(&layout)),
            "sid-mid"
        );
        assert_eq!(
            focused_session_write_target(Some("sid-bot"), "sid-bot", Some(&layout)),
            "sid-bot"
        );
    }

    #[test]
    fn session_focus_on_removed_pane_falls_back_to_active() {
        // Focus pointing at a session that is no longer a pane in the live layout (the pane was closed)
        // degrades to the active session, never a vanished one. Same fallback when there is no layout.
        let s = strip(vec![
            plain_tab("src", false),
            split_child("child", "src", RendererTabSplitAxis::Right, true),
        ]);
        let layout = compute_split_layout(&s, 21, 10).expect("layout");
        assert_eq!(
            focused_session_write_target(Some("sid-gone"), "sid-child", Some(&layout)),
            "sid-child"
        );
        assert_eq!(
            focused_session_write_target(Some("sid-src"), "sid-child", None),
            "sid-child"
        );
    }

    // --- focused-pane indicator: the drawn focus region resolves like the write target ---

    #[test]
    fn focus_indicator_none_without_split_draws_no_chrome() {
        // A single (unsplit) active tab yields a one-pane layout; a single pane needs no focus chrome,
        // so the indicator is `None` and the no-split view stays visually unchanged. `None` layout
        // (never computed) is likewise `None`.
        let s = strip(vec![plain_tab("only", true)]);
        let layout = compute_split_layout(&s, 21, 10).expect("one-pane layout");
        assert_eq!(layout.panes.len(), 1);
        assert_eq!(focused_pane_region(None, Some(&layout)), None);
        assert_eq!(focused_pane_region(Some("sid-only"), Some(&layout)), None);
        assert_eq!(focused_pane_region(None, None), None);
    }

    #[test]
    fn focus_indicator_marks_active_root_and_split_child_panes() {
        // A two-pane right-split: `src` is the active/root pane, `child` the split child. With no focus
        // set the indicator falls back to the active/root pane; focusing the child marks the child pane;
        // focusing the active pane's own session also resolves to it. Each resolves to that pane's region.
        let tabs = vec![
            plain_tab("src", true),
            split_child("child", "src", RendererTabSplitAxis::Right, false),
        ];
        let layout = compute_split_layout(&strip(tabs), 21, 10).expect("two-pane layout");
        let src_region = layout
            .panes
            .iter()
            .find(|p| p.session_id == "sid-src")
            .expect("src pane")
            .region;
        let child_region = layout
            .panes
            .iter()
            .find(|p| p.session_id == "sid-child")
            .expect("child pane")
            .region;
        assert_ne!(
            src_region, child_region,
            "split panes occupy distinct regions"
        );
        // No focus -> active/root pane.
        assert_eq!(focused_pane_region(None, Some(&layout)), Some(src_region));
        // Focus the active pane's own session -> same active region.
        assert_eq!(
            focused_pane_region(Some("sid-src"), Some(&layout)),
            Some(src_region)
        );
        // Focus the split child -> the child's region.
        assert_eq!(
            focused_pane_region(Some("sid-child"), Some(&layout)),
            Some(child_region)
        );
    }

    #[test]
    fn focus_indicator_marks_only_the_focused_nested_pane() {
        // Three panes: src (left), mid (top-right), bot (bottom-right, active). Focusing the nested
        // `mid` pane marks ONLY the mid region — not src, not bot. The region is exactly mid's region.
        let tabs = vec![
            plain_tab("src", false),
            split_child("mid", "src", RendererTabSplitAxis::Right, false),
            split_child("bot", "mid", RendererTabSplitAxis::Down, true),
        ];
        let layout = compute_split_layout(&strip(tabs), 21, 10).expect("three-pane layout");
        assert_eq!(layout.panes.len(), 3);
        let mid_region = layout
            .panes
            .iter()
            .find(|p| p.session_id == "sid-mid")
            .expect("mid pane")
            .region;
        let resolved = focused_pane_region(Some("sid-mid"), Some(&layout)).expect("mid indicator");
        assert_eq!(resolved, mid_region);
        // It is exactly the mid region and not src's or bot's.
        for other in ["sid-src", "sid-bot"] {
            let r = layout
                .panes
                .iter()
                .find(|p| p.session_id == other)
                .expect("pane")
                .region;
            assert_ne!(resolved, r, "indicator must not land on {other}");
        }
    }

    #[test]
    fn focus_indicator_stale_focus_falls_back_to_active_root_pane() {
        // Focus pointing at a session that is no longer a pane in the live layout degrades to the
        // ACTIVE pane's region (mirroring `focused_session_write_target`), never a vanished pane.
        let tabs = vec![
            plain_tab("src", false),
            split_child("child", "src", RendererTabSplitAxis::Right, true),
        ];
        let layout = compute_split_layout(&strip(tabs), 21, 10).expect("two-pane layout");
        let active_region = layout
            .panes
            .iter()
            .find(|p| p.active)
            .expect("active pane")
            .region;
        assert_eq!(
            focused_pane_region(Some("sid-gone"), Some(&layout)),
            Some(active_region)
        );
    }

    #[test]
    fn focus_indicator_moves_to_remaining_pane_when_focused_leaf_closes() {
        // Closing the focused leaf removes its pane from the layout: the indicator no longer resolves to
        // the closed session and instead lands on the active/root pane that remains. Model the close by
        // recomputing the layout from a strip with the closed child dropped, keeping the same stale focus.
        let before = vec![
            plain_tab("src", false),
            split_child("child", "src", RendererTabSplitAxis::Right, true),
        ];
        let layout_before = compute_split_layout(&strip(before), 21, 10).expect("two-pane layout");
        let child_region = layout_before
            .panes
            .iter()
            .find(|p| p.session_id == "sid-child")
            .expect("child pane")
            .region;
        // Focused on the child while it exists -> the child region.
        assert_eq!(
            focused_pane_region(Some("sid-child"), Some(&layout_before)),
            Some(child_region)
        );
        // Close the child leaf: the surviving `src` is now the lone active pane (no split).
        let after = vec![plain_tab("src", true)];
        let layout_after = compute_split_layout(&strip(after), 21, 10).expect("one-pane layout");
        // Single remaining pane -> no split chrome at all (indicator clears).
        assert_eq!(
            focused_pane_region(Some("sid-child"), Some(&layout_after)),
            None
        );
    }

    // --- keyboard pane-focus navigation: shortcut matcher + directional neighbor ---

    #[test]
    fn pane_focus_shortcut_accepts_only_the_intended_modifier_arrow_chords() {
        use crate::host_event::{HostKey, HostNamedKey};
        use crate::host_mods;
        let up = HostKey::Named(HostNamedKey::ArrowUp);
        let down = HostKey::Named(HostNamedKey::ArrowDown);
        let left = HostKey::Named(HostNamedKey::ArrowLeft);
        let right = HostKey::Named(HostNamedKey::ArrowRight);
        let super_alt = host_mods(false, true, false, true);
        let ctrl_alt = host_mods(true, true, false, false);
        // macOS chord (Cmd+Option+Arrow) and other-platform chord (Ctrl+Alt+Arrow) both map each arrow.
        assert_eq!(
            pane_focus_shortcut_matches(&up, &super_alt),
            Some(PaneFocusDirection::Up)
        );
        assert_eq!(
            pane_focus_shortcut_matches(&down, &ctrl_alt),
            Some(PaneFocusDirection::Down)
        );
        assert_eq!(
            pane_focus_shortcut_matches(&left, &super_alt),
            Some(PaneFocusDirection::Left)
        );
        assert_eq!(
            pane_focus_shortcut_matches(&right, &ctrl_alt),
            Some(PaneFocusDirection::Right)
        );
        // Plain arrow -> no match (ordinary terminal input untouched).
        assert_eq!(
            pane_focus_shortcut_matches(&up, &host_mods(false, false, false, false)),
            None
        );
        // Missing the alt half of the chord -> no match.
        assert_eq!(
            pane_focus_shortcut_matches(&up, &host_mods(false, false, false, true)),
            None
        );
        assert_eq!(
            pane_focus_shortcut_matches(&up, &host_mods(true, false, false, false)),
            None
        );
        // Both platform-chord keys held (super AND control) -> ambiguous, no match.
        assert_eq!(
            pane_focus_shortcut_matches(&up, &host_mods(true, true, false, true)),
            None
        );
        // Shift is reserved -> no match even with an otherwise-valid chord.
        assert_eq!(
            pane_focus_shortcut_matches(&up, &host_mods(false, true, true, true)),
            None
        );
        // A non-arrow key never matches.
        assert_eq!(
            pane_focus_shortcut_matches(&HostKey::Character("a".to_string()), &super_alt),
            None
        );
    }

    #[test]
    fn pane_focus_no_split_produces_no_movement() {
        // A single (unsplit) active tab yields a one-pane layout; no neighbor exists in any direction.
        let s = strip(vec![plain_tab("only", true)]);
        let layout = compute_split_layout(&s, 21, 10).expect("one-pane layout");
        for dir in [
            PaneFocusDirection::Up,
            PaneFocusDirection::Down,
            PaneFocusDirection::Left,
            PaneFocusDirection::Right,
        ] {
            assert!(pane_neighbor_in_direction(&layout, None, dir).is_none());
            assert!(pane_neighbor_in_direction(&layout, Some("sid-only"), dir).is_none());
        }
    }

    #[test]
    fn pane_focus_two_pane_right_and_down_move_in_expected_direction() {
        // Right split: src (left) | child (right). Moving Right from the active src lands on the child;
        // moving Left from the child returns to src. Up/Down find no neighbor (same row band).
        let right = compute_split_layout(
            &strip(vec![
                plain_tab("src", true),
                split_child("child", "src", RendererTabSplitAxis::Right, false),
            ]),
            21,
            10,
        )
        .expect("right layout");
        assert_eq!(
            pane_neighbor_in_direction(&right, None, PaneFocusDirection::Right)
                .map(|p| p.session_id.as_str()),
            Some("sid-child")
        );
        assert_eq!(
            pane_neighbor_in_direction(&right, Some("sid-child"), PaneFocusDirection::Left)
                .map(|p| p.session_id.as_str()),
            Some("sid-src")
        );
        assert!(
            pane_neighbor_in_direction(&right, None, PaneFocusDirection::Up).is_none(),
            "no vertical neighbor in a pure right split"
        );

        // Down split: src (top) over child (bottom). Moving Down from src lands on the child; Up returns.
        let down = compute_split_layout(
            &strip(vec![
                plain_tab("src", true),
                split_child("child", "src", RendererTabSplitAxis::Down, false),
            ]),
            21,
            10,
        )
        .expect("down layout");
        assert_eq!(
            pane_neighbor_in_direction(&down, None, PaneFocusDirection::Down)
                .map(|p| p.session_id.as_str()),
            Some("sid-child")
        );
        assert_eq!(
            pane_neighbor_in_direction(&down, Some("sid-child"), PaneFocusDirection::Up)
                .map(|p| p.session_id.as_str()),
            Some("sid-src")
        );
    }

    #[test]
    fn pane_focus_nested_layout_chooses_nearest_directional_neighbor() {
        // src (left, full height) | [ mid (top-right) over bot (bottom-right) ]. Each tab carries at most
        // one split child, so this 3-pane chain is the canonical nested layout. The directional metric
        // resolves the nearest neighbor along each axis:
        //   - From mid (top-right), Down lands on bot; from bot, Up returns to mid (vertical neighbors).
        //   - From bot/mid, Left lands on src (the only pane on the left).
        //   - From src, Right has two right-side candidates at equal primary distance; the nearest by
        //     perpendicular center distance wins (bot, whose center row sits closest to src's mid-height).
        let layout = compute_split_layout(
            &strip(vec![
                plain_tab("src", true),
                split_child("mid", "src", RendererTabSplitAxis::Right, false),
                split_child("bot", "mid", RendererTabSplitAxis::Down, false),
            ]),
            21,
            10,
        )
        .expect("nested layout");
        // Vertical neighbors inside the right column resolve unambiguously.
        assert_eq!(
            pane_neighbor_in_direction(&layout, Some("sid-mid"), PaneFocusDirection::Down)
                .map(|p| p.session_id.as_str()),
            Some("sid-bot")
        );
        assert_eq!(
            pane_neighbor_in_direction(&layout, Some("sid-bot"), PaneFocusDirection::Up)
                .map(|p| p.session_id.as_str()),
            Some("sid-mid")
        );
        // Left from either right pane lands on the sole left pane.
        assert_eq!(
            pane_neighbor_in_direction(&layout, Some("sid-mid"), PaneFocusDirection::Left)
                .map(|p| p.session_id.as_str()),
            Some("sid-src")
        );
        assert_eq!(
            pane_neighbor_in_direction(&layout, Some("sid-bot"), PaneFocusDirection::Left)
                .map(|p| p.session_id.as_str()),
            Some("sid-src")
        );
        // Right from the full-height left pane picks the nearest-by-center right pane.
        assert_eq!(
            pane_neighbor_in_direction(&layout, Some("sid-src"), PaneFocusDirection::Right)
                .map(|p| p.session_id.as_str()),
            Some("sid-bot")
        );
    }

    #[test]
    fn pane_focus_stale_focus_starts_from_active_root_pane() {
        // Focus pointing at a vanished session resolves the source to the ACTIVE pane, so a Right move
        // from a stale focus behaves like a Right move from the active src.
        let layout = compute_split_layout(
            &strip(vec![
                plain_tab("src", true),
                split_child("child", "src", RendererTabSplitAxis::Right, false),
            ]),
            21,
            10,
        )
        .expect("right layout");
        assert_eq!(
            pane_neighbor_in_direction(&layout, Some("sid-gone"), PaneFocusDirection::Right)
                .map(|p| p.session_id.as_str()),
            Some("sid-child")
        );
    }

    #[test]
    fn pane_focus_no_neighbor_direction_leaves_focus_unchanged() {
        // Right split: from the right child there is no pane further Right, and none Up/Down -> None
        // (the caller treats None as a no-op, leaving focus unchanged).
        let layout = compute_split_layout(
            &strip(vec![
                plain_tab("src", true),
                split_child("child", "src", RendererTabSplitAxis::Right, false),
            ]),
            21,
            10,
        )
        .expect("right layout");
        for dir in [
            PaneFocusDirection::Right,
            PaneFocusDirection::Up,
            PaneFocusDirection::Down,
        ] {
            assert!(
                pane_neighbor_in_direction(&layout, Some("sid-child"), dir).is_none(),
                "no neighbor from the right child going {dir:?}"
            );
        }
    }

    #[test]
    fn focus_cycle_shortcut_accepts_only_the_intended_modifier_bracket_chords() {
        use crate::host_event::{HostKey, HostNamedKey};
        use crate::host_mods;
        let next = HostKey::Character("]".to_string());
        let prev = HostKey::Character("[".to_string());
        let super_alt = host_mods(false, true, false, true);
        let ctrl_alt = host_mods(true, true, false, false);
        // macOS chord (Cmd+Option+]/[) and other-platform chord (Ctrl+Alt+]/[) both map each bracket.
        assert_eq!(
            focus_cycle_shortcut_matches(&next, &super_alt),
            Some(PaneCycleDirection::Next)
        );
        assert_eq!(
            focus_cycle_shortcut_matches(&next, &ctrl_alt),
            Some(PaneCycleDirection::Next)
        );
        assert_eq!(
            focus_cycle_shortcut_matches(&prev, &super_alt),
            Some(PaneCycleDirection::Previous)
        );
        assert_eq!(
            focus_cycle_shortcut_matches(&prev, &ctrl_alt),
            Some(PaneCycleDirection::Previous)
        );
        // Plain bracket -> no match (ordinary terminal input untouched).
        assert_eq!(
            focus_cycle_shortcut_matches(&next, &host_mods(false, false, false, false)),
            None
        );
        // Missing the alt half of the chord -> no match.
        assert_eq!(
            focus_cycle_shortcut_matches(&next, &host_mods(false, false, false, true)),
            None
        );
        assert_eq!(
            focus_cycle_shortcut_matches(&next, &host_mods(true, false, false, false)),
            None
        );
        // Both platform-chord keys held (super AND control) -> ambiguous, no match.
        assert_eq!(
            focus_cycle_shortcut_matches(&next, &host_mods(true, true, false, true)),
            None
        );
        // Shift is reserved -> no match even with an otherwise-valid chord.
        assert_eq!(
            focus_cycle_shortcut_matches(&next, &host_mods(false, true, true, true)),
            None
        );
        // A non-bracket key never matches.
        assert_eq!(
            focus_cycle_shortcut_matches(&HostKey::Character("a".to_string()), &super_alt),
            None
        );
        assert_eq!(
            focus_cycle_shortcut_matches(&HostKey::Named(HostNamedKey::Enter), &super_alt),
            None
        );
    }

    #[test]
    fn focus_cycle_no_split_produces_no_movement() {
        // A single (unsplit) active tab yields a one-pane layout; cycling either direction is a no-op.
        let s = strip(vec![plain_tab("only", true)]);
        let layout = compute_split_layout(&s, 21, 10).expect("one-pane layout");
        for dir in [PaneCycleDirection::Next, PaneCycleDirection::Previous] {
            assert!(pane_cycle_target(&layout, None, dir).is_none());
            assert!(pane_cycle_target(&layout, Some("sid-only"), dir).is_none());
        }
    }

    #[test]
    fn focus_cycle_two_pane_layout_cycles_between_both_panes() {
        // Right split: panes in stable order are [src, child]. Next/Previous both swap between the two,
        // wrapping at each end.
        let layout = compute_split_layout(
            &strip(vec![
                plain_tab("src", true),
                split_child("child", "src", RendererTabSplitAxis::Right, false),
            ]),
            21,
            10,
        )
        .expect("right layout");
        // From the active src, Next -> child, Previous -> child (wrap).
        assert_eq!(
            pane_cycle_target(&layout, None, PaneCycleDirection::Next)
                .map(|p| p.session_id.as_str()),
            Some("sid-child")
        );
        assert_eq!(
            pane_cycle_target(&layout, None, PaneCycleDirection::Previous)
                .map(|p| p.session_id.as_str()),
            Some("sid-child")
        );
        // From the child, Next -> src (wrap), Previous -> src.
        assert_eq!(
            pane_cycle_target(&layout, Some("sid-child"), PaneCycleDirection::Next)
                .map(|p| p.session_id.as_str()),
            Some("sid-src")
        );
        assert_eq!(
            pane_cycle_target(&layout, Some("sid-child"), PaneCycleDirection::Previous)
                .map(|p| p.session_id.as_str()),
            Some("sid-src")
        );
    }

    #[test]
    fn focus_cycle_nested_three_pane_layout_traverses_every_pane_and_wraps() {
        // src | [ mid over bot ]. The stable pane order is the split chain: [src, mid, bot].
        let layout = compute_split_layout(
            &strip(vec![
                plain_tab("src", true),
                split_child("mid", "src", RendererTabSplitAxis::Right, false),
                split_child("bot", "mid", RendererTabSplitAxis::Down, false),
            ]),
            21,
            10,
        )
        .expect("nested layout");
        let order = ["sid-src", "sid-mid", "sid-bot"];
        // Next walks the full ring src -> mid -> bot -> src, visiting every pane and wrapping.
        let mut from: Option<&str> = None; // None resolves to the active (src) pane.
        for step in 0..order.len() + 1 {
            let expected = order[(step + 1) % order.len()];
            let landed = pane_cycle_target(&layout, from, PaneCycleDirection::Next)
                .map(|p| p.session_id.clone())
                .expect("next pane exists");
            assert_eq!(landed, expected, "Next step {step}");
            from = Some(Box::leak(landed.into_boxed_str()));
        }
        // Previous walks the ring backwards from src: bot -> mid -> src -> bot.
        let prev_order = ["sid-bot", "sid-mid", "sid-src", "sid-bot"];
        let mut from: Option<&str> = None;
        for (step, expected) in prev_order.iter().enumerate() {
            let landed = pane_cycle_target(&layout, from, PaneCycleDirection::Previous)
                .map(|p| p.session_id.clone())
                .expect("previous pane exists");
            assert_eq!(&landed, expected, "Previous step {step}");
            from = Some(Box::leak(landed.into_boxed_str()));
        }
    }

    #[test]
    fn focus_cycle_stale_focus_starts_from_active_root_pane() {
        // Focus pointing at a vanished session resolves the source to the ACTIVE pane (src), so Next
        // lands on the pane after src in stable order.
        let layout = compute_split_layout(
            &strip(vec![
                plain_tab("src", true),
                split_child("child", "src", RendererTabSplitAxis::Right, false),
            ]),
            21,
            10,
        )
        .expect("right layout");
        assert_eq!(
            pane_cycle_target(&layout, Some("sid-gone"), PaneCycleDirection::Next)
                .map(|p| p.session_id.as_str()),
            Some("sid-child")
        );
        assert_eq!(
            pane_cycle_target(&layout, Some("sid-gone"), PaneCycleDirection::Previous)
                .map(|p| p.session_id.as_str()),
            Some("sid-child")
        );
    }

    // Region of the pane with `session_id` in `layout`, for inactive-dim assertions.
    fn region_of(layout: &RendererSplitLayout, session_id: &str) -> Option<RendererPaneRegion> {
        layout
            .panes
            .iter()
            .find(|p| p.session_id == session_id)
            .map(|p| p.region)
    }

    #[test]
    fn inactive_dim_no_split_produces_no_overlay() {
        // A single (unsplit) active tab yields a one-pane layout; nothing is dimmed.
        let s = strip(vec![plain_tab("only", true)]);
        let layout = compute_split_layout(&s, 21, 10).expect("one-pane layout");
        assert!(inactive_pane_regions(None, Some(&layout)).is_empty());
        assert!(inactive_pane_regions(Some("sid-only"), Some(&layout)).is_empty());
        // A missing layout also dims nothing.
        assert!(inactive_pane_regions(None, None).is_empty());
    }

    #[test]
    fn inactive_dim_two_pane_dims_only_the_non_focused_pane() {
        // Right split: panes [src (active), child]. With default focus the active src is focused, so only
        // the child dims; focusing the child flips it so only src dims.
        let layout = compute_split_layout(
            &strip(vec![
                plain_tab("src", true),
                split_child("child", "src", RendererTabSplitAxis::Right, false),
            ]),
            21,
            10,
        )
        .expect("right layout");
        // Default focus (None) -> active src focused -> only the child is dimmed.
        assert_eq!(
            inactive_pane_regions(None, Some(&layout)),
            vec![region_of(&layout, "sid-child").unwrap()]
        );
        // Focus the child -> only src is dimmed.
        assert_eq!(
            inactive_pane_regions(Some("sid-child"), Some(&layout)),
            vec![region_of(&layout, "sid-src").unwrap()]
        );
    }

    #[test]
    fn inactive_dim_nested_three_pane_dims_every_pane_except_focused() {
        // src | [ mid over bot ]. Focusing mid dims exactly src and bot (in stable layout order).
        let layout = compute_split_layout(
            &strip(vec![
                plain_tab("src", true),
                split_child("mid", "src", RendererTabSplitAxis::Right, false),
                split_child("bot", "mid", RendererTabSplitAxis::Down, false),
            ]),
            21,
            10,
        )
        .expect("nested layout");
        let dims = inactive_pane_regions(Some("sid-mid"), Some(&layout));
        // Exactly the two non-focused panes, and never the focused pane's region.
        assert_eq!(dims.len(), 2);
        assert!(dims.contains(&region_of(&layout, "sid-src").unwrap()));
        assert!(dims.contains(&region_of(&layout, "sid-bot").unwrap()));
        assert!(!dims.contains(&region_of(&layout, "sid-mid").unwrap()));
    }

    #[test]
    fn inactive_dim_stale_focus_dims_relative_to_active_root_fallback() {
        // A focus session that names no pane falls back to the active/root pane (src), so the dim set is
        // identical to the default-focus case: only the child dims.
        let layout = compute_split_layout(
            &strip(vec![
                plain_tab("src", true),
                split_child("child", "src", RendererTabSplitAxis::Right, false),
            ]),
            21,
            10,
        )
        .expect("right layout");
        assert_eq!(
            inactive_pane_regions(Some("sid-gone"), Some(&layout)),
            inactive_pane_regions(None, Some(&layout))
        );
        assert_eq!(
            inactive_pane_regions(Some("sid-gone"), Some(&layout)),
            vec![region_of(&layout, "sid-child").unwrap()]
        );
    }

    #[test]
    fn inactive_dim_zoomed_pane_has_no_overlay() {
        // While zoomed the caller passes the COLLAPSED single-pane layout (built here via
        // `zoom_collapsed_layout`), which is len() < 2, so the zoomed full-window pane is never dimmed.
        let full = compute_split_layout(
            &strip(vec![
                plain_tab("src", true),
                split_child("child", "src", RendererTabSplitAxis::Right, false),
            ]),
            21,
            10,
        )
        .expect("right layout");
        let collapsed = zoom_collapsed_layout(&full, "sid-child").expect("collapsed layout");
        assert_eq!(collapsed.panes.len(), 1);
        assert!(inactive_pane_regions(Some("sid-child"), Some(&collapsed)).is_empty());
        assert!(inactive_pane_regions(None, Some(&collapsed)).is_empty());
    }

    #[test]
    fn inactive_dim_planning_does_not_mutate_pane_or_focus_geometry() {
        // The planner returns COPIES of pane regions and leaves both the layout and the focus-border
        // (focused_pane_region) geometry unchanged across the call.
        let layout = compute_split_layout(
            &strip(vec![
                plain_tab("src", true),
                split_child("mid", "src", RendererTabSplitAxis::Right, false),
                split_child("bot", "mid", RendererTabSplitAxis::Down, false),
            ]),
            21,
            10,
        )
        .expect("nested layout");
        let before = layout.clone();
        let focus_before = focused_pane_region(Some("sid-bot"), Some(&layout));
        let dims = inactive_pane_regions(Some("sid-bot"), Some(&layout));
        // The layout and the focus-border region are untouched by planning.
        assert_eq!(layout, before);
        assert_eq!(
            focused_pane_region(Some("sid-bot"), Some(&layout)),
            focus_before
        );
        // The dimmed regions are exactly the panes other than the focused one, and the focused pane's
        // region is excluded (so the focus border is never under a dim quad).
        assert_eq!(dims.len(), 2);
        assert!(!dims.contains(&focus_before.unwrap()));
    }

    #[test]
    fn reset_ratio_shortcut_accepts_only_the_intended_modifier_zero_chord() {
        use crate::host_event::HostKey;
        use crate::host_mods;
        let zero = HostKey::Character("0".to_string());
        let super_alt = host_mods(false, true, false, true);
        let ctrl_alt = host_mods(true, true, false, false);
        // Both platform chords match on `0`.
        assert!(reset_split_ratio_shortcut_matches(&zero, &super_alt));
        assert!(reset_split_ratio_shortcut_matches(&zero, &ctrl_alt));
        // Plain `0` and single-modifier `0` do NOT match (must reach the PTY / not collide).
        assert!(!reset_split_ratio_shortcut_matches(
            &zero,
            &host_mods(false, false, false, false)
        ));
        assert!(!reset_split_ratio_shortcut_matches(
            &zero,
            &host_mods(false, false, false, true)
        ));
        assert!(!reset_split_ratio_shortcut_matches(
            &zero,
            &host_mods(true, false, false, false)
        ));
        assert!(!reset_split_ratio_shortcut_matches(
            &zero,
            &host_mods(false, true, false, false)
        ));
        // Both super AND control held is not the chord (XOR requires exactly one).
        assert!(!reset_split_ratio_shortcut_matches(
            &zero,
            &host_mods(true, true, false, true)
        ));
        // Shift is forbidden (keeps the chord unambiguous; `)` never resets).
        assert!(!reset_split_ratio_shortcut_matches(
            &zero,
            &host_mods(false, true, true, true)
        ));
        // A non-`0` key never matches even with the right chord.
        assert!(!reset_split_ratio_shortcut_matches(
            &HostKey::Character("1".to_string()),
            &super_alt
        ));
    }

    #[test]
    fn reset_no_split_produces_no_target() {
        // A lone tab has no split, so there is nothing to reset (the caller treats None as a no-op).
        let strip = strip(vec![plain_tab("solo", true)]);
        assert_eq!(focused_split_child_to_reset(&strip, None), None);
        assert_eq!(focused_split_child_to_reset(&strip, Some("sid-solo")), None);
    }

    #[test]
    fn reset_focused_split_child_resets_its_own_persisted_ratio() {
        // Focus on the split child resolves the child itself; even-resetting it drops its ratio to 0.5.
        let strip = strip(vec![
            plain_tab("src", true),
            split_child("child", "src", RendererTabSplitAxis::Right, false),
        ]);
        let child = focused_split_child_to_reset(&strip, Some("sid-child")).expect("child target");
        assert_eq!(child, "child");
        let mut ratios = SplitRatios::default();
        ratios.set_first_share(child, 0.8);
        assert!((ratios.first_share(child) - 0.8).abs() < 1e-6);
        ratios.set_first_share(child, DEFAULT_SPLIT_RATIO);
        assert_eq!(ratios.first_share(child), DEFAULT_SPLIT_RATIO);
        assert_eq!(first_share_to_per_mille(DEFAULT_SPLIT_RATIO), 500);
    }

    #[test]
    fn reset_focused_split_parent_resets_its_child_split() {
        // Focus on the PARENT (the active root) resolves to its child's divider — resetting the parent
        // resets the child split it owns.
        let strip = strip(vec![
            plain_tab("src", true),
            split_child("child", "src", RendererTabSplitAxis::Right, false),
        ]);
        // No focus (None) falls back to the active/root tab `src`, which owns `child`.
        assert_eq!(focused_split_child_to_reset(&strip, None), Some("child"));
        // Explicit focus on the parent session resolves the same child.
        assert_eq!(
            focused_split_child_to_reset(&strip, Some("sid-src")),
            Some("child")
        );
    }

    #[test]
    fn reset_nested_split_resets_only_the_focused_local_split() {
        // src (left) | [ mid (top-right) over bot (bottom-right) ]. Focusing `mid` (a child AND the
        // parent of `bot`) resolves `mid`'s OWN divider, not `bot`'s — the local split, never a
        // descendant. Focusing `bot` resolves `bot`; focusing the root `src` resolves its first child
        // `mid`, not the nested `bot`.
        let strip = strip(vec![
            plain_tab("src", true),
            split_child("mid", "src", RendererTabSplitAxis::Right, false),
            split_child("bot", "mid", RendererTabSplitAxis::Down, false),
        ]);
        assert_eq!(
            focused_split_child_to_reset(&strip, Some("sid-mid")),
            Some("mid")
        );
        assert_eq!(
            focused_split_child_to_reset(&strip, Some("sid-bot")),
            Some("bot")
        );
        assert_eq!(
            focused_split_child_to_reset(&strip, Some("sid-src")),
            Some("mid")
        );
    }

    #[test]
    fn reset_stale_focus_falls_back_to_the_active_root_split() {
        // A focus naming a vanished session falls back to the active/root tab, whose child split resets.
        let strip = strip(vec![
            plain_tab("src", true),
            split_child("child", "src", RendererTabSplitAxis::Right, false),
        ]);
        assert_eq!(
            focused_split_child_to_reset(&strip, Some("sid-ghost")),
            Some("child")
        );
    }

    #[test]
    fn resize_shortcut_accepts_only_the_intended_modifier_shift_arrow_chords() {
        use crate::host_event::{HostKey, HostNamedKey};
        use crate::host_mods;
        let right = HostKey::Named(HostNamedKey::ArrowRight);
        let up = HostKey::Named(HostNamedKey::ArrowUp);
        let super_alt_shift = host_mods(false, true, true, true);
        let ctrl_alt_shift = host_mods(true, true, true, false);
        // Both platform chords (with shift) match and carry the arrow's direction.
        assert_eq!(
            resize_split_shortcut_matches(&right, &super_alt_shift),
            Some(PaneFocusDirection::Right)
        );
        assert_eq!(
            resize_split_shortcut_matches(&up, &ctrl_alt_shift),
            Some(PaneFocusDirection::Up)
        );
        // WITHOUT shift this is the focus chord, not a resize — must NOT match (keeps the two distinct).
        assert_eq!(
            resize_split_shortcut_matches(&right, &host_mods(false, true, false, true)),
            None
        );
        // Plain arrow and partial chords do NOT match (ordinary arrows reach the PTY).
        assert_eq!(
            resize_split_shortcut_matches(&right, &host_mods(false, false, false, false)),
            None
        );
        assert_eq!(
            resize_split_shortcut_matches(&right, &host_mods(false, false, true, false)),
            None
        );
        assert_eq!(
            resize_split_shortcut_matches(&right, &host_mods(false, true, true, false)),
            None
        );
        // Both super AND control held is not the chord (XOR requires exactly one).
        assert_eq!(
            resize_split_shortcut_matches(&right, &host_mods(true, true, true, true)),
            None
        );
        // A non-arrow key never matches even with the full chord.
        assert_eq!(
            resize_split_shortcut_matches(&HostKey::Character("a".to_string()), &super_alt_shift),
            None
        );
    }

    #[test]
    fn shortcut_hint_toggle_accepts_only_the_intended_modifier_slash_chord() {
        use crate::host_event::{HostKey, HostNamedKey};
        use crate::host_mods;
        let slash = HostKey::Character("/".to_string());
        let super_alt = host_mods(false, true, false, true);
        let ctrl_alt = host_mods(true, true, false, false);
        // Both platform chords match on `/`.
        assert!(shortcut_hint_toggle_matches(&slash, &super_alt));
        assert!(shortcut_hint_toggle_matches(&slash, &ctrl_alt));
        // Plain `/` and single-modifier `/` do NOT match (must reach the PTY / shell).
        assert!(!shortcut_hint_toggle_matches(
            &slash,
            &host_mods(false, false, false, false)
        ));
        assert!(!shortcut_hint_toggle_matches(
            &slash,
            &host_mods(false, false, false, true)
        ));
        assert!(!shortcut_hint_toggle_matches(
            &slash,
            &host_mods(true, false, false, false)
        ));
        assert!(!shortcut_hint_toggle_matches(
            &slash,
            &host_mods(false, true, false, false)
        ));
        // Both super AND control held is not the chord (XOR requires exactly one).
        assert!(!shortcut_hint_toggle_matches(
            &slash,
            &host_mods(true, true, false, true)
        ));
        // Shift is forbidden, so `?` (shift+`/`) never toggles — it still reaches the shell.
        assert!(!shortcut_hint_toggle_matches(
            &slash,
            &host_mods(false, true, true, true)
        ));
        // A non-`/` key never matches even with the right chord, and `?` typed as its own character
        // (already-shifted logical key) is not `/` so it never matches either.
        assert!(!shortcut_hint_toggle_matches(
            &HostKey::Character("?".to_string()),
            &super_alt
        ));
        assert!(!shortcut_hint_toggle_matches(
            &HostKey::Named(HostNamedKey::Enter),
            &super_alt
        ));
    }

    #[test]
    fn shortcut_hint_overlay_lines_are_bounded_and_list_the_split_controls() {
        let lines = compose_shortcut_hint_overlay_lines();
        // Bounded well under the cap, and never empty (always at least the title + the controls).
        assert!(!lines.is_empty());
        assert!(lines.len() <= SHORTCUT_HINT_OVERLAY_MAX_ROWS);
        // The first line is the non-selectable title; every line is non-selectable (display-only).
        assert_eq!(lines[0].text, "Split-pane shortcuts");
        assert!(lines.iter().all(|l| !l.selectable && !l.selected));
        // The expected split controls are each named somewhere in the overlay (case-insensitive).
        let blob = lines
            .iter()
            .map(|l| l.text.to_lowercase())
            .collect::<Vec<_>>()
            .join("\n");
        for needle in [
            "split right",
            "split down",
            "close focused pane",
            "focus pane",
            "cycle focus",
            "drag resize",
            "keyboard resize",
            "reset divider ratio",
            "zoom",
        ] {
            assert!(
                blob.contains(needle),
                "overlay is missing the {needle:?} control: {blob}"
            );
        }
    }

    #[test]
    fn resize_nudge_delta_matches_axis_and_is_a_no_op_off_axis() {
        // A Right split only responds to horizontal arrows: Right grows the first (left) pane, Left
        // shrinks it; Up/Down are no-ops.
        assert_eq!(
            split_ratio_nudge_delta(RendererTabSplitAxis::Right, PaneFocusDirection::Right),
            Some(RESIZE_RATIO_STEP)
        );
        assert_eq!(
            split_ratio_nudge_delta(RendererTabSplitAxis::Right, PaneFocusDirection::Left),
            Some(-RESIZE_RATIO_STEP)
        );
        assert_eq!(
            split_ratio_nudge_delta(RendererTabSplitAxis::Right, PaneFocusDirection::Up),
            None
        );
        assert_eq!(
            split_ratio_nudge_delta(RendererTabSplitAxis::Right, PaneFocusDirection::Down),
            None
        );
        // A Down split only responds to vertical arrows: Down grows the first (top) pane, Up shrinks it;
        // Left/Right are no-ops.
        assert_eq!(
            split_ratio_nudge_delta(RendererTabSplitAxis::Down, PaneFocusDirection::Down),
            Some(RESIZE_RATIO_STEP)
        );
        assert_eq!(
            split_ratio_nudge_delta(RendererTabSplitAxis::Down, PaneFocusDirection::Up),
            Some(-RESIZE_RATIO_STEP)
        );
        assert_eq!(
            split_ratio_nudge_delta(RendererTabSplitAxis::Down, PaneFocusDirection::Left),
            None
        );
        assert_eq!(
            split_ratio_nudge_delta(RendererTabSplitAxis::Down, PaneFocusDirection::Right),
            None
        );
    }

    #[test]
    fn resize_nudge_moves_the_first_side_ratio_and_drives_geometry() {
        // src (left) | child (right), a Right split on a 21x10 grid (one divider column). A Right nudge
        // grows the first (left) column by one step; the resulting per-mille flows through the existing
        // frame computation, so the left column widens and the right narrows by the same amount.
        let tabs = vec![
            plain_tab("src", false),
            split_child("child", "src", RendererTabSplitAxis::Right, true),
        ];
        let s = strip(tabs);
        let child = focused_split_child_to_reset(&s, Some("sid-child")).expect("child target");
        assert_eq!(child, "child");

        let mut ratios = SplitRatios::default();
        let before = ratios.first_share(child); // DEFAULT_SPLIT_RATIO
        let delta = split_ratio_nudge_delta(RendererTabSplitAxis::Right, PaneFocusDirection::Right)
            .expect("on-axis delta");
        ratios.set_first_share(child, before + delta);
        let after = ratios.first_share(child);
        assert!(after > before);
        assert_eq!(first_share_to_per_mille(after), 550);

        let nudged = compute_split_frame_with(&s.tabs, child, 21, 10, &ratios).expect("frame");
        // 0.55 of the 20 splittable columns = 11 left, 9 right (one column is the divider).
        assert_eq!(nudged.first.cols, 11);
        assert_eq!(nudged.second.cols, 21 - 1 - 11);
    }

    #[test]
    fn resize_nudge_clamps_at_the_existing_ratio_band() {
        // Repeated nudges toward one side never push the first share past the usable band; the per-mille
        // saturates at the clamp bound (MIN_SPLIT_RATIO from the other side), and a further nudge in the
        // same direction is a no-op (the clamped value does not move).
        let child = "child";
        let mut ratios = SplitRatios::default();
        let delta = split_ratio_nudge_delta(RendererTabSplitAxis::Right, PaneFocusDirection::Left)
            .expect("on-axis delta");
        // Drive it down repeatedly; it saturates at MIN_SPLIT_RATIO.
        for _ in 0..50 {
            let cur = ratios.first_share(child);
            ratios.set_first_share(child, cur + delta);
        }
        let floored = ratios.first_share(child);
        assert!((floored - MIN_SPLIT_RATIO).abs() < 1e-6);
        // One more nudge in the same direction does not move the clamped value (the App treats an
        // unchanged share as a no-op).
        ratios.set_first_share(child, floored + delta);
        assert!((ratios.first_share(child) - floored).abs() <= f32::EPSILON);
    }

    #[test]
    fn resize_nested_nudge_resolves_only_the_focused_local_split() {
        // src --Right--> mid --Down--> bot. Focusing `bot` resolves `bot`'s OWN (Down) divider; its axis
        // is Down, so a vertical nudge applies and a horizontal one is an off-axis no-op. The root Right
        // split (`mid`) is never the resolved target when `bot` is focused.
        let s = strip(vec![
            plain_tab("src", true),
            split_child("mid", "src", RendererTabSplitAxis::Right, false),
            split_child("bot", "mid", RendererTabSplitAxis::Down, false),
        ]);
        let child = focused_split_child_to_reset(&s, Some("sid-bot")).expect("child target");
        assert_eq!(child, "bot");
        let axis = s
            .tabs
            .iter()
            .find(|t| t.tab_id == child)
            .and_then(|t| t.split)
            .expect("axis");
        assert_eq!(axis, RendererTabSplitAxis::Down);
        // On-axis (vertical) nudges the nested split; off-axis (horizontal) is a no-op.
        assert!(split_ratio_nudge_delta(axis, PaneFocusDirection::Down).is_some());
        assert!(split_ratio_nudge_delta(axis, PaneFocusDirection::Left).is_none());
    }

    #[test]
    fn resize_no_split_resolves_no_target() {
        // A lone tab has no split, so there is nothing to nudge (the App treats None as a no-op).
        let s = strip(vec![plain_tab("solo", true)]);
        assert_eq!(focused_split_child_to_reset(&s, Some("sid-solo")), None);
        assert_eq!(focused_split_child_to_reset(&s, None), None);
    }

    #[test]
    fn zoom_shortcut_accepts_only_the_intended_modifier_enter_chord() {
        use crate::host_event::{HostKey, HostNamedKey};
        use crate::host_mods;
        let enter = HostKey::Named(HostNamedKey::Enter);
        let super_alt = host_mods(false, true, false, true);
        let ctrl_alt = host_mods(true, true, false, false);
        // Both platform chords match on Enter.
        assert!(zoom_toggle_shortcut_matches(&enter, &super_alt));
        assert!(zoom_toggle_shortcut_matches(&enter, &ctrl_alt));
        // Plain Enter and single-modifier Enter do NOT match (Enter must still reach the PTY).
        assert!(!zoom_toggle_shortcut_matches(
            &enter,
            &host_mods(false, false, false, false)
        ));
        assert!(!zoom_toggle_shortcut_matches(
            &enter,
            &host_mods(false, false, false, true)
        ));
        assert!(!zoom_toggle_shortcut_matches(
            &enter,
            &host_mods(true, false, false, false)
        ));
        assert!(!zoom_toggle_shortcut_matches(
            &enter,
            &host_mods(false, true, false, false)
        ));
        // Both super AND control held is not the chord (XOR requires exactly one).
        assert!(!zoom_toggle_shortcut_matches(
            &enter,
            &host_mods(true, true, false, true)
        ));
        // Shift is forbidden (keeps the chord unambiguous).
        assert!(!zoom_toggle_shortcut_matches(
            &enter,
            &host_mods(false, true, true, true)
        ));
        // A non-Enter key never matches even with the right chord.
        assert!(!zoom_toggle_shortcut_matches(
            &HostKey::Character("0".to_string()),
            &super_alt
        ));
        assert!(!zoom_toggle_shortcut_matches(
            &HostKey::Named(HostNamedKey::Space),
            &super_alt
        ));
    }

    #[test]
    fn zoom_no_split_produces_no_zoom() {
        // A single (unsplit) pane has nothing to zoom over: the collapse returns None for any session.
        let s = strip(vec![plain_tab("solo", true)]);
        let layout = compute_split_layout(&s, 40, 20).expect("layout");
        assert_eq!(layout.panes.len(), 1);
        assert!(zoom_collapsed_layout(&layout, "sid-solo").is_none());
    }

    #[test]
    fn zoom_focused_child_fills_the_grid_and_restores() {
        // src (left) | child (right), child active. Zooming either pane collapses to ONE full-grid pane
        // for that session; the un-zoomed layout is unchanged (restore is just dropping the collapse).
        let s = strip(vec![
            plain_tab("src", false),
            split_child("child", "src", RendererTabSplitAxis::Right, true),
        ]);
        let layout = compute_split_layout(&s, 40, 20).expect("layout");
        assert_eq!(layout.panes.len(), 2);
        // Full grid spans the union of both pane regions (origin 0,0 to the far edges).
        let zoom_child = zoom_collapsed_layout(&layout, "sid-child").expect("zoom child");
        assert_eq!(zoom_child.panes.len(), 1);
        assert!(zoom_child.dividers.is_empty());
        let p = &zoom_child.panes[0];
        assert_eq!(p.session_id, "sid-child");
        assert!(p.active);
        assert_eq!(
            p.region,
            RendererPaneRegion {
                col: 0,
                row: 0,
                cols: 40,
                rows: 20
            }
        );
        // The non-active source pane can be zoomed too — it fills the SAME full grid.
        let zoom_src = zoom_collapsed_layout(&layout, "sid-src").expect("zoom src");
        assert_eq!(zoom_src.panes.len(), 1);
        assert_eq!(zoom_src.panes[0].session_id, "sid-src");
        assert_eq!(
            zoom_src.panes[0].region,
            RendererPaneRegion {
                col: 0,
                row: 0,
                cols: 40,
                rows: 20
            }
        );
        // "Restore" is the absence of a collapse: the original layout is untouched and still 2 panes.
        let restored = compute_split_layout(&s, 40, 20).expect("layout again");
        assert_eq!(restored, layout);
    }

    #[test]
    fn zoom_nested_pane_fills_the_grid_without_mutating_geometry() {
        // src (left) | [ mid (top-right) over bot (bottom-right) ]. Zooming the nested `bot` exposes ONLY
        // bot, spanning the full grid, with no dividers — and the recomputed split layout is identical,
        // proving the stored geometry was never mutated by the collapse.
        let s = strip(vec![
            plain_tab("src", true),
            split_child("mid", "src", RendererTabSplitAxis::Right, false),
            split_child("bot", "mid", RendererTabSplitAxis::Down, false),
        ]);
        let layout = compute_split_layout(&s, 41, 21).expect("layout");
        assert_eq!(layout.panes.len(), 3);
        let zoom_bot = zoom_collapsed_layout(&layout, "sid-bot").expect("zoom bot");
        assert_eq!(zoom_bot.panes.len(), 1);
        assert!(zoom_bot.dividers.is_empty());
        assert_eq!(zoom_bot.panes[0].session_id, "sid-bot");
        assert!(zoom_bot.panes[0].active);
        // Union of all three panes is the whole grid.
        assert_eq!(
            zoom_bot.panes[0].region,
            RendererPaneRegion {
                col: 0,
                row: 0,
                cols: 41,
                rows: 21
            }
        );
        // Geometry is read-only: the source layout is unchanged after collapsing.
        let again = compute_split_layout(&s, 41, 21).expect("layout again");
        assert_eq!(again, layout);
    }

