        // Zooming the ACTIVE pane keeps the existing paint source (`Shared::grid` + scrollback): the
        // selector returns None so the active live grid fills the window unchanged.
        assert_eq!(zoom_paint_session(Some("sid-src"), "sid-src"), None);
