    #[test]
    fn pane_drag_target_resolves_other_pane_center_and_rejects_dividers() {
        // The drop TARGET reuses `layout_pane_at_cell`: a center cell of any pane resolves that pane;
        // a divider/outside resolves none. The app only emits a swap when target != source, so a drop
        // back onto the dragged pane is a no-op the renderer filters before emitting.
        let tabs = vec![
            plain_tab("src", false),
            split_child("mid", "src", RendererTabSplitAxis::Right, false),
            split_child("bot", "mid", RendererTabSplitAxis::Down, true),
        ];
        let layout = compute_split_layout(&strip(tabs), 21, 12).expect("layout");
        for pane in &layout.panes {
            let r = pane.region;
            // Center cell of the pane resolves the pane itself as a drop target.
            let cx = (r.col as usize) + (r.cols as usize) / 2;
            let cy = (r.row as usize) + (r.rows as usize) / 2;
            let target = layout_pane_at_cell(&layout, cx, cy).expect("center target");
            assert_eq!(target.tab_id, pane.tab_id);
        }
        let divider = layout.dividers.first().expect("divider");
        assert!(
            layout_pane_at_cell(&layout, divider.col as usize, divider.row as usize).is_none(),
            "a drop on a divider has no target"
        );
    }

    // --- edge-drop drop-zone resolution (pure geometry) ---

    #[test]
    fn drop_zone_center_band_resolves_to_swap() {
        // A generous pane; the exact center is a center (swap) zone, as is anything inside the 18% band.
        let region = RendererPaneRegion {
            col: 0,
            row: 0,
            cols: 40,
            rows: 20,
        };
        // Center cell.
        assert_eq!(
            pane_drop_zone_in_region(region, 20, 10),
            PaneDropZone::Center
        );
        // Just inside the band on both axes (|d|<0.18): col 17/40=0.4375 -> dx=-0.0625, row 9.
        assert_eq!(
            pane_drop_zone_in_region(region, 17, 9),
            PaneDropZone::Center
        );
        // Center has no dock edge.
        assert_eq!(PaneDropZone::Center.dock_edge(), None);
    }

    #[test]
    fn drop_zone_edges_pick_the_dominant_axis() {
        let region = RendererPaneRegion {
            col: 0,
            row: 0,
            cols: 40,
            rows: 20,
        };
        // Far left, vertically centered -> Left (horizontal dominates).
        assert_eq!(pane_drop_zone_in_region(region, 1, 10), PaneDropZone::Left);
        // Far right -> Right.
        assert_eq!(
            pane_drop_zone_in_region(region, 38, 10),
            PaneDropZone::Right
        );
        // Top, horizontally centered -> Top (vertical dominates).
        assert_eq!(pane_drop_zone_in_region(region, 20, 1), PaneDropZone::Top);
        // Bottom -> Bottom.
        assert_eq!(
            pane_drop_zone_in_region(region, 20, 18),
            PaneDropZone::Bottom
        );
        // Edge zones map to dock edges.
        assert_eq!(PaneDropZone::Left.dock_edge(), Some(PaneDockEdge::Left));
        assert_eq!(PaneDropZone::Right.dock_edge(), Some(PaneDockEdge::Right));
        assert_eq!(PaneDropZone::Top.dock_edge(), Some(PaneDockEdge::Top));
        assert_eq!(PaneDropZone::Bottom.dock_edge(), Some(PaneDockEdge::Bottom));
    }

    #[test]
    fn drop_zone_single_cell_pane_is_center_not_a_divide_by_zero() {
        // A 1x1 region normalizes the lone cell to its center (0.5,0.5) -> Center, never a NaN/panic.
        let region = RendererPaneRegion {
            col: 5,
            row: 7,
            cols: 1,
            rows: 1,
        };
        assert_eq!(pane_drop_zone_in_region(region, 5, 7), PaneDropZone::Center);
    }

    #[test]
    fn drop_highlight_region_is_full_for_center_and_a_correct_half_for_edges() {
        let region = RendererPaneRegion {
            col: 10,
            row: 4,
            cols: 40,
            rows: 20,
        };
        // Center washes the whole pane.
        assert_eq!(
            pane_drop_highlight_region(region, PaneDropZone::Center),
            region
        );
        // Left half: same origin, half the columns.
        assert_eq!(
            pane_drop_highlight_region(region, PaneDropZone::Left),
            RendererPaneRegion {
                col: 10,
                row: 4,
                cols: 20,
                rows: 20
            }
        );
        // Right half: shifted origin, half the columns, ending on the same right edge.
        assert_eq!(
            pane_drop_highlight_region(region, PaneDropZone::Right),
            RendererPaneRegion {
                col: 30,
                row: 4,
                cols: 20,
                rows: 20
            }
        );
        // Top half: same origin, half the rows.
        assert_eq!(
            pane_drop_highlight_region(region, PaneDropZone::Top),
            RendererPaneRegion {
                col: 10,
                row: 4,
                cols: 40,
                rows: 10
            }
        );
        // Bottom half: shifted origin, half the rows, ending on the same bottom edge.
        assert_eq!(
            pane_drop_highlight_region(region, PaneDropZone::Bottom),
            RendererPaneRegion {
                col: 10,
                row: 14,
                cols: 40,
                rows: 10
            }
        );
    }

    #[test]
    fn visible_pane_drag_center_and_edge_drops_both_swap_with_target() {
        let layout = RendererSplitLayout {
            panes: vec![
                RendererLayoutPane {
                    tab_id: "left".to_string(),
                    session_id: "left-session".to_string(),
                    region: RendererPaneRegion {
                        col: 0,
                        row: 0,
                        cols: 40,
                        rows: 20,
                    },
                    active: true,
                },
                RendererLayoutPane {
                    tab_id: "right".to_string(),
                    session_id: "right-session".to_string(),
                    region: RendererPaneRegion {
                        col: 41,
                        row: 0,
                        cols: 40,
                        rows: 20,
                    },
                    active: false,
                },
            ],
            dividers: vec![RendererSplitDivider {
                col: 40,
                row: 0,
                length: 20,
                glyph: '|',
            }],
        };

        // Center of the right pane: visible pane onto visible pane -> swap.
        assert_eq!(
            visible_pane_drag_swap_target(&layout, "left", 61, 10),
            Some("right")
        );
        assert_eq!(
            pane_drop_zone_in_region(layout.panes[1].region, 61, 10),
            PaneDropZone::Center
        );

        // Far right edge of the same right pane: still a swap, not a redock/reshape.
        assert_eq!(
            visible_pane_drag_swap_target(&layout, "left", 79, 10),
            Some("right")
        );
        assert_eq!(
            pane_drop_zone_in_region(layout.panes[1].region, 79, 10),
            PaneDropZone::Right
        );

        // Drops onto the source pane, divider, or outside the layout do not produce a swap target.
        assert_eq!(visible_pane_drag_swap_target(&layout, "left", 20, 10), None);
        assert_eq!(visible_pane_drag_swap_target(&layout, "left", 40, 10), None);
        assert_eq!(visible_pane_drag_swap_target(&layout, "left", 99, 99), None);
    }

    #[test]
    fn emit_pane_edge_dock_requested_round_trips_and_is_nonfatal_when_closed() {
        let (tx, rx) = std::sync::mpsc::channel();
        assert!(emit_pane_edge_dock_requested(
            Some(&tx),
            "src",
            "tgt",
            PaneDockEdge::Bottom
        ));
        match rx.recv().expect("event") {
            RendererEvent::PaneEdgeDockRequested {
                source_tab_id,
                target_tab_id,
                edge,
            } => {
                assert_eq!(source_tab_id, "src");
                assert_eq!(target_tab_id, "tgt");
                assert_eq!(edge, PaneDockEdge::Bottom);
            }
            other => panic!("expected PaneEdgeDockRequested, got {other:?}"),
        }
        // No sender / dropped receiver -> false, never panics.
        assert!(!emit_pane_edge_dock_requested(
            None,
            "s",
            "t",
            PaneDockEdge::Left
        ));
        drop(rx);
        assert!(!emit_pane_edge_dock_requested(
            Some(&tx),
            "s",
            "t",
            PaneDockEdge::Left
        ));
    }

    // --- pane-local mouse coords + scrollback routing ---

    #[test]
    fn scroll_pane_local_cell_is_zero_based_for_active_and_sibling() {
        // Right split: active pane (child) is the SECOND (right) region offset to the right; the
        // sibling (source) is the FIRST (left) region at the window origin. The two-pane layout is a
        // strict subset of the N-pane layout, so pane-local translation runs through the production
        // `pane_local_cell_in_region` over each pane's region — preserving two-pane mouse coordinates.
        let s = strip(vec![
            plain_tab("src", false),
            split_child("child", "src", RendererTabSplitAxis::Right, true),
        ]);
        let frame = active_split_frame(Some(&s), 21, 10).expect("frame");
        let active = active_pane_region(&frame);
        let sibling = inactive_pane_region(&frame);
        // The top-left absolute cell of each pane maps to its local (0,0).
        assert_eq!(
            pane_local_cell_in_region(active, active.col as usize, active.row as usize),
            Some((0, 0))
        );
        assert_eq!(
            pane_local_cell_in_region(sibling, sibling.col as usize, sibling.row as usize),
            Some((0, 0))
        );
        // One cell into the active pane maps to local (1,0), proving the right-offset is subtracted.
        assert_eq!(
            pane_local_cell_in_region(active, active.col as usize + 1, active.row as usize),
            Some((1, 0))
        );
    }

    #[test]
    fn scroll_pane_local_cell_outside_focused_pane_is_none() {
        let s = strip(vec![
            plain_tab("src", false),
            split_child("child", "src", RendererTabSplitAxis::Right, true),
        ]);
        let frame = active_split_frame(Some(&s), 21, 10).expect("frame");
        let sibling = inactive_pane_region(&frame);
        // A cell that lives in the active (right) pane is OUTSIDE the focused sibling pane → None,
        // so the report path emits nothing for the wrong pane.
        let active = active_pane_region(&frame);
        assert_eq!(
            pane_local_cell_in_region(sibling, active.col as usize, active.row as usize),
            None
        );
        // And a cell past the sibling extent is also None.
        assert_eq!(
            pane_local_cell_in_region(
                sibling,
                (sibling.col + sibling.cols) as usize,
                sibling.row as usize
            ),
            None
        );
    }

    #[test]
    fn scroll_pane_local_cellpos_clamps_into_pane() {
        let region = RendererPaneRegion {
            col: 10,
            row: 4,
            cols: 6,
            rows: 5,
        };
        // In-pane absolute cell translates by subtracting the origin.
        assert_eq!(
            pane_local_cellpos(CellPos { col: 12, row: 6 }, region),
            CellPos { col: 2, row: 2 }
        );
        // A cell left/above the pane clamps to local (0,0) (saturating subtraction).
        assert_eq!(
            pane_local_cellpos(CellPos { col: 0, row: 0 }, region),
            CellPos { col: 0, row: 0 }
        );
        // A cell past the pane extent clamps to the last in-pane cell, never reading neighbours.
        assert_eq!(
            pane_local_cellpos(CellPos { col: 999, row: 999 }, region),
            CellPos { col: 5, row: 4 }
        );
    }

    #[test]
    fn scroll_request_target_follows_focus() {
        // The Scrollback request reuses `focused_session_write_target` over the N-pane layout, so a
        // scroll gesture pages whichever pane the session focus names — sibling-focused pages the
        // sibling, active-focused (or unsplit) pages the active. Two-pane layout = strict subset.
        let s = strip(vec![
            plain_tab("src", false),
            split_child("child", "src", RendererTabSplitAxis::Right, true),
        ]);
        let layout = compute_split_layout(&s, 21, 10).expect("layout");
        // Active-pane focus (None) pages the active session.
        assert_eq!(
            focused_session_write_target(None, "sid-active", Some(&layout)),
            "sid-active"
        );
        // Focusing the sibling session pages it.
        assert_eq!(
            focused_session_write_target(Some("sid-src"), "sid-active", Some(&layout)),
            "sid-src"
        );
        // Unsplit (no layout): always the active session id.
        assert_eq!(
            focused_session_write_target(Some("sid-src"), "sid-active", None),
            "sid-active"
        );
    }

