    #[test]
    fn resize_active_source_pane_uses_its_own_region_not_the_child() {
        // When the SOURCE tab is active (not the child), the active session adopts the source pane's
        // region (the left/top half), distinct from the sibling child's region.
        let s = strip(vec![
            plain_tab("src", true),
            split_child("child", "src", RendererTabSplitAxis::Right, false),
        ]);
        let frame = active_split_frame(Some(&s), 21, 10).expect("frame");
        let active = active_pane_region(&frame);
        let sibling = inactive_pane_region(&frame);
        assert_eq!(
            active_resize_dims((21, 10), Some(&frame)),
            (active.cols, active.rows)
        );
        // The active (source/left) region and the sibling (child/right) region are both 10x10 here, but
        // their origins differ — the resize uses the active region, never the sibling's.
        assert_eq!(active.col, 0);
        assert_ne!(active.col, sibling.col);
    }

