    #[test]
    fn layout_two_pane_matches_compute_split_frame_regions() {
        // The two-pane layout is the existing frame geometry as a strict subset: same two regions,
        // same divider — so the live frame path and the N-pane layout agree on the simple case.
        let tabs = vec![
            plain_tab("src", false),
            split_child("child", "src", RendererTabSplitAxis::Right, true),
        ];
        let frame = compute_split_frame(&tabs, "child", 21, 10).expect("frame");
        let layout = compute_split_layout(&strip(tabs), 21, 10).expect("layout");

        assert_eq!(layout.panes.len(), 2);
        assert_eq!(layout.dividers, vec![frame.divider]);
        // Source pane first (left), child pane second (right) — same regions as the frame.
        assert_eq!(layout.panes[0].tab_id, "src");
        assert_eq!(layout.panes[0].region, frame.first);
        assert!(!layout.panes[0].active);
        assert_eq!(layout.panes[1].tab_id, "child");
        assert_eq!(layout.panes[1].region, frame.second);
        assert!(layout.panes[1].active);
    }

    #[test]
    fn layout_three_pane_nested_right_then_down_is_non_overlapping() {
        // src --Right--> mid --Down--> bot (active). The right half is split again vertically.
        let tabs = vec![
            plain_tab("src", false),
            split_child("mid", "src", RendererTabSplitAxis::Right, false),
            split_child("bot", "mid", RendererTabSplitAxis::Down, true),
        ];
        let layout = compute_split_layout(&strip(tabs), 21, 10).expect("layout");

        assert_eq!(layout.panes.len(), 3);
        let src = &layout.panes[0];
        let mid = &layout.panes[1];
        let bot = &layout.panes[2];
        assert_eq!(src.tab_id, "src");
        assert_eq!(mid.tab_id, "mid");
        assert_eq!(bot.tab_id, "bot");
        assert_eq!(
            src.region,
            RendererPaneRegion {
                col: 0,
                row: 0,
                cols: 10,
                rows: 10
            }
        );
        assert_eq!(
            mid.region,
            RendererPaneRegion {
                col: 11,
                row: 0,
                cols: 10,
                rows: 4
            }
        );
        assert_eq!(
            bot.region,
            RendererPaneRegion {
                col: 11,
                row: 5,
                cols: 10,
                rows: 5
            }
        );
        assert!(bot.active);
        assert!(!src.active && !mid.active);

        // Two dividers: the top-level vertical line, then the nested horizontal one in the right half.
        assert_eq!(layout.dividers.len(), 2);
        assert!(layout.dividers.contains(&RendererSplitDivider {
            col: 10,
            row: 0,
            length: 10,
            glyph: '|'
        }));
        assert!(layout.dividers.contains(&RendererSplitDivider {
            col: 11,
            row: 4,
            length: 10,
            glyph: '-'
        }));

        // Pairwise non-overlap: no cell belongs to two panes.
        for a in 0..3 {
            for b in (a + 1)..3 {
                let ra = layout.panes[a].region;
                let rb = layout.panes[b].region;
                let disjoint = ra.col + ra.cols <= rb.col
                    || rb.col + rb.cols <= ra.col
                    || ra.row + ra.rows <= rb.row
                    || rb.row + rb.rows <= ra.row;
                assert!(disjoint, "panes {a} and {b} overlap");
            }
        }
    }

