    #[test]
    fn production_pointer_planner_uses_window_grid_for_right_and_bottom_secondary_panes() {
        const ORIGIN_X: f32 = 4.0;
        const ORIGIN_Y: f32 = 6.0;
        const CELL_W: f32 = 10.0;
        const CELL_H: f32 = 20.0;

        for (axis, child, cols, rows) in [
            (RendererTabSplitAxis::Right, "right", 41u16, 16u16),
            (RendererTabSplitAxis::Down, "bottom", 30u16, 21u16),
        ] {
            let layout = compute_split_layout(
                &strip(vec![
                    plain_tab("src", false),
                    split_child(child, "src", axis, true),
                ]),
                cols,
                rows,
            )
            .expect("split layout");
            let secondary = layout
                .panes
                .iter()
                .find(|pane| pane.session_id == format!("sid-{child}"))
                .expect("secondary pane");
            let content = pane_content_region(secondary.region);
            let absolute = CellPos {
                col: usize::from(content.col),
                row: usize::from(content.row),
            };
            let pointer = (
                ORIGIN_X + (absolute.col as f32 + 0.5) * CELL_W,
                ORIGIN_Y + (absolute.row as f32 + 0.5) * CELL_H,
            );
            let primary = layout
                .panes
                .iter()
                .find(|pane| pane.session_id == "sid-src")
                .expect("primary pane");
            let primary_content = pane_content_region(primary.region);

            // This is the old macOS production behavior: bounding the pointer by the
            // primary pane's own grid rejects a right/bottom secondary pane.
            let clamped_to_primary = terminal_pointer_cell_with_layout(
                pointer,
                ORIGIN_X,
                ORIGIN_Y,
                CELL_W,
                CELL_H,
                Some((
                    usize::from(primary_content.cols),
                    usize::from(primary_content.rows),
                )),
                None,
            )
            .expect("legacy fallback clamps to the primary edge");
            assert_ne!(
                clamped_to_primary, absolute,
                "{axis:?}: primary-sized fallback loses the secondary absolute cell"
            );
            assert_eq!(
                pane_local_cell_in_region(content, clamped_to_primary.col, clamped_to_primary.row,),
                None,
                "{axis:?}: the later pane-local gate drops the clamped legacy cell"
            );

            // The production split plan uses the full window grid, admits exactly the
            // focused pane's content, and preserves its absolute cell for one later
            // pane-local translation in report_mouse.
            assert_eq!(
                terminal_pointer_cell_with_layout(
                    pointer,
                    ORIGIN_X,
                    ORIGIN_Y,
                    CELL_W,
                    CELL_H,
                    None,
                    Some((
                        &layout,
                        &secondary.session_id,
                        (usize::from(cols), usize::from(rows)),
                    )),
                ),
                Some(absolute),
                "{axis:?}: split-aware production plan reaches the secondary pane"
            );
            assert_eq!(
                pane_local_cell_in_region(content, absolute.col, absolute.row),
                Some((0, 0)),
                "{axis:?}: report_mouse translates the admitted cell exactly once"
            );
        }
    }

    #[test]
    fn layout_root_resolved_from_active_child() {
        // Active tab is the deepest child; the layout still walks up to the chain root so the whole
        // tree renders, not just the active tab.
        let tabs = vec![
            plain_tab("src", false),
            split_child("mid", "src", RendererTabSplitAxis::Right, false),
            split_child("bot", "mid", RendererTabSplitAxis::Down, true),
        ];
        let layout = compute_split_layout(&strip(tabs), 21, 10).expect("layout");
        let ids: Vec<&str> = layout.panes.iter().map(|p| p.tab_id.as_str()).collect();
        assert_eq!(ids, vec!["src", "mid", "bot"]);
        assert_eq!(layout.panes.iter().filter(|p| p.active).count(), 1);
    }

