    // No cache snapshot for any pane (every pane is unknown to the cache).
    fn no_snapshot(_id: &str) -> Option<(Option<u32>, Option<Option<i32>>)> {
        None
    }

    #[test]
    fn plan_two_pane_yields_no_extra_panes_or_dividers() {
        // A two-pane layout: active=child, sibling=source. Neither remains as an "extra" pane, so the
        // active+sibling paint stays byte-identical and no extra divider is emitted.
        let tabs = vec![
            plain_tab("src", false),
            split_child("child", "src", RendererTabSplitAxis::Right, true),
        ];
        let layout = compute_split_layout(&strip(tabs), 21, 10).expect("layout");
        let (panes, dividers) =
            plan_extra_panes(&layout, "sid-child", Some("sid-src"), None, no_snapshot);
        assert!(panes.is_empty(), "no extra panes in the two-pane case");
        assert!(
            dividers.is_empty(),
            "no extra dividers in the two-pane case"
        );
    }

    #[test]
    fn plan_panes_include_all_paints_each_pane_in_its_own_region_no_swap() {
        // The source pane's grid must not paint into the child's region (and
        // vice versa) because the privileged primary path clipped `self.session_id`'s grid to the
        // layout-ACTIVE region. With `include_all`, every pane (active + primary included) is emitted
        // with ITS OWN region, so there is no swap. Layout: `A | B`, A is the source (left), B the
        // active child (right). Each pane reports a distinct grid id; assert grid id ↔ region pairing.
        let tabs = vec![
            plain_tab("src", false),
            split_child("child", "src", RendererTabSplitAxis::Right, true),
        ];
        let layout = compute_split_layout(&strip(tabs), 21, 10).expect("layout");
        // A's region is the left half, B's the right half (the divider sits at col 10).
        let src_region = layout
            .panes
            .iter()
            .find(|p| p.session_id == "sid-src")
            .expect("src pane")
            .region;
        let child_region = layout
            .panes
            .iter()
            .find(|p| p.session_id == "sid-child")
            .expect("child pane")
            .region;
        assert_ne!(src_region, child_region, "panes occupy distinct regions");

        // Each pane resolves a grid tagged by which session it belongs to (1 = src, 2 = child).
        let (panes, dividers) = plan_panes(
            &layout,
            "sid-src", // primary (self.session_id) is the SOURCE — the un-rebased case that swapped.
            None,
            None,
            true,
            None,
            |_| false,
            |id| id.to_string(),
            |id| match id {
                "sid-src" => Some((Some(1u32), None)),
                "sid-child" => Some((Some(2u32), None)),
                _ => None,
            },
        );
        assert_eq!(panes.len(), 2, "both panes are painted in include_all mode");
        let src = panes
            .iter()
            .find(|p| p.session_id == "sid-src")
            .expect("src in paint list");
        let child = panes
            .iter()
            .find(|p| p.session_id == "sid-child")
            .expect("child in paint list");
        // The crux: src's grid (1) is paired with src's region, child's grid (2) with child's region.
        assert_eq!(src.region, src_region);
        assert_eq!(src.grid, Some(1u32), "source pane keeps the source grid");
        assert_eq!(child.region, child_region);
        assert_eq!(child.grid, Some(2u32), "child pane keeps the child grid");
        // include_all carries every divider (none are drawn by a privileged split_frame path now).
        assert_eq!(dividers.len(), layout.dividers.len());
    }

    #[test]
    fn plan_three_pane_extra_excludes_active_and_sibling() {
        // active=sid-bot, sibling(rendered)=sid-src → only `mid` is an extra pane. `mid` has no cache
        // entry yet, so it reads as Pending with no grid (its placeholder shows until it baselines).
        let layout = three_pane_layout();
        let top_divider = RendererSplitDivider {
            col: 10,
            row: 0,
            length: 10,
            glyph: '|',
        };
        let (panes, dividers) = plan_extra_panes(
            &layout,
            "sid-bot",
            Some("sid-src"),
            Some(top_divider),
            no_snapshot,
        );
        assert_eq!(panes.len(), 1, "exactly one extra pane (mid)");
        assert_eq!(panes[0].session_id, "sid-mid");
        assert_eq!(panes[0].tab_id, "mid");
        assert_eq!(
            panes[0].region,
            RendererPaneRegion {
                col: 11,
                row: 0,
                cols: 10,
                rows: 4
            }
        );
        assert!(panes[0].grid.is_none());
        assert_eq!(panes[0].status, SiblingPaneStatus::Pending);

        // The top-level divider was drawn by the split_frame path → only the nested one remains.
        assert_eq!(dividers.len(), 1, "the drawn top divider is de-duped");
        assert_eq!(
            dividers[0],
            RendererSplitDivider {
                col: 11,
                row: 4,
                length: 10,
                glyph: '-'
            }
        );
    }

    #[test]
    fn plan_extra_pane_status_reflects_cache_snapshot() {
        // active=sid-bot, sibling=sid-mid → only `src` is an extra pane. Its status/grid follow the
        // cache snapshot: a cached grid → Attached(with grid); an exit → Exited(with its retained
        // grid when cached); a bound but ungridded entry → Pending; an unknown id → Pending.
        let layout = three_pane_layout();

        let attached = plan_extra_panes(&layout, "sid-bot", Some("sid-mid"), None, |id| {
            if id == "sid-src" {
                Some((Some(7u32), None))
            } else {
                None
            }
        });
        assert_eq!(attached.0.len(), 1);
        assert_eq!(attached.0[0].session_id, "sid-src");
        assert_eq!(attached.0[0].grid, Some(7u32));
        assert_eq!(attached.0[0].status, SiblingPaneStatus::Attached);

        let exited = plan_extra_panes(&layout, "sid-bot", Some("sid-mid"), None, |id| {
            if id == "sid-src" {
                // Exited entries retain their final cached grid for inspection.
                Some((Some(7u32), Some(Some(0))))
            } else {
                None
            }
        });
        assert_eq!(
            exited.0[0].grid,
            Some(7u32),
            "an exited pane keeps its retained final grid"
        );
        assert_eq!(exited.0[0].status, SiblingPaneStatus::Exited);

        let pending_member = plan_extra_panes(&layout, "sid-bot", Some("sid-mid"), None, |id| {
            if id == "sid-src" {
                Some((None::<u32>, None))
            } else {
                None
            }
        });
        assert_eq!(pending_member.0[0].status, SiblingPaneStatus::Pending);
    }

    #[test]
    fn pane_content_region_reserves_the_header_row_when_the_pane_can_host_one() {
        // A pane big enough for the header bar gives up its TOP rows to chrome: content starts below
        // the reserved header and is shorter by the same amount, but keeps the same column span. This is the single source of
        // truth the PTY size, draw offset, clip height, and mouse/selection coords all read from.
        let region = RendererPaneRegion {
            col: 4,
            row: 2,
            cols: 10,
            rows: 6,
        };
        assert_eq!(
            pane_content_region(region),
            RendererPaneRegion {
                col: 4,
                row: 4,
                cols: 10,
                rows: 4,
            }
        );
    }

    #[test]
    fn pane_content_region_passes_through_a_pane_too_small_for_a_header() {
        // Below the header size gate (cols < 3 or rows < 2) no header is drawn, so the whole region is
        // content — content must NOT shrink, or a tiny pane would lose its only usable row.
        let tiny = RendererPaneRegion {
            col: 0,
            row: 0,
            cols: 2,
            rows: 1,
        };
        assert_eq!(pane_content_region(tiny), tiny);
        let one_row = RendererPaneRegion {
            col: 0,
            row: 0,
            cols: 8,
            rows: 1,
        };
        assert_eq!(pane_content_region(one_row), one_row);
    }

    #[test]
    fn single_pane_layout_keeps_full_height_because_no_header_is_drawn() {
        let region = RendererPaneRegion {
            col: 0,
            row: 0,
            cols: 80,
            rows: 30,
        };
        assert_eq!(
            pane_content_region_for_layout(region, 1),
            region,
            "an unsplit PTY must not lose the two invisible header rows"
        );
        assert_eq!(
            pane_content_region_for_layout(region, 2),
            RendererPaneRegion {
                col: 0,
                row: PANE_HEADER_ROWS,
                cols: 80,
                rows: 30 - PANE_HEADER_ROWS,
            },
            "real split panes still reserve their visible header"
        );
    }

    #[test]
    fn terminal_viewport_origin_composes_with_two_and_four_pane_input_and_pty_dims() {
        use super::pixel_to_cell_with_top_offset;
        use RendererTabSplitAxis::{Down, Right};

        const WINDOW_COLS: u16 = 73;
        const WINDOW_ROWS: u16 = 37;
        const GRID_ORIGIN_X: f32 = 464.0;
        const GRID_ORIGIN_Y: f32 = 46.0;
        const CELL_W: f32 = 10.0;
        const CELL_H: f32 = 20.0;

        let cases = [
            (
                "two-pane",
                strip(vec![
                    plain_tab("A", false),
                    split_child("B", "A", Right, true),
                ]),
                2,
            ),
            (
                "canonical-four-pane",
                strip(vec![
                    plain_tab("A", false),
                    split_child("B", "A", Right, false),
                    split_child("C", "A", Down, false),
                    split_child("D", "B", Down, true),
                ]),
                4,
            ),
        ];

        for (label, tab_strip, expected_panes) in cases {
            let layout = compute_split_layout(&tab_strip, WINDOW_COLS, WINDOW_ROWS)
                .unwrap_or_else(|| panic!("{label}: layout"));
            assert_eq!(layout.panes.len(), expected_panes, "{label}");

            let shared = Shared::with_test_outbound();
            shared.set_active_session("sid-A");
            *shared.grid.lock().unwrap() = Some(Arc::new(role_transition_grid(
                usize::from(WINDOW_COLS),
                usize::from(WINDOW_ROWS),
            )));
            let mut app = role_transition_app(shared.clone(), "sid-A");
            app.handle_user_event(UserEvent::SetTabStrip {
                tab_strip: Some(tab_strip),
            });
            // In production the subsequent draw performs this primary-side half of the same
            // reconciliation; call it explicitly in the headless fixture so every visible PTY is
            // represented in the outbound assertion below.
            app.sync_primary_resize();
            let requests = shared.drain_test_requests();

            for pane in &layout.panes {
                let content = pane_content_region_for_layout(pane.region, layout.panes.len());
                let expected_dims = (content.cols, content.rows);
                assert!(
                    requests.iter().any(|request| matches!(
                        request,
                        ClientRequest::Resize { id, cols, rows }
                            if id == &pane.session_id && (*cols, *rows) == expected_dims
                    )),
                    "{label}: {} PTY must receive its exact painted content dimensions {expected_dims:?}; requests={requests:?}",
                    pane.session_id,
                );

                let header_cell = CellPos {
                    col: usize::from(pane.region.col),
                    row: usize::from(pane.region.row),
                };
                assert_eq!(
                    focused_terminal_cell_in_layout(&layout, &pane.session_id, header_cell),
                    None,
                    "{label}: pane header is chrome, never terminal input",
                );

                let map_pixel = |col: u16, row: u16| {
                    pixel_to_cell_with_top_offset(
                        GRID_ORIGIN_X + (f32::from(col) + 0.5) * CELL_W,
                        GRID_ORIGIN_Y + (f32::from(row) + 0.5) * CELL_H,
                        GRID_ORIGIN_X,
                        GRID_ORIGIN_Y,
                        CELL_W,
                        CELL_H,
                        usize::from(WINDOW_COLS),
                        usize::from(WINDOW_ROWS),
                    )
                    .expect("pane content pixel maps into the window grid")
                };
                let first = map_pixel(content.col, content.row);
                assert_eq!(
                    focused_terminal_cell_in_layout(&layout, &pane.session_id, first),
                    Some(first),
                );
                assert_eq!(
                    pane_local_cell_in_region(content, first.col, first.row),
                    Some((0, 0)),
                );

                let last = map_pixel(
                    content.col + content.cols - 1,
                    content.row + content.rows - 1,
                );
                assert_eq!(
                    focused_terminal_cell_in_layout(&layout, &pane.session_id, last),
                    Some(last),
                );
                assert_eq!(
                    pane_local_cell_in_region(content, last.col, last.row),
                    Some((usize::from(content.cols) - 1, usize::from(content.rows) - 1,)),
                    "{label}: the final painted cell and PTY-local final cell must coincide",
                );
            }
        }
    }

    #[test]
    fn close_and_drag_targets_are_dead_in_a_single_pane_layout() {
        // A single full-window pane has NO header (no `x`, no drag handle), so its top-right corner and
        // top row are ordinary terminal content. Both hit-tests must decline, or a click on row 0 of an
        // unsplit terminal would be swallowed as chrome instead of reaching the shell.
        let layout = compute_split_layout(&strip(vec![plain_tab("solo", true)]), 21, 10)
            .expect("single-pane layout");
        assert_eq!(
            layout.panes.len(),
            1,
            "fixture is a single full-window pane"
        );
        let r = layout.panes[0].region;
        let corner_col = (r.col + r.cols - 1) as usize;
        assert!(
            pane_close_target_at_cell(&layout, corner_col, r.row as usize).is_none(),
            "no close target in a single-pane layout"
        );
        assert!(
            pane_drag_origin_at_cell(&layout, r.col as usize, r.row as usize).is_none(),
            "no drag origin in a single-pane layout"
        );
    }

    #[test]
    fn close_and_drag_targets_resolve_per_pane_in_a_real_split() {
        // In a 2-pane split each pane hosts a header: its top-right corner closes THAT pane (not the
        // active one) and its top row is a drag origin. Assert the corner of B resolves
        // to B and the corner of A resolves to A.
        let tabs = vec![
            plain_tab("a", false),
            split_child("b", "a", RendererTabSplitAxis::Right, true),
        ];
        let layout = compute_split_layout(&strip(tabs), 21, 10).expect("layout");
        for pane in &layout.panes {
            let r = pane.region;
            let close_col = super::render::pane_header_close_cell(r).expect("close cell");
            let hit = pane_close_target_at_cell(&layout, close_col as usize, r.row as usize)
                .expect("each pane's corner is its own close target");
            assert_eq!(
                hit.session_id, pane.session_id,
                "the `x` closes the pane it sits in, not the active one"
            );
            assert!(
                pane_close_target_at_cell(&layout, (r.col + r.cols - 1) as usize, r.row as usize)
                    .map(|hit| hit.session_id.as_str())
                    != Some(
                        layout
                            .panes
                            .iter()
                            .find(|other| other.session_id != pane.session_id)
                            .map(|other| other.session_id.as_str())
                            .unwrap_or("")
                    ),
                "a pane's close hit zone must not bleed into a neighboring pane"
            );
            assert!(
                pane_drag_origin_at_cell(&layout, r.col as usize, r.row as usize).is_some(),
                "the header row of each pane is a drag origin"
            );
        }
    }

    #[test]
    fn plan_panes_sets_name_focused_and_show_header_for_a_split() {
        // plan_panes resolves each pane's display name (via name_of) and focus (via focused_id), and
        // turns the header on only for a real 2+-pane split. Layout `a | b`, focus pinned to a.
        let tabs = vec![
            plain_tab("a", false),
            split_child("b", "a", RendererTabSplitAxis::Right, true),
        ];
        let layout = compute_split_layout(&strip(tabs), 21, 10).expect("layout");
        let (panes, _dividers) = plan_panes(
            &layout,
            "sid-a",
            None,
            None,
            true,
            Some("sid-a"),
            |_| false,
            |id| format!("name-{id}"),
            no_snapshot,
        );
        assert_eq!(panes.len(), 2);
        let a = panes
            .iter()
            .find(|p| p.session_id == "sid-a")
            .expect("pane a");
        let b = panes
            .iter()
            .find(|p| p.session_id == "sid-b")
            .expect("pane b");
        assert_eq!(a.name, "name-a", "name comes from name_of, keyed by tab id");
        assert_eq!(b.name, "name-b");
        assert!(a.focused, "the focused_id pane is focused");
        assert!(!b.focused, "a non-focused pane is not focused");
        assert!(
            a.show_header && b.show_header,
            "both panes show a header in a 2-pane split"
        );
    }

    #[test]
    fn plan_panes_keeps_header_action_arrows_visible_without_hover() {
        // The move/extend arrows are persistent pane chrome. Hover is only used for cursor/drag feedback;
        // every legal action cluster remains visible so panes do not hide controls until mouseover.
        let layout = three_pane_layout();
        let (panes, _dividers) = plan_panes(
            &layout,
            "sid-src",
            None,
            None,
            true,
            None,
            |_| false,
            |id| id.to_string(),
            no_snapshot,
        );
        assert!(
            panes
                .iter()
                .any(|p| !p.move_directions.is_empty() || !p.swallow_directions.is_empty()),
            "fixture starts with at least one visible action arrow"
        );
        assert!(
            panes
                .iter()
                .filter(|p| !p.move_directions.is_empty() || !p.swallow_directions.is_empty())
                .count()
                >= 2,
            "multiple panes keep their action arrows without a hovered header"
        );
    }

    #[test]
    fn plan_panes_focus_falls_back_to_active_when_no_focused_id() {
        // With focused_id = None (focus not yet pinned), the layout-ACTIVE pane is treated as focused so
        // the amber ring still lands somewhere sensible. Active = b here.
        let tabs = vec![
            plain_tab("a", false),
            split_child("b", "a", RendererTabSplitAxis::Right, true),
        ];
        let layout = compute_split_layout(&strip(tabs), 21, 10).expect("layout");
        let (panes, _dividers) = plan_panes(
            &layout,
            "sid-a",
            None,
            None,
            true,
            None,
            |_| false,
            |id| id.to_string(),
            no_snapshot,
        );
        let a = panes.iter().find(|p| p.session_id == "sid-a").unwrap();
        let b = panes.iter().find(|p| p.session_id == "sid-b").unwrap();
        assert!(!a.focused);
        assert!(b.focused, "the active pane is the focus fallback");
    }

    #[test]
    fn plan_three_columns_keep_both_dividers_minus_the_drawn_one() {
        // src --Right--> a --Right--> b(active): three columns, two vertical dividers. With sibling=src
        // and active=b, `a` is the lone extra pane; the drawn top divider is removed, leaving the
        // second vertical divider as an extra.
        let tabs = vec![
            plain_tab("src", false),
            split_child("a", "src", RendererTabSplitAxis::Right, false),
            split_child("b", "a", RendererTabSplitAxis::Right, true),
        ];
        let layout = compute_split_layout(&strip(tabs), 30, 10).expect("layout");
        assert_eq!(layout.dividers.len(), 2, "two vertical dividers");
        let drawn = layout.dividers[0];
        let (panes, dividers) =
            plan_extra_panes(&layout, "sid-b", Some("sid-src"), Some(drawn), no_snapshot);
        assert_eq!(panes.len(), 1);
        assert_eq!(panes[0].session_id, "sid-a");
        assert_eq!(dividers, vec![layout.dividers[1]]);
    }

    #[test]
    fn layout_too_small_grid_stops_chain_without_degenerate_pane() {
        // A 2-wide grid cannot host a Right split (needs >=3 cols); the chain stops at the root,
        // yielding a single full-grid pane rather than a zero-width region.
        let tabs = vec![
            plain_tab("src", true),
            split_child("child", "src", RendererTabSplitAxis::Right, false),
        ];
        let layout = compute_split_layout(&strip(tabs), 2, 10).expect("layout");
        assert_eq!(layout.panes.len(), 1);
        assert_eq!(layout.dividers, vec![]);
        assert_eq!(layout.panes[0].tab_id, "src");
        assert_eq!(
            layout.panes[0].region,
            RendererPaneRegion {
                col: 0,
                row: 0,
                cols: 2,
                rows: 10
            }
        );
    }

    // --- Focus-driven split source: Cmd/Ctrl+D splits the FOCUSED pane, not the global active tab ---

    #[test]
    fn tab_id_for_session_is_inverse_of_pane_session_id() {
        let s = strip(vec![
            plain_tab("src", true),
            split_child("child", "src", RendererTabSplitAxis::Right, false),
        ]);
        assert_eq!(tab_id_for_session(&s, "sid-src"), Some("src"));
        assert_eq!(tab_id_for_session(&s, "sid-child"), Some("child"));
        // A session backing no tab in the strip resolves to nothing (no guessed tab).
        assert_eq!(tab_id_for_session(&s, "sid-absent"), None);
    }

    #[test]
    fn split_source_is_active_tab_when_no_pane_focus() {
        // Default (focus None): the split branches from the active tab — identical to pre-focus.
        let s = strip(vec![
            plain_tab("src", true),
            split_child("child", "src", RendererTabSplitAxis::Right, false),
        ]);
        assert_eq!(focused_split_source_tab_id(&s, None), Some("src"));
    }

    #[test]
    fn split_source_follows_clicked_pane_focus() {
        // Right split, then click the RIGHT (child) pane: a subsequent split must branch from the
        // focused right pane, not the active tab. This is what turns right-then-down into a 3-pane
        // column (left | top-right / bottom-right) rather than a 2x2 off the root.
        let s = strip(vec![
            plain_tab("src", true),
            split_child("child", "src", RendererTabSplitAxis::Right, false),
        ]);
        assert_eq!(
            focused_split_source_tab_id(&s, Some("sid-child")),
            Some("child")
        );
        // Clicking back onto the left (active) pane retargets the split to it.
        assert_eq!(
            focused_split_source_tab_id(&s, Some("sid-src")),
            Some("src")
        );
    }

    #[test]
    fn split_source_falls_back_to_active_for_stale_focus() {
        // A focus pointing at a pane that has since been removed never resolves to a vanished pane:
        // it falls back to the active tab.
        let s = strip(vec![
            plain_tab("src", true),
            split_child("child", "src", RendererTabSplitAxis::Right, false),
        ]);
        assert_eq!(
            focused_split_source_tab_id(&s, Some("sid-removed")),
            Some("src")
        );
    }

    #[test]
    fn nested_right_then_down_from_focused_right_pane_yields_exactly_three_panes() {
        // Model the end state of: right-split, click right pane, split down. The down child branches
        // from the right pane (`mid`), producing a 3-pane column — left | top-right / bottom-right —
        // NOT a 2x2 grid off the root. The down split's source is the FOCUSED right pane.
        let s = strip(vec![
            plain_tab("src", false),
            split_child("mid", "src", RendererTabSplitAxis::Right, false),
            split_child("bot", "mid", RendererTabSplitAxis::Down, true),
        ]);
        // The focused right pane resolves as the down split's source.
        assert_eq!(
            focused_split_source_tab_id(&s, Some("sid-mid")),
            Some("mid")
        );
        let layout = compute_split_layout(&s, 21, 10).expect("layout");
        // Exactly three panes, not four (a 2x2 would be four).
        assert_eq!(layout.panes.len(), 3);
        let ids: Vec<&str> = layout.panes.iter().map(|p| p.tab_id.as_str()).collect();
        assert_eq!(ids, vec!["src", "mid", "bot"]);
        // Left column spans full height; the right column is split top/bottom.
        assert_eq!(layout.panes[0].region.rows, 10);
        assert_eq!(layout.panes[1].region.col, 11);
        assert_eq!(layout.panes[2].region.col, 11);
        assert!(layout.panes[1].region.row < layout.panes[2].region.row);
    }

    #[test]
    fn nested_split_ux_contract_strip_focus_and_click_all_agree() {
        // One fixture, the full split-pane UX contract: split-right, click the right pane, split-down.
        // The end state is a 3-pane column (left | top-right / bottom-right). This asserts the four
        // user-facing behaviors hold TOGETHER on the same state, guarding against any one regressing
        // while the isolated per-behavior tests still pass:
        //   1. splits are sub-panes of one top-level tab (3 panes, one root chain);
        //   2. the top tab bar projects ONLY the root tab, never the split children;
        //   3. a split from the focused right pane sources that pane (not the root);
        //   4. a mouse click inside each pane resolves to that pane's own session.
        let s = strip(vec![
            plain_tab("src", false),
            split_child("mid", "src", RendererTabSplitAxis::Right, false),
            split_child("bot", "mid", RendererTabSplitAxis::Down, true),
        ]);

        // (1) Exactly three panes off a single root chain — sub-panes, not new top-level tabs.
        let layout = compute_split_layout(&s, 21, 10).expect("layout");
        assert_eq!(layout.panes.len(), 3);

        // (2) The top tab strip shows only the root tab; both split children are absent.
        assert_eq!(
            compose_tab_strip_text(Some(&s)).as_deref(),
            Some("win [src]")
        );

        // (3) Splitting from the focused right pane sources that pane (`mid`), not the root (`src`).
        assert_eq!(
            focused_split_source_tab_id(&s, Some("sid-mid")),
            Some("mid")
        );

        // (4) A click inside each pane resolves to that pane's own session. Pick a cell strictly inside
        // each region so the hit-test is unambiguous (avoids divider rows/cols).
        for pane in &layout.panes {
            let col = (pane.region.col + pane.region.cols / 2) as usize;
            let row = (pane.region.row + pane.region.rows / 2) as usize;
            assert_eq!(
                layout_pane_at_cell(&layout, col, row).map(|p| p.session_id.as_str()),
                Some(format!("sid-{}", pane.tab_id).as_str()),
                "click at center of pane {} should focus its own session",
                pane.tab_id
            );
        }
    }

    // --- Divider drag-resize ---

    #[test]
    fn default_ratios_keep_split_geometry_byte_identical() {
        // The empty SplitRatios (every split 0.5) must reproduce the historical even split exactly, so
        // the `_with` path is a strict superset of the unparameterized one.
        let tabs = vec![
            plain_tab("src", false),
            split_child("mid", "src", RendererTabSplitAxis::Right, false),
            split_child("bot", "mid", RendererTabSplitAxis::Down, true),
        ];
        let plain = compute_split_layout(&strip(tabs.clone()), 21, 10).expect("layout");
        let with = compute_split_layout_with(&strip(tabs), 21, 10, &SplitRatios::default())
            .expect("layout");
        assert_eq!(plain, with);
    }

    #[test]
    fn split_first_extent_clamps_and_matches_even_split_at_half() {
        // 0.5 reproduces floor((total-1)/2) for both even and odd budgets.
        assert_eq!(split_first_extent(21, 0.5), Some(10)); // (21-1)/2
        assert_eq!(split_first_extent(20, 0.5), Some(9)); // (20-1)/2 = 9 (floor)
                                                          // Extreme ratios never collapse a pane: first stays in [1, available-1].
        assert_eq!(split_first_extent(21, 0.0), Some(1));
        assert_eq!(split_first_extent(21, 1.0), Some(19)); // available=20 → max first 19
                                                           // Too small to split.
        assert_eq!(split_first_extent(2, 0.5), None);
    }

    #[test]
    fn divider_hit_test_identifies_vertical_horizontal_and_nested_dividers() {
        // src --Right--> mid --Down--> bot: a top-level vertical divider plus a nested horizontal one.
        let tabs = vec![
            plain_tab("src", false),
            split_child("mid", "src", RendererTabSplitAxis::Right, false),
            split_child("bot", "mid", RendererTabSplitAxis::Down, true),
        ];
        let targets = split_divider_targets(&strip(tabs), 21, 10, &SplitRatios::default());
        assert_eq!(targets.len(), 2);

        // Vertical (Right) divider at col 10 spanning all rows — its child is `mid`.
        let v = divider_target_at_cell(&targets, 10, 5).expect("vertical divider hit");
        assert_eq!(v.child_tab_id, "mid");
        assert_eq!(v.axis, RendererTabSplitAxis::Right);

        // Nested horizontal (Down) divider lives in the right column (col >= 11) — its child is `bot`.
        let h_row = targets
            .iter()
            .find(|t| t.child_tab_id == "bot")
            .expect("nested target")
            .divider
            .row;
        let h = divider_target_at_cell(&targets, 14, h_row).expect("horizontal divider hit");
        assert_eq!(h.child_tab_id, "bot");
        assert_eq!(h.axis, RendererTabSplitAxis::Down);

        // A cell inside a pane (not on any divider) hits nothing.
        assert!(divider_target_at_cell(&targets, 2, 2).is_none());
    }

    #[test]
    fn dragging_vertical_divider_changes_only_that_column_allocation() {
        let tabs = vec![
            plain_tab("src", false),
            split_child("child", "src", RendererTabSplitAxis::Right, true),
        ];
        let s = strip(tabs);
        let even = compute_split_frame(&s.tabs, "child", 21, 10).expect("frame");
        assert_eq!(even.first.cols, 10);
        assert_eq!(even.second.cols, 10);

        // Drag the divider toward col 6: the parent (left) column shrinks, the child (right) grows;
        // total columns and all rows are unchanged.
        let mut ratios = SplitRatios::default();
        let target = &split_divider_targets(&s, 21, 10, &ratios)[0];
        let share = divider_drag_share(target, 6, 5).expect("share");
        ratios.set_first_share("child", share);
        let dragged = compute_split_frame_with(&s.tabs, "child", 21, 10, &ratios).expect("frame");
        assert_eq!(dragged.first.cols, 6);
        assert_eq!(dragged.second.cols, 21 - 1 - 6);
        // Rows untouched on a vertical drag.
        assert_eq!(dragged.first.rows, 10);
        assert_eq!(dragged.second.rows, 10);
    }

    #[test]
    fn dragging_horizontal_divider_changes_only_that_row_allocation() {
        let tabs = vec![
            plain_tab("top", false),
            split_child("bot", "top", RendererTabSplitAxis::Down, true),
        ];
        let s = strip(tabs);
        let mut ratios = SplitRatios::default();
        let target = &split_divider_targets(&s, 12, 11, &ratios)[0];
        // Drag toward row 3 (parent top pane shrinks to 3 rows).
        let share = divider_drag_share(target, 6, 3).expect("share");
        ratios.set_first_share("bot", share);
        let dragged = compute_split_frame_with(&s.tabs, "bot", 12, 11, &ratios).expect("frame");
        assert_eq!(dragged.first.rows, 3);
        assert_eq!(dragged.second.rows, 11 - 1 - 3);
        // Columns untouched on a horizontal drag.
        assert_eq!(dragged.first.cols, 12);
        assert_eq!(dragged.second.cols, 12);
    }

    #[test]
    fn nested_drag_changes_nested_split_without_changing_root() {
        // src --Right--> mid --Down--> bot. Drag the NESTED (Down) divider; the root (Right) split's
        // column allocation must stay even.
        let tabs = vec![
            plain_tab("src", false),
            split_child("mid", "src", RendererTabSplitAxis::Right, false),
            split_child("bot", "mid", RendererTabSplitAxis::Down, true),
        ];
        let s = strip(tabs);
        let mut ratios = SplitRatios::default();
        // The nested target splits the right column (region rows 10). Drag its divider toward row 2.
        let nested = split_divider_targets(&s, 21, 10, &ratios)
            .into_iter()
            .find(|t| t.child_tab_id == "bot")
            .expect("nested target");
        let share = divider_drag_share(&nested, nested.region.col + 1, 2).expect("share");
        ratios.set_first_share("bot", share);

        let layout = compute_split_layout_with(&s, 21, 10, &ratios).expect("layout");
        let pane = |id: &str| {
            layout
                .panes
                .iter()
                .find(|p| p.tab_id == id)
                .expect("pane")
                .region
        };
        // Root split unchanged: left column still 10 wide, right column starts at col 11.
        assert_eq!(pane("src").cols, 10);
        assert_eq!(pane("mid").col, 11);
        assert_eq!(pane("bot").col, 11);
        // Nested split moved: mid (top of right column) is now 2 rows tall.
        assert_eq!(pane("mid").rows, 2);
        assert_eq!(pane("bot").rows, 10 - 1 - 2);
    }

    #[test]
    fn clamping_prevents_zero_size_panes_on_extreme_drag() {
        let tabs = vec![
            plain_tab("src", false),
            split_child("child", "src", RendererTabSplitAxis::Right, true),
        ];
        let s = strip(tabs);
        let target = split_divider_targets(&s, 21, 10, &SplitRatios::default())
            .into_iter()
            .next()
            .expect("target");

        // Drag hard against the left edge (col 0) and the right edge (col 20): both panes survive.
        for col in [0u16, 20u16] {
            let mut ratios = SplitRatios::default();
            let share = divider_drag_share(&target, col, 5).expect("share");
            ratios.set_first_share("child", share);
            let frame = compute_split_frame_with(&s.tabs, "child", 21, 10, &ratios).expect("frame");
            assert!(frame.first.cols >= 1, "left pane collapsed at col {col}");
            assert!(frame.second.cols >= 1, "right pane collapsed at col {col}");
        }
        // The ratio store itself never records a value outside the usable band.
        let mut ratios = SplitRatios::default();
        ratios.set_first_share("child", 5.0);
        assert!(ratios.first_share("child") <= 1.0 - MIN_SPLIT_RATIO);
        ratios.set_first_share("child", -5.0);
        assert!(ratios.first_share("child") >= MIN_SPLIT_RATIO);
        // An unset split defaults to the even split.
        assert_eq!(ratios.first_share("other"), DEFAULT_SPLIT_RATIO);
    }

    #[test]
    fn divider_drag_share_is_none_when_region_too_small_to_split() {
        // A region under 3 cells along the split axis cannot host two panes; a drag is a no-op.
        let target = super::RendererDividerTarget {
            child_tab_id: "child".to_string(),
            axis: RendererTabSplitAxis::Right,
            divider: RendererSplitDivider {
                col: 1,
                row: 0,
                length: 4,
                glyph: '|',
            },
            region: RendererPaneRegion {
                col: 0,
                row: 0,
                cols: 2,
                rows: 4,
            },
        };
        assert!(divider_drag_share(&target, 1, 1).is_none());
    }

    // --- Canonical branching split-geometry (the `A/C | B` fix) ---

    /// Helper: assert a layout's panes tile the `cols`x`rows` grid with no overlap, and that the total
    /// pane area equals `cols*rows` minus the cells the dividers consume.
    fn assert_tiles_grid(layout: &super::RendererSplitLayout, cols: u16, rows: u16) {
        // Pairwise non-overlap.
        for a in 0..layout.panes.len() {
            for b in (a + 1)..layout.panes.len() {
                let ra = layout.panes[a].region;
                let rb = layout.panes[b].region;
                let disjoint = ra.col + ra.cols <= rb.col
                    || rb.col + rb.cols <= ra.col
                    || ra.row + ra.rows <= rb.row
                    || rb.row + rb.rows <= ra.row;
                assert!(disjoint, "panes {a} and {b} overlap: {ra:?} vs {rb:?}");
            }
        }
        // In-bounds.
        for p in &layout.panes {
            assert!(
                p.region.col + p.region.cols <= cols,
                "pane past right edge: {p:?}"
            );
            assert!(
                p.region.row + p.region.rows <= rows,
                "pane past bottom edge: {p:?}"
            );
            assert!(
                p.region.cols >= 1 && p.region.rows >= 1,
                "degenerate pane: {p:?}"
            );
        }
        // Area accounting: every grid cell is in exactly one pane or one divider, never both/neither.
        let mut covered = 0u32;
        for p in &layout.panes {
            covered += u32::from(p.region.cols) * u32::from(p.region.rows);
        }
        let mut divider_cells = 0u32;
        // Dividers can share crossing cells; count unique cells via a set for correctness.
        let mut seen = std::collections::BTreeSet::new();
        for d in &layout.dividers {
            match d.glyph {
                '|' => {
                    for r in d.row..d.row + d.length {
                        seen.insert((d.col, r));
                    }
                }
                '-' => {
                    for c in d.col..d.col + d.length {
                        seen.insert((c, d.row));
                    }
                }
                g => panic!("unexpected divider glyph {g:?}"),
            }
        }
        divider_cells += seen.len() as u32;
        assert_eq!(
            covered + divider_cells,
            u32::from(cols) * u32::from(rows),
            "panes + dividers must exactly cover the grid"
        );
    }

    #[test]
    fn split_left_pane_down_yields_three_right_main_branching() {
        // `A | B`, A is the left pane; splitting A DOWN must yield `A/C | B`: A and the new C stacked in
        // the LEFT column, B untouched full-height on the RIGHT. Chain: a (root) -> b (Right child of a)
        // -> c (Down child of a). The active pane is c.
        let s = strip(vec![
            plain_tab("a", false),
            split_child("b", "a", RendererTabSplitAxis::Right, false),
            split_child("c", "a", RendererTabSplitAxis::Down, true),
        ]);
        let layout = compute_split_layout(&s, 21, 10).expect("layout");
        assert_eq!(layout.panes.len(), 3);
        let pane = |id: &str| {
            layout
                .panes
                .iter()
                .find(|p| p.tab_id == id)
                .unwrap_or_else(|| panic!("pane {id}"))
                .region
        };
        let a = pane("a");
        let b = pane("b");
        let c = pane("c");
        // A and C share the LEFT column (same col + cols), A on top, C below.
        assert_eq!(a.col, c.col, "A and C share the left column origin");
        assert_eq!(a.cols, c.cols, "A and C share the left column width");
        assert!(a.row < c.row, "A is above C");
        // B is full-height on the right (rows span the whole grid), to the right of A/C.
        assert_eq!(b.rows, 10, "B is full height");
        assert!(b.col > a.col + a.cols - 1, "B is right of the left column");
        assert_eq!(b.col, a.cols + 1, "B starts past the left column + divider");
        assert_tiles_grid(&layout, 21, 10);
    }

    #[test]
    fn split_right_pane_down_yields_three_left_main_branching() {
        // `A | B`, splitting the RIGHT pane B down -> `A | B/C`: A full-height left; B top-right, C
        // bottom-right. Chain: a (root) -> b (Right child of a) -> c (Down child of b). Active = c.
        let s = strip(vec![
            plain_tab("a", false),
            split_child("b", "a", RendererTabSplitAxis::Right, false),
            split_child("c", "b", RendererTabSplitAxis::Down, true),
        ]);
        let layout = compute_split_layout(&s, 21, 10).expect("layout");
        assert_eq!(layout.panes.len(), 3);
        let pane = |id: &str| {
            layout
                .panes
                .iter()
                .find(|p| p.tab_id == id)
                .unwrap_or_else(|| panic!("pane {id}"))
                .region
        };
        let a = pane("a");
        let b = pane("b");
        let c = pane("c");
        // A full-height left.
        assert_eq!(a.col, 0);
        assert_eq!(a.rows, 10, "A is full height");
        // B and C share the right column, B above C.
        assert_eq!(b.col, c.col, "B and C share the right column origin");
        assert_eq!(b.cols, c.cols, "B and C share the right column width");
        assert!(b.row < c.row, "B is above C");
        assert!(b.col > a.col + a.cols - 1, "right column is right of A");
        assert_tiles_grid(&layout, 21, 10);
    }

    #[test]
    fn two_pane_canonical_is_byte_identical_to_old_layout() {
        // Regression guard: the 2-pane case must be byte-for-byte what the historical even-split path
        // produced. Build `a | child` and compare the full layout (panes + dividers) against the known
        // even-split geometry (left 10 cols, divider at col 10, right col 11 cols 10).
        let s = strip(vec![
            plain_tab("a", true),
            split_child("child", "a", RendererTabSplitAxis::Right, false),
        ]);
        let layout = compute_split_layout(&s, 21, 10).expect("layout");
        let expected = super::RendererSplitLayout {
            panes: vec![
                super::RendererLayoutPane {
                    tab_id: "a".to_string(),
                    session_id: "sid-a".to_string(),
                    region: RendererPaneRegion {
                        col: 0,
                        row: 0,
                        cols: 10,
                        rows: 10,
                    },
                    active: true,
                },
                super::RendererLayoutPane {
                    tab_id: "child".to_string(),
                    session_id: "sid-child".to_string(),
                    region: RendererPaneRegion {
                        col: 11,
                        row: 0,
                        cols: 10,
                        rows: 10,
                    },
                    active: false,
                },
            ],
            dividers: vec![RendererSplitDivider {
                col: 10,
                row: 0,
                length: 10,
                glyph: '|',
            }],
        };
        assert_eq!(layout, expected);
    }

    #[test]
    fn unrepresentable_chain_falls_back_and_still_covers_grid() {
        // A 4-deep chain (5 panes) overflows the engine's 4-pane cap, and an intermediate 3-pane source
        // returns Ok(None) -> the canonical replay aborts and the linear `place_split_chain` fallback
        // runs. The result must still be a valid layout (no panic) whose panes cover the grid.
        let s = strip(vec![
            plain_tab("a", false),
            split_child("b", "a", RendererTabSplitAxis::Right, false),
            split_child("c", "b", RendererTabSplitAxis::Down, false),
            split_child("d", "c", RendererTabSplitAxis::Right, false),
            split_child("e", "d", RendererTabSplitAxis::Down, true),
        ]);
        let layout = compute_split_layout(&s, 41, 21).expect("fallback layout");
        // The linear fallback walks first_split_child, so it tiles all reachable panes without panic.
        assert!(
            layout.panes.len() >= 2,
            "fallback still produces multiple panes"
        );
        // Pairwise non-overlap holds for the fallback geometry too.
        for a in 0..layout.panes.len() {
            for b in (a + 1)..layout.panes.len() {
                let ra = layout.panes[a].region;
                let rb = layout.panes[b].region;
                let disjoint = ra.col + ra.cols <= rb.col
                    || rb.col + rb.cols <= ra.col
                    || ra.row + ra.rows <= rb.row
                    || rb.row + rb.rows <= ra.row;
                assert!(disjoint, "fallback panes {a},{b} overlap");
            }
        }
    }

    #[test]
    fn fourth_split_from_side_stack_stays_visible_in_four_right_main() {
        // User repro: A|B, split A down -> A/C | B, then split C down. The fourth pane must not force
        // the renderer into the old linear fallback where only A|B are visible and C/D sit off to the
        // side until a pane is removed.
        use RendererTabSplitAxis::{Down, Right};
        let s = strip(vec![
            plain_tab("A", false),
            split_child("B", "A", Right, false),
            split_child("C", "A", Down, false),
            split_child("D", "C", Down, true),
        ]);
        let root = s.tabs.iter().find(|t| t.tab_id == "A").unwrap();
        let (model, _bridge) =
            super::replay_canonical_model(&s.tabs, root).expect("canonical replay");
        assert_eq!(model.layout, super::CanonicalLayout::FourRightMain);
        let layout = compute_split_layout(&s, 41, 21).expect("layout");
        assert_eq!(layout.panes.len(), 4, "all four panes render");
        assert_tiles_grid(&layout, 41, 21);

        let pane = |id: &str| {
            layout
                .panes
                .iter()
                .find(|p| p.tab_id == id)
                .unwrap_or_else(|| panic!("pane {id}"))
                .region
        };
        let a = pane("A");
        let b = pane("B");
        let c = pane("C");
        let d = pane("D");
        assert_eq!(a.col, c.col, "A and C stay in the left stack");
        assert_eq!(c.col, d.col, "D is added to the same left stack");
        assert_eq!(a.cols, c.cols);
        assert_eq!(c.cols, d.cols);
        assert!(
            a.row < c.row && c.row < d.row,
            "left stack is top-to-bottom"
        );
        assert!(b.col > a.col + a.cols - 1, "B remains the right main pane");
        assert_eq!(b.rows, 21, "B stays full height");
    }

    #[test]
    fn four_bottom_main_renders_dragged_pane_in_top_row_and_expanded_bottom_row() {
        // User repro: starting from A|B / C|D, drag C into the top row. The shell persists this as
        // A|B|C over D: B right of A, C right of B, D down from A. The renderer must not replay that
        // chain as `A/D | B | C`, which hides the intended bottom full-row pane.
        use RendererTabSplitAxis::{Down, Right};
        let s = strip(vec![
            plain_tab("A", false),
            split_child("B", "A", Right, false),
            split_child("C", "B", Right, true),
            split_child("D", "A", Down, false),
        ]);
        let root = s.tabs.iter().find(|t| t.tab_id == "A").unwrap();
        let (model, _bridge) =
            super::replay_canonical_model(&s.tabs, root).expect("canonical replay");
        assert_eq!(model.layout, super::CanonicalLayout::FourBottomMain);
        let layout = compute_split_layout(&s, 41, 21).expect("layout");
        assert_eq!(layout.panes.len(), 4, "all four panes render");
        assert_tiles_grid(&layout, 41, 21);

        let pane = |id: &str| {
            layout
                .panes
                .iter()
                .find(|p| p.tab_id == id)
                .unwrap_or_else(|| panic!("pane {id}"))
                .region
        };
        let a = pane("A");
        let b = pane("B");
        let c = pane("C");
        let d = pane("D");
        assert_eq!(a.row, b.row);
        assert_eq!(b.row, c.row);
        assert_eq!(a.rows, b.rows);
        assert_eq!(b.rows, c.rows);
        assert!(a.col < b.col && b.col < c.col, "top row is A|B|C");
        assert_eq!(d.col, 0);
        assert_eq!(d.cols, 41);
        assert!(d.row > a.row + a.rows - 1, "D is the bottom full row");
    }

