    fn hit_test_settings_panel(n: usize) -> super::RendererDashboardPanel {
        let lines: Vec<String> = (0..n).map(|i| format!("l{i}")).collect();
        let rows: Vec<_> = (0..n)
            .map(|i| hit_test_row(&format!("r{i}"), None))
            .collect();
        super::RendererDashboardPanel::settings_with_rows(lines, rows)
    }

    #[test]
    fn hit_test_settings_panel_returns_row_for_pixels_in_first_and_later_rows() {
        use super::hit_test_settings_panel_row_pixel;
        let panel = hit_test_settings_panel(3);
        // Panel band starts at y=100, each row is 20px tall, width 200, cell 10x20.
        let (i0, r0) =
            hit_test_settings_panel_row_pixel(&panel, 5.0, 105.0, 100.0, 200.0, 10.0, 20.0)
                .unwrap();
        assert_eq!(i0, 0);
        assert_eq!(r0.id, "r0");
        let (i2, r2) =
            hit_test_settings_panel_row_pixel(&panel, 5.0, 145.0, 100.0, 200.0, 10.0, 20.0)
                .unwrap();
        assert_eq!(i2, 2);
        assert_eq!(r2.id, "r2");
    }

    #[test]
    fn hit_test_settings_panel_row_boundaries_are_start_inclusive_end_exclusive() {
        use super::hit_test_settings_panel_row_pixel;
        let panel = hit_test_settings_panel(2);
        // Row 0 owns [100,120); row 1 owns [120,140). Band bottom 140 is exclusive.
        assert_eq!(
            hit_test_settings_panel_row_pixel(&panel, 0.0, 100.0, 100.0, 200.0, 10.0, 20.0)
                .unwrap()
                .0,
            0
        );
        assert_eq!(
            hit_test_settings_panel_row_pixel(&panel, 0.0, 119.999, 100.0, 200.0, 10.0, 20.0)
                .unwrap()
                .0,
            0
        );
        assert_eq!(
            hit_test_settings_panel_row_pixel(&panel, 0.0, 120.0, 100.0, 200.0, 10.0, 20.0)
                .unwrap()
                .0,
            1
        );
        assert!(
            hit_test_settings_panel_row_pixel(&panel, 0.0, 140.0, 100.0, 200.0, 10.0, 20.0)
                .is_none()
        );
    }

