    #[test]
    fn hit_test_dashboard_panel_resolves_only_focusable_rows() {
        use super::hit_test_dashboard_panel_row_pixel;
        // Lines: [title, summary, header, active-task]. Only the active-task row is focusable.
        let lines = vec![
            "Dashboard".to_string(),
            "running=1".to_string(),
            "Active (1/1)".to_string(),
            "[running] do x".to_string(),
        ];
        let rows = vec![
            dashboard_row(None),
            dashboard_row(None),
            dashboard_row(None),
            dashboard_row(Some(("w1", "t1"))),
        ];
        let panel = super::RendererDashboardPanel::dashboard_with_rows(lines, rows);
        // Band starts at y=100, 20px rows, width 200, cell 10x20.
        // Clicking the title row (index 0) resolves nothing (static chrome).
        assert!(
            hit_test_dashboard_panel_row_pixel(&panel, 5.0, 105.0, 100.0, 200.0, 10.0, 20.0)
                .is_none()
        );
        // Clicking the active-task row (index 3, y in [160,180)) resolves with the focus tab id.
        let (idx, row) =
            hit_test_dashboard_panel_row_pixel(&panel, 5.0, 165.0, 100.0, 200.0, 10.0, 20.0)
                .expect("focusable row resolves");
        assert_eq!(idx, 3);
        assert_eq!(row.focus_tab_id.as_deref(), Some("t1"));
        assert_eq!(row.focus_window_id.as_deref(), Some("w1"));
    }

