    #[test]
    fn hit_test_dock_row_maps_y_to_row_within_the_x_band() {
        use super::{hit_test_dock_row_pixel, DockRowKind};
        // Three rows, dock_top=24, row_h=20, dock_width=268. Row i owns [24+20i, 24+20(i+1)).
        let dock = dock_model(vec![
            dock_row(0, DockRowKind::Project, "proj"),
            dock_row(1, DockRowKind::Window, "win"),
            dock_row(2, DockRowKind::Pane, "pane"),
        ]);
        // Row 0: y in [24,44).
        let (i0, r0) = hit_test_dock_row_pixel(&dock, 5.0, 24.0, 24.0, 268.0, 20.0).unwrap();
        assert_eq!(i0, 0);
        assert_eq!(r0.label, "proj");
        // Row 2: y in [64,84).
        let (i2, r2) = hit_test_dock_row_pixel(&dock, 200.0, 70.0, 24.0, 268.0, 20.0).unwrap();
        assert_eq!(i2, 2);
        assert_eq!(r2.label, "pane");
    }

    #[test]
    fn hit_test_dock_row_band_boundaries_are_start_inclusive_end_exclusive() {
        use super::{hit_test_dock_row_pixel, DockRowKind};
        let dock = dock_model(vec![
            dock_row(0, DockRowKind::Project, "a"),
            dock_row(0, DockRowKind::Project, "b"),
        ]);
        // Row 0 owns [24,44); row 1 owns [44,64). Band bottom 64 is exclusive.
        assert_eq!(
            hit_test_dock_row_pixel(&dock, 0.0, 24.0, 24.0, 268.0, 20.0)
                .unwrap()
                .0,
            0
        );
        assert_eq!(
            hit_test_dock_row_pixel(&dock, 0.0, 43.999, 24.0, 268.0, 20.0)
                .unwrap()
                .0,
            0
        );
        assert_eq!(
            hit_test_dock_row_pixel(&dock, 0.0, 44.0, 24.0, 268.0, 20.0)
                .unwrap()
                .0,
            1
        );
        // y above the dock top and y at/below the band bottom both resolve nothing.
        assert!(hit_test_dock_row_pixel(&dock, 0.0, 23.999, 24.0, 268.0, 20.0).is_none());
        assert!(hit_test_dock_row_pixel(&dock, 0.0, 64.0, 24.0, 268.0, 20.0).is_none());
    }

    #[test]
    fn hit_test_dock_row_rejects_x_outside_the_column_and_empty_rows() {
        use super::{hit_test_dock_row_pixel, DockRowKind};
        let dock = dock_model(vec![dock_row(0, DockRowKind::Project, "a")]);
        // x at/past the dock width is on the grid, not the dock.
        assert!(hit_test_dock_row_pixel(&dock, 268.0, 30.0, 24.0, 268.0, 20.0).is_none());
        assert!(hit_test_dock_row_pixel(&dock, -1.0, 30.0, 24.0, 268.0, 20.0).is_none());
        // x just inside the right edge still resolves.
        assert!(hit_test_dock_row_pixel(&dock, 267.999, 30.0, 24.0, 268.0, 20.0).is_some());
        // An empty dock resolves nothing.
        let empty = dock_model(Vec::new());
        assert!(hit_test_dock_row_pixel(&empty, 5.0, 30.0, 24.0, 268.0, 20.0).is_none());
        // Degenerate width / row height resolve nothing.
        assert!(hit_test_dock_row_pixel(&dock, 5.0, 30.0, 24.0, 0.0, 20.0).is_none());
        assert!(hit_test_dock_row_pixel(&dock, 5.0, 30.0, 24.0, 268.0, 0.0).is_none());
    }

    #[test]
    fn dock_press_disclosure_band_only_fires_on_collapsible_rows_left_caret() {
        use super::dock_press_is_disclosure;
        // cell_width 10 → disclosure band is [0, 20). A collapsible row (expanded=Some) fires inside
        // the band and selects (no toggle) outside it.
        assert!(dock_press_is_disclosure(0.0, Some(false), 10.0));
        assert!(dock_press_is_disclosure(19.999, Some(true), 10.0));
        assert!(!dock_press_is_disclosure(20.0, Some(false), 10.0));
        assert!(!dock_press_is_disclosure(-0.1, Some(false), 10.0));
        // A non-collapsible row (window/pane, expanded=None) never has a disclosure band.
        assert!(!dock_press_is_disclosure(0.0, None, 10.0));
        assert!(!dock_press_is_disclosure(5.0, None, 10.0));
    }

    #[test]
    fn dock_collapse_button_sits_in_the_top_right_corner_and_needs_room() {
        use super::{dock_collapse_button_rect, point_in_rect};
        // dock_width 268, dock_top 24, cell_h 20 → button rect [248, 24, 20, 20].
        let rect = dock_collapse_button_rect(268.0, 24.0, 20.0).expect("room for the button");
        assert_eq!(rect, [248.0, 24.0, 20.0, 20.0]);
        // A press inside the corner square hits the button; the row body to its left does not.
        assert!(point_in_rect(250.0, 30.0, rect));
        assert!(point_in_rect(248.0, 24.0, rect)); // start-inclusive
        assert!(!point_in_rect(247.999, 30.0, rect)); // just left of the button
        assert!(!point_in_rect(268.0, 30.0, rect)); // end-exclusive on x
        assert!(!point_in_rect(250.0, 44.0, rect)); // end-exclusive on y
                                                    // A dock no wider than one cell has no room for the button.
        assert!(dock_collapse_button_rect(20.0, 24.0, 20.0).is_none());
        assert!(dock_collapse_button_rect(19.0, 24.0, 20.0).is_none());
        // Degenerate cell height resolves nothing.
        assert!(dock_collapse_button_rect(268.0, 24.0, 0.0).is_none());
    }

    #[test]
    fn hit_test_dock_row_resolves_any_row_including_targetless_window_headers() {
        use super::{hit_test_dock_row_pixel, DockRowKind};
        // Unlike the dashboard hit-test, the dock resolves a targetless row (a window header) too,
        // so the caller can decide to ignore it or toggle a disclosure.
        let dock = dock_model(vec![dock_row(1, DockRowKind::Window, "header-no-target")]);
        let (idx, row) = hit_test_dock_row_pixel(&dock, 5.0, 30.0, 24.0, 268.0, 20.0).unwrap();
        assert_eq!(idx, 0);
        assert!(row.focus_tab_id.is_none());
        assert!(row.revive_tab_id.is_none());
        assert!(row.select_project_id.is_none());
    }

    #[test]
    fn emit_dashboard_row_activated_round_trips_focus_target_and_skips_unfocusable() {
        use super::{emit_dashboard_row_activated, RendererEvent};
        let (tx, rx) = std::sync::mpsc::channel();
        // A focusable row emits exactly one DashboardRowActivated carrying the focus target.
        assert!(emit_dashboard_row_activated(
            Some(&tx),
            &dashboard_row(Some(("w9", "t9")))
        ));
        match rx.recv().expect("event round-trips") {
            RendererEvent::DashboardRowActivated { window_id, tab_id } => {
                assert_eq!(window_id.as_deref(), Some("w9"));
                assert_eq!(tab_id, "t9");
            }
            other => panic!("unexpected event: {other:?}"),
        }
        // An unfocusable row (no tab id) emits nothing and never panics.
        assert!(!emit_dashboard_row_activated(
            Some(&tx),
            &dashboard_row(None)
        ));
        assert!(rx.try_recv().is_err());
        // No sink is a non-fatal false, not a panic.
        assert!(!emit_dashboard_row_activated(
            None,
            &dashboard_row(Some(("w", "t")))
        ));
    }

    #[test]
    fn hit_test_dashboard_panel_resolves_stashed_revive_rows() {
        use super::hit_test_dashboard_panel_row_pixel;
        // Lines: [title, summary, "Stashed" header, stashed row]. Only the stashed row is actionable.
        let lines = vec![
            "Dashboard".to_string(),
            "running=0".to_string(),
            "Stashed (1/1)".to_string(),
            "⟲ dormant".to_string(),
        ];
        let rows = vec![
            dashboard_row(None),
            dashboard_row(None),
            dashboard_row(None),
            revive_row(Some(("w1", "t1"))),
        ];
        let panel = super::RendererDashboardPanel::dashboard_with_rows(lines, rows);
        // Header row (index 2) is static chrome → no resolve.
        assert!(
            hit_test_dashboard_panel_row_pixel(&panel, 5.0, 145.0, 100.0, 200.0, 10.0, 20.0)
                .is_none()
        );
        // The stashed row (index 3, y in [160,180)) resolves carrying the revive target, NOT a focus
        // target.
        let (idx, row) =
            hit_test_dashboard_panel_row_pixel(&panel, 5.0, 165.0, 100.0, 200.0, 10.0, 20.0)
                .expect("revive row resolves");
        assert_eq!(idx, 3);
        assert_eq!(row.focus_tab_id, None);
        assert_eq!(row.revive_tab_id.as_deref(), Some("t1"));
        assert_eq!(row.revive_window_id.as_deref(), Some("w1"));
    }

    #[test]
    fn emit_dashboard_row_revive_requested_round_trips_target_and_skips_non_revive() {
        use super::{emit_dashboard_row_revive_requested, RendererEvent};
        let (tx, rx) = std::sync::mpsc::channel();
        // A revive row emits exactly one DashboardRowReviveRequested carrying the revive target.
        assert!(emit_dashboard_row_revive_requested(
            Some(&tx),
            &revive_row(Some(("w9", "t9")))
        ));
        match rx.recv().expect("event round-trips") {
            RendererEvent::DashboardRowReviveRequested { window_id, tab_id } => {
                assert_eq!(window_id.as_deref(), Some("w9"));
                assert_eq!(tab_id, "t9");
            }
            other => panic!("unexpected event: {other:?}"),
        }
        // A focusable (non-revive) row emits nothing through the revive emitter.
        assert!(!emit_dashboard_row_revive_requested(
            Some(&tx),
            &dashboard_row(Some(("w", "t")))
        ));
        assert!(rx.try_recv().is_err());
        // No sink is a non-fatal false, not a panic.
        assert!(!emit_dashboard_row_revive_requested(
            None,
            &revive_row(Some(("w", "t")))
        ));
    }

