    #[test]
    fn hit_test_rows_beyond_max_are_not_hit_testable() {
        use super::{hit_test_settings_panel_row_pixel, DASHBOARD_PANEL_MAX_ROWS};
        // More lines + rows than the cap; the row just past the cap is not hit-testable even
        // though metadata exists, because visible-row clamping uses dashboard_panel_rows.
        let panel = hit_test_settings_panel(DASHBOARD_PANEL_MAX_ROWS + 3);
        let last_visible = DASHBOARD_PANEL_MAX_ROWS - 1;
        // y inside the last visible row.
        let y_last = 100.0 + (last_visible as f32) * 20.0 + 5.0;
        assert_eq!(
            hit_test_settings_panel_row_pixel(&panel, 5.0, y_last, 100.0, 200.0, 10.0, 20.0)
                .unwrap()
                .0,
            last_visible
        );
        // y where the first clamped-away row would be.
        let y_clamped = 100.0 + (DASHBOARD_PANEL_MAX_ROWS as f32) * 20.0 + 5.0;
        assert!(hit_test_settings_panel_row_pixel(
            &panel, 5.0, y_clamped, 100.0, 200.0, 10.0, 20.0
        )
        .is_none());
    }

    #[test]
    fn hit_test_degenerate_metrics_return_none() {
        use super::hit_test_settings_panel_row_pixel;
        let panel = hit_test_settings_panel(2);
        for (w, cw, ch) in [
            (0.0_f32, 10.0_f32, 20.0_f32),
            (200.0, 0.0, 20.0),
            (200.0, 10.0, 0.0),
            (-1.0, 10.0, 20.0),
            (200.0, -1.0, 20.0),
            (200.0, 10.0, -1.0),
            (f32::NAN, 10.0, 20.0),
            (200.0, f32::NAN, 20.0),
            (200.0, 10.0, f32::NAN),
            (f32::INFINITY, 10.0, 20.0),
            (200.0, f32::INFINITY, 20.0),
            (200.0, 10.0, f32::INFINITY),
        ] {
            assert!(
                hit_test_settings_panel_row_pixel(&panel, 5.0, 105.0, 100.0, w, cw, ch).is_none(),
                "expected None for width={w} cell_width={cw} cell_height={ch}"
            );
        }
    }

    #[test]
    fn fit_settings_panel_lines_marks_only_selected_row() {
        use super::{fit_settings_panel_lines, SETTINGS_PANEL_SELECTION_MARKER};
        let panel = hit_test_settings_panel(3);
        // Selecting row 1 prepends the marker to exactly that line; rows 0 and 2 are plain.
        let lines = fit_settings_panel_lines(&panel, Some(1), 40);
        assert_eq!(lines[0], "l0");
        assert_eq!(lines[1], format!("{SETTINGS_PANEL_SELECTION_MARKER}l1"));
        assert_eq!(lines[2], "l2");
        // Selecting row 0 vs none differs only on row 0.
        let sel0 = fit_settings_panel_lines(&panel, Some(0), 40);
        let none = fit_settings_panel_lines(&panel, None, 40);
        assert_eq!(sel0[0], format!("{SETTINGS_PANEL_SELECTION_MARKER}l0"));
        assert_eq!(none[0], "l0");
        assert_eq!(&sel0[1..], &none[1..]);
    }

