    #[test]
    fn settings_panel_clamped_navigation_reports_no_change_so_no_event_emits() {
        use super::{navigate_settings_panel_selection, SettingsPanelNavKey};
        // The click/keyboard callers emit only when the new index differs from the prior selection
        // (the `Some(idx) if Some(idx) != current` guard). A no-op clamp at the last row returns the
        // SAME index, so `Some(idx) != current` is false and no event is sent. This proves the
        // emission predicate at the source: a settle at first/last row never re-emits.
        let panel = hit_test_settings_panel(3);
        let current = Some(2usize); // already at the last selectable row
        let next =
            navigate_settings_panel_selection(Some(&panel), current, SettingsPanelNavKey::Down);
        assert_eq!(next, Some(2));
        let would_emit = matches!(next, Some(idx) if Some(idx) != current);
        assert!(
            !would_emit,
            "a clamped no-op Down at the last row must not emit"
        );
        // Same at the top edge: Up from row 0 stays at 0, so no emission.
        let top = Some(0usize);
        let up = navigate_settings_panel_selection(Some(&panel), top, SettingsPanelNavKey::Up);
        assert_eq!(up, Some(0));
        assert!(!matches!(up, Some(idx) if Some(idx) != top));
    }

    #[test]
    fn settings_panel_navigation_to_new_row_reports_change_so_event_emits() {
        use super::{navigate_settings_panel_selection, SettingsPanelNavKey};
        // The complementary case: a real move to a different row trips the emission predicate.
        let panel = hit_test_settings_panel(3);
        let current = Some(0usize);
        let next =
            navigate_settings_panel_selection(Some(&panel), current, SettingsPanelNavKey::Down);
        assert_eq!(next, Some(1));
        assert!(matches!(next, Some(idx) if Some(idx) != current));
    }

