    #[test]
    fn settings_panel_activation_skips_emission_when_no_row_or_out_of_range() {
        use super::emit_settings_panel_row_activated;
        // The Enter handler looks the selected index back up from the live panel and emits only when
        // it resolves to a row. Mirror that source predicate: a None selection and an out-of-range
        // index both resolve to no row, so the caller never reaches the emit. (Bounds match the panel
        // the draw/hit-test paths use.)
        let panel = hit_test_settings_panel(2);
        let selected: Option<usize> = None;
        let would_emit_none = selected
            .and_then(|idx| panel.settings_rows.get(idx))
            .is_some();
        assert!(!would_emit_none, "no selected row must not emit activation");

        let stale = Some(9usize); // beyond the 2 rows -> stale/out-of-range
        let resolved = stale.and_then(|idx| panel.settings_rows.get(idx));
        assert!(
            resolved.is_none(),
            "a stale/out-of-range selection resolves to no row, so activation is suppressed"
        );

        // The complementary in-range case DOES resolve to a row (so the live handler would emit).
        let (tx, rx) = std::sync::mpsc::channel();
        let row = panel
            .settings_rows
            .get(1)
            .expect("row 1 exists on a 2-row panel");
        assert!(emit_settings_panel_row_activated(Some(&tx), 1, row));
        assert!(rx.recv().is_ok(), "an in-range selected row activates");
    }

    #[test]
    fn fit_panel_line_truncates_deterministically_and_strips_control_chars() {
        use super::fit_panel_line;
        // Control chars (newline/tab/CR) are replaced by spaces, never dropped or mid-codepoint.
        assert_eq!(fit_panel_line("a\tb\nc\r", 10), "a b c ");
        // Truncation is by char to exactly `cols`, deterministic on repeat.
        let long = "abcdefghij";
        assert_eq!(fit_panel_line(long, 4), "abcd");
        assert_eq!(fit_panel_line(long, 4), "abcd");
        // Multi-byte chars truncate on codepoint boundaries (never split a char).
        let multi = "áéíóú";
        let fit = fit_panel_line(multi, 3);
        assert_eq!(fit.chars().count(), 3);
        assert_eq!(fit, "áéí");
        // cols == 0 -> empty; shorter-than-cols lines pass through unchanged.
        assert_eq!(fit_panel_line("hello", 0), "");
        assert_eq!(fit_panel_line("hi", 10), "hi");
    }

    #[test]
    fn renderer_launch_can_carry_dashboard_panel() {
        use super::{RendererDashboardPanel, RendererLaunch};
        // Compile-shape proof: a launch contract can carry a panel without a window/GPU.
        let launch = RendererLaunch {
            socket_path: "/tmp/sock".into(),
            session_id: "sid".into(),
            window_title: None,
            status_label: None,
            tab_strip: None,
            top_tab_bar: false,
            dashboard_panel: Some(RendererDashboardPanel::dashboard(vec![
                "Dashboard".into(),
                "running 1".into(),
            ])),
            picker: None,
            command_palette: None,
            font_size_px: None,
            theme: None,
            react_chrome: None,
        };
        let panel = launch.dashboard_panel.expect("panel present");
        assert_eq!(panel.lines, vec!["Dashboard", "running 1"]);
        // A `None` panel is the byte-identical historical launch shape.
        let plain = RendererLaunch {
            socket_path: "/tmp/sock".into(),
            session_id: "sid".into(),
            window_title: None,
            status_label: None,
            tab_strip: None,
            top_tab_bar: false,
            dashboard_panel: None,
            picker: None,
            command_palette: None,
            font_size_px: None,
            theme: None,
            react_chrome: None,
        };
        assert!(plain.dashboard_panel.is_none());
    }

