    #[test]
    fn launch_font_size_line_height_policy_unchanged() {
        use super::DEFAULT_FONT_SIZE_PX;
        // The launch font size feeds the same `(font_size * 1.25).round()` line-height policy the
        // renderer applies in `Renderer::new`, for both the default and an explicit override.
        let line_height = |px: u32| (px as f32 * 1.25).round();
        assert_eq!(line_height(DEFAULT_FONT_SIZE_PX), 20.0);
        assert_eq!(line_height(18), 23.0);
    }

    fn cli(args: &[&str]) -> Result<super::RendererCli, String> {
        let owned: Vec<String> = args.iter().map(|s| (*s).to_string()).collect();
        super::parse_renderer_cli(&owned)
    }

