    #[test]
    fn grid_origin_moves_below_dashboard_panel_rows() {
        use super::pixel_to_cell_with_top_offset;
        // Physical cell 10x20. Top chrome = 1 tab row (20px) + 3 panel rows (60px) = 80px offset.
        let (cw, ch) = (10.0_f32, 20.0_f32);
        let top_offset = ch + ch * 3.0; // tab + 3 panel rows = 80.0
                                        // A pixel anywhere in the reserved 80px top band is chrome, not a grid cell.
        assert_eq!(
            pixel_to_cell_with_top_offset(5.0, 10.0, 0.0, top_offset, cw, ch, 40, 24),
            None,
            "pixel in the tab row is chrome"
        );
        assert_eq!(
            pixel_to_cell_with_top_offset(5.0, 70.0, 0.0, top_offset, cw, ch, 40, 24),
            None,
            "pixel in a panel row is chrome"
        );
        // The first pixel below all top chrome maps to grid row 0, col 0.
        let pos = pixel_to_cell_with_top_offset(5.0, 80.0, 0.0, top_offset, cw, ch, 40, 24)
            .expect("pixel just below the panel maps to the grid");
        assert_eq!((pos.row, pos.col), (0, 0));
        // One row further down is grid row 1 (panel rows do not consume grid rows).
        let pos2 = pixel_to_cell_with_top_offset(5.0, 100.0, 0.0, top_offset, cw, ch, 40, 24)
            .expect("maps to second grid row");
        assert_eq!(pos2.row, 1);
    }

