    #[test]
    fn scoped_react_draw_and_hit_origins_map_the_first_visible_row() {
        use super::{
            grid_origin_offset_px, native_top_bar_enabled, pixel_to_cell_with_top_offset,
            surface_owned_react_inset_px,
        };
        use crate::host_services::TerminalSurfaceScope;

        let (cw, ch) = (10.0_f32, 20.0_f32);
        for (scope, expected_origin) in [
            (TerminalSurfaceScope::TerminalSlot, 0.0),
            (TerminalSurfaceScope::FullWindowWithChrome, 46.0),
        ] {
            let react_top = surface_owned_react_inset_px(scope, 46, 1.0, Some(600));
            let native_top = native_top_bar_enabled(true, true);
            let origin = react_top + grid_origin_offset_px(native_top, 0, ch);
            assert_eq!(origin, expected_origin);

            let first =
                pixel_to_cell_with_top_offset(5.0, origin + 10.0, 0.0, origin, cw, ch, 80, 24)
                    .expect("a point centered in the first painted row must hit row zero");
            assert_eq!((first.row, first.col), (0, 0));

            let second =
                pixel_to_cell_with_top_offset(5.0, origin + ch + 10.0, 0.0, origin, cw, ch, 80, 24)
                    .expect("a point centered in the second painted row must hit row one");
            assert_eq!(second.row, 1);

            if origin > 0.0 {
                assert_eq!(
                    pixel_to_cell_with_top_offset(5.0, origin - 0.5, 0.0, origin, cw, ch, 80, 24,),
                    None,
                    "a point above the painted grid remains chrome"
                );
            }
        }
    }

    #[test]
    fn scoped_react_insets_and_terminal_padding_drive_product_pty_dimensions_once() {
        use super::{
            compute_dims_with_chrome_rows, surface_owned_react_inset_px,
            terminal_surface_left_padding_px,
        };
        use crate::host_services::TerminalSurfaceScope;

        let dims_for = |scope| {
            let dock = surface_owned_react_inset_px(scope, 460, 1.0, Some(800));
            let left = dock + terminal_surface_left_padding_px(1.0, Some(800), dock, 10.0);
            let top = surface_owned_react_inset_px(scope, 46, 1.0, Some(600));
            // Product policy hides the retired bottom overlay, so no invisible row is reserved.
            compute_dims_with_chrome_rows(800.0 - left, 600.0 - top, 10.0, 20.0, 0)
        };
        assert_eq!(
            dims_for(TerminalSurfaceScope::TerminalSlot),
            (79, 30),
            "the host-owned slot reserves only its 4px terminal padding"
        );
        assert_eq!(
            dims_for(TerminalSurfaceScope::FullWindowWithChrome),
            (33, 27),
            "a full-window surface reserves React chrome once plus terminal-only padding"
        );
    }

