    #[test]
    fn grid_origin_offset_panel_only_is_below_panel_rows() {
        use super::grid_origin_offset_px;
        // Dashboard panel only (no tab bar): the grid origin is exactly the panel rows' height. This
        // is the regression that `set_top_bar` must honor even though `top_bar` is `None`.
        assert_eq!(grid_origin_offset_px(false, 3, 20.0), 60.0);
        assert_eq!(grid_origin_offset_px(false, 1, 20.0), 20.0);
    }

