    fn grid_origin_offset_tab_only_is_below_tab_row() {
        use super::grid_origin_offset_px;
        // Top tab bar only (no panel): the grid origin is exactly one tab row tall.
        assert_eq!(grid_origin_offset_px(true, 0, 20.0), 20.0);
    }

    #[test]
    fn grid_origin_offset_tab_plus_panel_is_below_both() {
        use super::grid_origin_offset_px;
        // Tab bar + dashboard panel: the grid origin is below the tab row AND all panel rows, and is
        // strictly greater than either chrome band alone.
        let tab_only = grid_origin_offset_px(true, 0, 20.0);
        let panel_only = grid_origin_offset_px(false, 3, 20.0);
        let both = grid_origin_offset_px(true, 3, 20.0);
        assert_eq!(both, 80.0); // (1 tab + 3 panel) * 20px
        assert!(both > tab_only && both > panel_only);
        assert_eq!(both, tab_only + panel_only);
    }

