    #[test]
    fn top_bar_hit_emits_exactly_one_activation() {
        use super::{
            decide_top_tab_click, emit_tab_strip_activation, RendererEvent, TopTabClickOutcome,
        };
        use std::sync::mpsc::channel;

        let s = strip(vec![
            tab("a", "one", true, false, false),
            tab("b", "two", false, false, false),
        ]);
        let width = 800.0;
        let layout = layout_tab_bar(Some(&s), width, CELL_W, CELL_H).unwrap();
        let (cx, cy) = center(&layout, 1);
        let tab_id = hit_test_tab_bar_pixel(Some(&layout), cx, cy, width, CELL_H);
        assert_eq!(tab_id, Some("b"));

        let (tx, rx) = channel::<RendererEvent>();
        match decide_top_tab_click(true, tab_id) {
            TopTabClickOutcome::Activate(id) => {
                assert!(emit_tab_strip_activation(Some(&tx), &id));
            }
            other => panic!("expected Activate, got {other:?}"),
        }

        match rx.try_recv() {
            Ok(RendererEvent::TabStripActivated { tab_id }) => assert_eq!(tab_id, "b"),
            other => panic!("expected one TabStripActivated, got {other:?}"),
        }
        assert!(rx.try_recv().is_err(), "exactly one event must be emitted");
    }

    #[test]
    fn top_bar_gap_click_emits_no_event() {
        use super::{decide_top_tab_click, RendererEvent};
        use std::sync::mpsc::channel;

        let s = strip(vec![tab("a", "one", true, false, false)]);
        let width = 800.0;
        let layout = layout_tab_bar(Some(&s), width, CELL_W, CELL_H).unwrap();
        let gap_x = layout.items[0].x1 + 4.0;
        let tab_id = hit_test_tab_bar_pixel(Some(&layout), gap_x, 8.0, width, CELL_H);
        assert_eq!(tab_id, None, "the gap resolves to no tab");

        let (tx, rx) = channel::<RendererEvent>();
        // ConsumeNoop must not emit; we simply never call emit on that arm.
        assert!(matches!(
            decide_top_tab_click(true, tab_id),
            super::TopTabClickOutcome::ConsumeNoop
        ));
        let _ = &tx; // sender exists but is never used on the noop arm
        assert!(rx.try_recv().is_err(), "gap click must emit no event");
    }

    #[test]
    fn top_bar_activation_with_no_sender_does_not_panic() {
        use super::{decide_top_tab_click, emit_tab_strip_activation, TopTabClickOutcome};

        let s = strip(vec![tab("a", "one", true, false, false)]);
        let width = 800.0;
        let layout = layout_tab_bar(Some(&s), width, CELL_W, CELL_H).unwrap();
        let (cx, cy) = center(&layout, 0);
        let tab_id = hit_test_tab_bar_pixel(Some(&layout), cx, cy, width, CELL_H);

        match decide_top_tab_click(true, tab_id) {
            TopTabClickOutcome::Activate(id) => {
                // No outbound sender: emit is a no-op and must not panic.
                assert!(!emit_tab_strip_activation(None, &id));
            }
            other => panic!("expected Activate, got {other:?}"),
        }
    }

    // The physical x at the horizontal center of a tab's drawn close cell, or `None` if the tab is too
    // narrow to host one. Derived from the SAME helper the renderer draws with, so a test click here
    // lands exactly where the `x` was painted.
    fn close_center_x(layout: &RendererTabBarLayout, idx: usize, width: f32) -> Option<f32> {
        let it = &layout.items[idx];
        super::render::tab_close_rect_for_item(it.x0, it.x1, width, CELL_W, CELL_H)
            .map(|[cx0, _, cw, _]| cx0 + cw / 2.0)
    }

    #[test]
    fn close_emit_helper_sends_exactly_one_close_event() {
        use super::{emit_tab_close_requested, RendererEvent};
        use std::sync::mpsc::channel;

        let (tx, rx) = channel::<RendererEvent>();
        assert!(emit_tab_close_requested(Some(&tx), "b"));
        match rx.try_recv() {
            Ok(RendererEvent::TabCloseRequested { tab_id }) => assert_eq!(tab_id, "b"),
            other => panic!("expected one TabCloseRequested, got {other:?}"),
        }
        assert!(rx.try_recv().is_err(), "exactly one close event");
    }

    #[test]
    fn close_emit_helper_no_sender_or_dropped_receiver_does_not_panic() {
        use super::{emit_tab_close_requested, RendererEvent};
        use std::sync::mpsc::channel;

        // No sender: false, no panic.
        assert!(!emit_tab_close_requested(None, "a"));
        // Dropped receiver: send fails -> false, no panic.
        let (tx, rx) = channel::<RendererEvent>();
        drop(rx);
        assert!(!emit_tab_close_requested(Some(&tx), "a"));
    }

    #[test]
    fn new_tab_event_is_payload_free_and_distinct_from_tab_events() {
        use super::RendererEvent;
        // NewTabRequested carries no payload and is its own value, never equal to an activation or a
        // close — even for a tab whose id is empty/anything.
        let n = RendererEvent::NewTabRequested;
        assert_eq!(n, RendererEvent::NewTabRequested);
        assert_ne!(
            n,
            RendererEvent::TabStripActivated {
                tab_id: String::new()
            }
        );
        assert_ne!(
            n,
            RendererEvent::TabCloseRequested {
                tab_id: String::new()
            }
        );
    }

    #[test]
    fn new_tab_emit_helper_sends_exactly_one_payload_free_event() {
        use super::{emit_new_tab_requested, RendererEvent};
        use std::sync::mpsc::channel;

        let (tx, rx) = channel::<RendererEvent>();
        assert!(emit_new_tab_requested(Some(&tx)));
        match rx.try_recv() {
            Ok(RendererEvent::NewTabRequested) => {}
            other => panic!("expected one NewTabRequested, got {other:?}"),
        }
        assert!(rx.try_recv().is_err(), "exactly one new-tab event");
    }

    #[test]
    fn new_tab_emit_helper_no_sender_or_dropped_receiver_does_not_panic() {
        use super::{emit_new_tab_requested, RendererEvent};
        use std::sync::mpsc::channel;

        // No sender: false, no panic.
        assert!(!emit_new_tab_requested(None));
        // Dropped receiver: send fails -> false, no panic.
        let (tx, rx) = channel::<RendererEvent>();
        drop(rx);
        assert!(!emit_new_tab_requested(Some(&tx)));
    }

    #[test]
    fn new_tab_hit_test_shares_draw_helper_and_is_true_only_inside_the_control() {
        // The click-side `pixel_in_new_tab_control` resolves the SAME rect the draw passes use
        // (`render::new_tab_rect`), so a press lands on the `+` exactly where a `+` was drawn.
        use super::pixel_in_new_tab_control;

        let s = strip(vec![tab("a", "alpha-tab", true, false, false)]);
        let width = 800.0;
        let layout = layout_tab_bar(Some(&s), width, CELL_W, CELL_H).unwrap();
        // No overflow at this width: the control is the rightmost cell.
        assert!(!layout.overflow);
        let [rx, _, rw, _] =
            super::render::new_tab_rect(layout.overflow, width, CELL_W, CELL_H).unwrap();
        let inside_x = rx + rw / 2.0;

        // A pixel inside the control's cell, within the one-cell band, hits.
        assert!(pixel_in_new_tab_control(
            Some(&layout),
            inside_x,
            CELL_H / 2.0,
            width,
            CELL_W,
            CELL_H
        ));
        // Just left of the control is NOT the control.
        assert!(!pixel_in_new_tab_control(
            Some(&layout),
            rx - 1.0,
            CELL_H / 2.0,
            width,
            CELL_W,
            CELL_H
        ));
        // Below the one-cell band is not the control even at the right x.
        assert!(!pixel_in_new_tab_control(
            Some(&layout),
            inside_x,
            CELL_H,
            width,
            CELL_W,
            CELL_H
        ));
        // No layout -> false.
        assert!(!pixel_in_new_tab_control(
            None,
            inside_x,
            CELL_H / 2.0,
            width,
            CELL_W,
            CELL_H
        ));
    }

    #[test]
    fn new_tab_control_does_not_collide_with_overflow_marker() {
        // When the strip overflows, the overflow marker owns the rightmost cell and the new-tab
        // control sits in the cell to its left: the two hit-tests are mutually exclusive.
        use super::{pixel_in_new_tab_control, pixel_in_overflow_marker};

        let s = strip(vec![
            tab("a", "tab00", false, false, false),
            tab("b", "tab01", false, false, false),
            tab("c", "tab02", true, false, false),
            tab("d", "tab03", false, false, false),
        ]);
        let narrow = 120.0;
        let layout = layout_tab_bar(Some(&s), narrow, CELL_W, CELL_H).unwrap();
        assert!(layout.overflow, "fixture must overflow");

        let marker_x = narrow - 1.0;
        assert!(pixel_in_overflow_marker(
            Some(&layout),
            marker_x,
            narrow,
            CELL_W
        ));
        // The overflow marker column is NOT the new-tab control.
        assert!(!pixel_in_new_tab_control(
            Some(&layout),
            marker_x,
            CELL_H / 2.0,
            narrow,
            CELL_W,
            CELL_H
        ));
        // The new-tab control column (one cell left of the marker) IS the control and is NOT the
        // overflow marker.
        let [nx, _, nw, _] =
            super::render::new_tab_rect(layout.overflow, narrow, CELL_W, CELL_H).unwrap();
        let new_tab_x = nx + nw / 2.0;
        assert!(pixel_in_new_tab_control(
            Some(&layout),
            new_tab_x,
            CELL_H / 2.0,
            narrow,
            CELL_W,
            CELL_H
        ));
        assert!(!pixel_in_overflow_marker(
            Some(&layout),
            new_tab_x,
            narrow,
            CELL_W
        ));
    }

    #[test]
    fn split_control_hit_test_resolves_right_and_down_and_is_disjoint_from_new_tab() {
        // The click-side `pixel_in_split_control` resolves the SAME rects the draw passes use
        // (`render::split_button_rects`), so a press lands on `>`/`v` exactly where they were drawn.
        // The two split cells sit left of `+`: hitting them yields the right/down axis, and the
        // new-tab control column is NOT a split control.
        use super::{pixel_in_new_tab_control, pixel_in_split_control, RendererTabSplitAxis};

        let s = strip(vec![tab("a", "alpha-tab", true, false, false)]);
        let width = 800.0;
        let layout = layout_tab_bar(Some(&s), width, CELL_W, CELL_H).unwrap();
        assert!(!layout.overflow);

        let (right, down) =
            super::render::split_button_rects(layout.overflow, width, CELL_W, CELL_H).unwrap();
        let [rx, _, rw, _] = right;
        let [dx, _, dw, _] = down;
        let right_x = rx + rw / 2.0;
        let down_x = dx + dw / 2.0;

        assert_eq!(
            pixel_in_split_control(Some(&layout), right_x, CELL_H / 2.0, width, CELL_W, CELL_H),
            Some(RendererTabSplitAxis::Right)
        );
        assert_eq!(
            pixel_in_split_control(Some(&layout), down_x, CELL_H / 2.0, width, CELL_W, CELL_H),
            Some(RendererTabSplitAxis::Down)
        );
        // Below the one-cell band is not a control even at the right x.
        assert_eq!(
            pixel_in_split_control(Some(&layout), right_x, CELL_H, width, CELL_W, CELL_H),
            None
        );
        // The new-tab `+` column is NOT a split control, and the split columns are NOT the `+`.
        let [nx, _, nw, _] =
            super::render::new_tab_rect(layout.overflow, width, CELL_W, CELL_H).unwrap();
        let newtab_x = nx + nw / 2.0;
        assert_eq!(
            pixel_in_split_control(Some(&layout), newtab_x, CELL_H / 2.0, width, CELL_W, CELL_H),
            None
        );
        assert!(!pixel_in_new_tab_control(
            Some(&layout),
            right_x,
            CELL_H / 2.0,
            width,
            CELL_W,
            CELL_H
        ));
        // No layout -> None.
        assert_eq!(
            pixel_in_split_control(None, right_x, CELL_H / 2.0, width, CELL_W, CELL_H),
            None
        );
    }

    #[test]
    fn swap_control_hit_test_resolves_and_is_disjoint_from_split_and_new_tab() {
        // The click-side `pixel_in_swap_control` resolves the SAME rect the draw passes use
        // (`render::swap_button_rect`), so a press lands on `⇄` exactly where it was drawn. The swap
        // cell sits left of `>`: hitting it is a swap, while the split/new-tab columns are NOT.
        use super::{pixel_in_split_control, pixel_in_swap_control};

        let s = strip(vec![tab("a", "alpha-tab", true, false, false)]);
        let width = 800.0;
        let layout = layout_tab_bar(Some(&s), width, CELL_W, CELL_H).unwrap();
        assert!(!layout.overflow);

        let [sx, _, sw, _] =
            super::render::swap_button_rect(layout.overflow, width, CELL_W, CELL_H).unwrap();
        let swap_x = sx + sw / 2.0;

        assert!(pixel_in_swap_control(
            Some(&layout),
            swap_x,
            CELL_H / 2.0,
            width,
            CELL_W,
            CELL_H
        ));
        // Below the one-cell band is not a control even at the right x.
        assert!(!pixel_in_swap_control(
            Some(&layout),
            swap_x,
            CELL_H,
            width,
            CELL_W,
            CELL_H
        ));
        // The swap column is NOT a split control, and the split columns are NOT swap.
        assert_eq!(
            pixel_in_split_control(Some(&layout), swap_x, CELL_H / 2.0, width, CELL_W, CELL_H),
            None
        );
        let (right, _down) =
            super::render::split_button_rects(layout.overflow, width, CELL_W, CELL_H).unwrap();
        let [rx, _, rw, _] = right;
        let right_x = rx + rw / 2.0;
        assert!(!pixel_in_swap_control(
            Some(&layout),
            right_x,
            CELL_H / 2.0,
            width,
            CELL_W,
            CELL_H
        ));
        // No layout -> false.
        assert!(!pixel_in_swap_control(
            None,
            swap_x,
            CELL_H / 2.0,
            width,
            CELL_W,
            CELL_H
        ));
    }

