    /// Pull the session id out of an AttachSession event.
    /// `UserEvent` intentionally derives only `Debug`/`Clone`, so we compare by id, not `==`.
    fn attach_id(event: UserEvent) -> String {
        match event {
            UserEvent::AttachSession { session_id } => session_id,
            other => panic!("expected AttachSession, got {other:?}"),
        }
    }

    fn one_tab_strip() -> RendererTabStrip {
        RendererTabStrip {
            window_id: "win-1".into(),
            tabs: vec![RendererTab {
                tab_id: "t0".into(),
                session_id: "s0".into(),
                title: "shell".into(),
                active: true,
                pinned: false,
                needs_attention: false,
                attention: None,
                split: None,
                split_from_tab_id: None,
                split_ratio_per_mille: None,
                pane_rect: None,
            }],
        }
    }

