    #[test]
    fn bridge_forwards_every_command_in_order_then_exits_on_channel_close() {
        let (tx, rx) = mpsc::channel();
        tx.send(RendererCommand::AttachSession {
            session_id: "a".into(),
        })
        .unwrap();
        tx.send(RendererCommand::AttachSession {
            session_id: "b".into(),
        })
        .unwrap();
        // Drop the sender so the bridge sees the channel close and returns.
        drop(tx);

        let mut forwarded = Vec::new();
        bridge_commands(rx, |event| {
            forwarded.push(attach_id(event));
            Ok(())
        });

        assert_eq!(forwarded, vec!["a".to_string(), "b".to_string()]);
    }

    #[test]
    fn bridge_stops_after_send_failure_even_with_commands_remaining() {
        let (tx, rx) = mpsc::channel();
        for id in ["a", "b", "c"] {
            tx.send(RendererCommand::AttachSession {
                session_id: id.into(),
            })
            .unwrap();
        }
        // Keep the sender alive: the channel is NOT closed, so the bridge can only stop
        // because the sink (a dead event loop) reports failure on the first send.
        let mut forwarded = Vec::new();
        bridge_commands(rx, |event| {
            forwarded.push(attach_id(event));
            Err(())
        });

        assert_eq!(
            forwarded,
            vec!["a".to_string()],
            "a failing sink must stop the bridge after exactly one delivery attempt"
        );
        drop(tx);
    }

    #[test]
    fn bridge_returns_immediately_on_an_already_closed_empty_channel() {
        let (tx, rx) = mpsc::channel::<RendererCommand>();
        drop(tx);
        let mut count = 0usize;
        bridge_commands(rx, |_event| {
            count += 1;
            Ok(())
        });
        assert_eq!(count, 0, "no commands means no forwards");
    }

