    #[test]
    fn bridge_forwards_mixed_attach_and_set_tab_strip_commands_in_order() {
        let (tx, rx) = mpsc::channel();
        let strip = one_tab_strip();
        tx.send(RendererCommand::AttachSession {
            session_id: "a".into(),
        })
        .unwrap();
        tx.send(RendererCommand::SetTabStrip {
            tab_strip: Some(strip.clone()),
        })
        .unwrap();
        tx.send(RendererCommand::SetTabStrip { tab_strip: None })
            .unwrap();
        drop(tx);

        // Record each event as a label so order across variants is asserted in one Vec.
        let mut forwarded = Vec::new();
        bridge_commands(rx, |event| {
            match event {
                UserEvent::AttachSession { session_id } => {
                    forwarded.push(format!("attach:{session_id}"))
                }
                UserEvent::SetTabStrip { tab_strip } => match tab_strip {
                    Some(s) => forwarded.push(format!("set:{}", s.window_id)),
                    None => forwarded.push("clear".to_string()),
                },
                UserEvent::Redraw => forwarded.push("redraw".to_string()),
                UserEvent::SessionExited { session_id, .. } => {
                    forwarded.push(format!("session-exited:{session_id}"))
                }
                UserEvent::TerminalBell => forwarded.push("terminal-bell".to_string()),
                UserEvent::TerminalTitle { title } => {
                    forwarded.push(format!("terminal-title:{title:?}"))
                }
                UserEvent::TerminalClipboardStore { .. } => {
                    forwarded.push("terminal-clipboard".to_string())
                }
                UserEvent::SetPickerOverlay { picker } => match picker {
                    Some(_) => forwarded.push("picker:set".to_string()),
                    None => forwarded.push("picker:clear".to_string()),
                },
                UserEvent::SetStatusLabel { status_label } => match status_label {
                    Some(s) => forwarded.push(format!("status:{s}")),
                    None => forwarded.push("status:clear".to_string()),
                },
                UserEvent::SetTheme { theme } => forwarded.push(format!("theme:{theme:?}")),
                UserEvent::SetCommandPaletteResult { result } => match result {
                    Some(r) => forwarded.push(format!("cp-result:{}", r.text)),
                    None => forwarded.push("cp-result:clear".to_string()),
                },
                UserEvent::DismissCommandPalette => forwarded.push("cp-dismiss".to_string()),
                UserEvent::SetCommandPaletteOverlay { command_palette } => match command_palette {
                    Some(_) => forwarded.push("cp-overlay:set".to_string()),
                    None => forwarded.push("cp-overlay:clear".to_string()),
                },
                UserEvent::SetDashboardPanel { dashboard_panel } => match dashboard_panel {
                    Some(_) => forwarded.push("dash-panel:set".to_string()),
                    None => forwarded.push("dash-panel:clear".to_string()),
                },
                UserEvent::SetRemoteOpen { open } => forwarded.push(format!("remote-open:{open}")),
                UserEvent::SetWinsizeOwner { remote } => {
                    forwarded.push(format!("winsize-owner:{remote}"))
                }
                UserEvent::SetRemoteExtensionState {
                    available,
                    open,
                    remote_winsize,
                    remote_owned_sessions,
                } => forwarded.push(format!(
                    "remote-extension:{available}:{open}:{remote_winsize}:{}",
                    remote_owned_sessions.len()
                )),
                UserEvent::SetDock { dock } => match dock {
                    Some(_) => forwarded.push("dock:set".to_string()),
                    None => forwarded.push("dock:clear".to_string()),
                },
                UserEvent::SetFilePreview { file_preview } => match file_preview {
                    Some(_) => forwarded.push("file-preview:set".to_string()),
                    None => forwarded.push("file-preview:clear".to_string()),
                },
                UserEvent::SetSettingsPanelEditDraft { draft } => match draft {
                    Some(_) => forwarded.push("edit-draft:set".to_string()),
                    None => forwarded.push("edit-draft:clear".to_string()),
                },
                UserEvent::SetFilePathInput { file_path_input } => match file_path_input {
                    Some(_) => forwarded.push("file-path-input:set".to_string()),
                    None => forwarded.push("file-path-input:clear".to_string()),
                },
                UserEvent::SetFontSize { px } => forwarded.push(format!("font-size:{px}")),
                UserEvent::SetReactChromeModel { model_json } => {
                    forwarded.push(format!("react-model:{model_json}"))
                }
                UserEvent::SetReactChromeWidth { width_logical_px } => {
                    forwarded.push(format!("react-width:{width_logical_px}"))
                }
                UserEvent::FocusTerminal => forwarded.push("focus-terminal".to_string()),
                UserEvent::SetReactChromeOverlayVisible { visible } => {
                    forwarded.push(format!("react-overlay:{visible}"))
                }
                UserEvent::EvaluateReactChromeScript { .. } => {
                    forwarded.push("react-eval".to_string())
                }
                UserEvent::PickReactChromeFolder { request_id } => {
                    forwarded.push(format!("react-pick:{request_id}"))
                }
                UserEvent::SetStashedPaneDrag { drag } => match drag {
                    Some(drag) => forwarded.push(format!("stashed-drag:{}", drag.tab_id)),
                    None => forwarded.push("stashed-drag:clear".to_string()),
                },
                UserEvent::MoveStashedPaneDragTo { x, y } => {
                    forwarded.push(format!("stashed-drag-move:{x},{y}"))
                }
                UserEvent::CompleteStashedPaneDropAt { x, y } => {
                    forwarded.push(format!("stashed-drag-drop:{x},{y}"))
                }
                UserEvent::ReactChromePageLoaded { url } => {
                    forwarded.push(format!("react-loaded:{url}"))
                }
            }
            Ok(())
        });

        assert_eq!(
            forwarded,
            vec![
                "attach:a".to_string(),
                format!("set:{}", strip.window_id),
                "clear".to_string(),
            ]
        );
    }

