    #[test]
    fn apply_set_tab_strip_some_yields_the_structured_line_with_same_text_and_targets() {
        let strip = one_tab_strip();
        let line = apply_set_tab_strip(Some(&strip)).expect("structured line");
        // Visible text is byte-identical to the launch-time composition.
        assert_eq!(
            Some(line.text.clone()),
            compose_tab_strip_text(Some(&strip)),
            "runtime update must compose the SAME text the launch-time strip uses"
        );
        assert_eq!(line.text, "win-1 [*shell]");
        // The hit targets are RETAINED (not discarded), so the future click path can use them.
        assert_eq!(line.targets.len(), 1);
        assert_eq!(line.targets[0].tab_id, "t0");
        // The stored-line hit-test wrapper maps a column inside the segment back to the tab id,
        // and returns None outside it (window id) and when there is no strip.
        assert_eq!(
            hit_test_tab_strip_line(Some(&line), line.targets[0].start_col),
            Some("t0")
        );
        assert_eq!(hit_test_tab_strip_line(Some(&line), 0), None);
        assert_eq!(
            hit_test_tab_strip_line(None, line.targets[0].start_col),
            None
        );
    }

