    #[test]
    fn renderer_event_tab_strip_activated_carries_exact_tab_id_and_derives_eq() {
        let a = RendererEvent::TabStripActivated {
            tab_id: "t1".into(),
        };
        let b = RendererEvent::TabStripActivated {
            tab_id: "t1".into(),
        };
        let c = RendererEvent::TabStripActivated {
            tab_id: "t2".into(),
        };
        assert_eq!(a, b);
        assert_ne!(a, c);

        // The additive close-intent variant is a distinct value (not equal to an activation with the
        // same id) and carries its own `tab_id`.
        let close = RendererEvent::TabCloseRequested {
            tab_id: "t1".into(),
        };
        assert_ne!(close, a);

        match &a {
            RendererEvent::TabStripActivated { tab_id } => assert_eq!(tab_id, "t1"),
            RendererEvent::TabCloseRequested { tab_id } => {
                panic!("unexpected close variant for {tab_id:?}")
            }
            RendererEvent::NewTabRequested => panic!("unexpected new-tab variant"),
            RendererEvent::TabAttentionClearRequested { tab_id } => {
                panic!("unexpected attention-clear variant for {tab_id:?}")
            }
            RendererEvent::SessionExited { .. }
            | RendererEvent::PickerRowActivated { .. }
            | RendererEvent::PickerConsentGrantRequested { .. }
            | RendererEvent::PickerConsentGrantConfirmed { .. }
            | RendererEvent::PickerDismissed
            | RendererEvent::CommandPaletteActionActivated { .. }
            | RendererEvent::CommandPaletteOpenRequested
            | RendererEvent::SettingsPanelOpenRequested
            | RendererEvent::SettingsPanelCloseRequested
            | RendererEvent::SettingsPanelRowSelected { .. }
            | RendererEvent::SettingsPanelRowActivated { .. }
            | RendererEvent::DashboardRowActivated { .. }
            | RendererEvent::DashboardRowReviveRequested { .. }
            | RendererEvent::DashboardProjectSelected { .. }
            | RendererEvent::DockProjectExpandToggled { .. }
            | RendererEvent::DockCollapseToggled
            | RendererEvent::SettingsPanelEditDraftSubmitted { .. }
            | RendererEvent::FilePreviewPathSubmitted { .. }
            | RendererEvent::SplitRequested { .. }
            | RendererEvent::SwapRequested { .. }
            | RendererEvent::PaneSwapRequested { .. }
            | RendererEvent::PaneEdgeDockRequested { .. }
            | RendererEvent::StashedPaneDropRequested { .. }
            | RendererEvent::PaneCloseRequested { .. }
            | RendererEvent::PaneFocused { .. }
            | RendererEvent::SwallowRequested { .. }
            | RendererEvent::PaneSwallowRequested { .. }
            | RendererEvent::CloseFocusedPaneRequested { .. }
            | RendererEvent::ReactChromeIntent { .. }
            | RendererEvent::DividerRatioPersisted { .. }
            | RendererEvent::RemoteAccessToggleRequested { .. }
            | RendererEvent::WinsizeOwnerToggleRequested { .. }
            | RendererEvent::ViewportReclaimRequested { .. }
            | RendererEvent::PaneRectsResized { .. } => {
                panic!("unexpected picker variant")
            }
        }
        match &close {
            RendererEvent::TabCloseRequested { tab_id } => assert_eq!(tab_id, "t1"),
            RendererEvent::TabStripActivated { tab_id } => {
                panic!("unexpected activation variant for {tab_id:?}")
            }
            RendererEvent::NewTabRequested => panic!("unexpected new-tab variant"),
            RendererEvent::TabAttentionClearRequested { tab_id } => {
                panic!("unexpected attention-clear variant for {tab_id:?}")
            }
            RendererEvent::SessionExited { .. }
            | RendererEvent::PickerRowActivated { .. }
            | RendererEvent::PickerConsentGrantRequested { .. }
            | RendererEvent::PickerConsentGrantConfirmed { .. }
            | RendererEvent::PickerDismissed
            | RendererEvent::CommandPaletteActionActivated { .. }
            | RendererEvent::CommandPaletteOpenRequested
            | RendererEvent::SettingsPanelOpenRequested
            | RendererEvent::SettingsPanelCloseRequested
            | RendererEvent::SettingsPanelRowSelected { .. }
            | RendererEvent::SettingsPanelRowActivated { .. }
            | RendererEvent::DashboardRowActivated { .. }
            | RendererEvent::DashboardRowReviveRequested { .. }
            | RendererEvent::DashboardProjectSelected { .. }
            | RendererEvent::DockProjectExpandToggled { .. }
            | RendererEvent::DockCollapseToggled
            | RendererEvent::SettingsPanelEditDraftSubmitted { .. }
            | RendererEvent::FilePreviewPathSubmitted { .. }
            | RendererEvent::SplitRequested { .. }
            | RendererEvent::SwapRequested { .. }
            | RendererEvent::PaneSwapRequested { .. }
            | RendererEvent::PaneEdgeDockRequested { .. }
            | RendererEvent::StashedPaneDropRequested { .. }
            | RendererEvent::PaneCloseRequested { .. }
            | RendererEvent::PaneFocused { .. }
            | RendererEvent::SwallowRequested { .. }
            | RendererEvent::PaneSwallowRequested { .. }
            | RendererEvent::CloseFocusedPaneRequested { .. }
            | RendererEvent::ReactChromeIntent { .. }
            | RendererEvent::DividerRatioPersisted { .. }
            | RendererEvent::RemoteAccessToggleRequested { .. }
            | RendererEvent::WinsizeOwnerToggleRequested { .. }
            | RendererEvent::ViewportReclaimRequested { .. }
            | RendererEvent::PaneRectsResized { .. } => {
                panic!("unexpected picker variant")
            }
        }
        // The additive attention-clear variant is distinct from activation/close/new-tab and
        // carries its own `tab_id`.
        let clear = RendererEvent::TabAttentionClearRequested {
            tab_id: "t1".into(),
        };
        assert_ne!(clear, a);
        assert_ne!(clear, close);
        assert_eq!(
            clear,
            RendererEvent::TabAttentionClearRequested {
                tab_id: "t1".into()
            }
        );
        assert_ne!(
            clear,
            RendererEvent::TabAttentionClearRequested {
                tab_id: "t2".into()
            }
        );
    }

    #[test]
    fn run_renderer_with_commands_and_events_is_referenceable_without_a_gui() {
        // Bind the new entrypoint as a typed fn pointer so signature drift breaks the build,
        // and round-trip the channel types through it — all without constructing a window.
        let _f: fn(
            RendererLaunch,
            mpsc::Receiver<RendererCommand>,
            mpsc::Sender<RendererEvent>,
        ) -> Result<(), RendererRunError> = run_renderer_with_commands_and_events;
    }

