    #[test]
    fn compose_empty_model_is_single_disabled_empty_state_row() {
        let rows = compose_picker_rows(&RendererPickerModel {
            projects: vec![],
            confirm: None,
            hint: None,
        });
        assert_eq!(rows.len(), 1);
        assert_eq!(rows[0].text, "(no projects)");
        assert_eq!(rows[0].target, PickerRowTarget::Disabled);
    }

    #[test]
    fn compose_keeps_model_order_and_targets_rows() {
        let model = RendererPickerModel {
            projects: vec![project("p1", vec![ws("w1", true, "granted")])],
            confirm: None,
            hint: None,
        };
        let rows = compose_picker_rows(&model);
        // project header first, then its workspace.
        assert_eq!(rows.len(), 2);
        assert_eq!(
            rows[0].target,
            PickerRowTarget::Project {
                project_id: "p1".into()
            }
        );
        assert_eq!(
            rows[1].target,
            PickerRowTarget::Workspace {
                project_id: "p1".into(),
                workspace_id: "w1".into(),
            }
        );
    }

    #[test]
    fn compose_disabled_workspace_carries_disabled_target_and_locked_marker() {
        // A non-selectable / missing-consent workspace draws disabled and can never activate.
        let model = RendererPickerModel {
            projects: vec![project("p1", vec![ws("w-missing", false, "missing")])],
            confirm: None,
            hint: None,
        };
        let rows = compose_picker_rows(&model);
        assert_eq!(rows[1].target, PickerRowTarget::Disabled);
        assert!(rows[1].text.contains("[locked]"));
    }

    #[test]
    fn compose_is_bounded_by_max_rows() {
        let workspaces: Vec<_> = (0..200)
            .map(|i| ws(&format!("w{i}"), true, "granted"))
            .collect();
        let model = RendererPickerModel {
            projects: vec![project("p1", workspaces)],
            confirm: None,
            hint: None,
        };
        let rows = compose_picker_rows(&model);
        assert!(rows.len() <= PICKER_OVERLAY_MAX_ROWS);
    }

    fn cp_row(id: &str, label: &str, category: &str, command: &str) -> RendererCommandPaletteRow {
        RendererCommandPaletteRow {
            id: id.to_string(),
            label: label.to_string(),
            category: category.to_string(),
            summary: format!("{label} summary"),
            command: command.to_string(),
        }
    }

    fn cp_model(
        query: Option<&str>,
        rows: Vec<RendererCommandPaletteRow>,
        selected_row: Option<usize>,
    ) -> RendererCommandPaletteModel {
        RendererCommandPaletteModel {
            title: "Command Palette".to_string(),
            query: query.map(str::to_string),
            rows,
            selected_row,
        }
    }

