    #[test]
    fn command_palette_overlay_out_of_range_selection_is_ignored() {
        let model = cp_model(None, vec![cp_row("a.one", "First", "Cat", "one")], Some(9));
        let lines = compose_command_palette_overlay_lines(&model);
        assert!(selected_overlay_line(&lines).is_none());
    }

    #[test]
    fn command_palette_overlay_truncation_preserves_visible_selection() {
        // Action index within the visible cap stays selected.
        let rows: Vec<_> = (0..500)
            .map(|i| cp_row(&format!("a.{i}"), &format!("Label {i}"), "Cat", "cmd"))
            .collect();
        let visible = cp_model(None, rows.clone(), Some(0));
        let lines = compose_command_palette_overlay_lines(&visible);
        let (_, text) = selected_overlay_line(&lines).expect("visible row selected");
        assert!(text.contains("Label 0"));
        assert!(lines.len() <= COMMAND_PALETTE_OVERLAY_MAX_ROWS);

        // An action index beyond the visible cap is truncated away: no selection drawn.
        let truncated = cp_model(None, rows, Some(400));
        let lines = compose_command_palette_overlay_lines(&truncated);
        assert!(selected_overlay_line(&lines).is_none());
        assert!(lines.len() <= COMMAND_PALETTE_OVERLAY_MAX_ROWS);
    }

