    fn command_palette_compose_text_only_helper_is_unaffected_by_selection() {
        // The retained text-only helper ignores selection entirely.
        let model = cp_model(None, vec![cp_row("a.one", "First", "Cat", "one")], Some(0));
        let lines = compose_command_palette_lines(&model);
        assert_eq!(lines[0], "Command Palette");
        assert_eq!(lines[1], "First [Cat] — one");
    }

    #[test]
    fn command_palette_overlay_marks_action_rows_selectable_and_headers_not() {
        // Title + query header are non-selectable; both action rows are selectable.
        let model = cp_model(
            Some("c"),
            vec![
                cp_row("a.one", "First", "Cat", "one"),
                cp_row("a.two", "Second", "Cat", "two"),
            ],
            Some(0),
        );
        let lines = compose_command_palette_overlay_lines(&model);
        // Title (0) and query (1) are headers; action rows are 2 and 3.
        assert!(!lines[0].selectable, "title is not selectable");
        assert!(!lines[1].selectable, "query header is not selectable");
        assert!(lines[2].selectable, "first action row is selectable");
        assert!(lines[3].selectable, "second action row is selectable");
        let selectable_count = lines.iter().filter(|l| l.selectable).count();
        assert_eq!(
            selectable_count, 2,
            "exactly the two action rows are selectable"
        );
    }

