    #[test]
    fn set_command_palette_result_command_bridges_to_matching_user_event() {
        let result = cp_result("ran settings.show (read-only)");
        let event = user_event_for_command(RendererCommand::SetCommandPaletteResult {
            result: Some(result.clone()),
        });
        match event {
            UserEvent::SetCommandPaletteResult { result: got } => assert_eq!(got, Some(result)),
            other => panic!("expected SetCommandPaletteResult, got {other:?}"),
        }
        let cleared =
            user_event_for_command(RendererCommand::SetCommandPaletteResult { result: None });
        match cleared {
            UserEvent::SetCommandPaletteResult { result } => assert!(result.is_none()),
            other => panic!("expected SetCommandPaletteResult(None), got {other:?}"),
        }
    }

    #[test]
    fn dismiss_command_palette_command_bridges_to_matching_user_event() {
        // The app sends `DismissCommandPalette` only AFTER the result command on a successful read-only
        // execution; it must translate to the local `UserEvent::DismissCommandPalette` that runs the
        // Escape-equivalent overlay clear.
        match user_event_for_command(RendererCommand::DismissCommandPalette) {
            UserEvent::DismissCommandPalette => {}
            other => panic!("expected DismissCommandPalette, got {other:?}"),
        }
    }

    #[test]
    fn open_shortcut_matches_ctrl_k_and_super_k_case_insensitively() {
        use super::command_palette_open_shortcut_matches;
        use crate::host_event::HostKey;
        use crate::host_mods;

        let ctrl = host_mods(true, false, false, false);
        let sup = host_mods(false, false, false, true);
        // Ctrl+K and Ctrl+k both match (case-insensitive).
        assert!(command_palette_open_shortcut_matches(
            &HostKey::Character("k".to_string()),
            &ctrl
        ));
        assert!(command_palette_open_shortcut_matches(
            &HostKey::Character("K".to_string()),
            &ctrl
        ));
        // Platform/super + K matches.
        assert!(command_palette_open_shortcut_matches(
            &HostKey::Character("k".to_string()),
            &sup
        ));
        assert!(command_palette_open_shortcut_matches(
            &HostKey::Character("K".to_string()),
            &sup
        ));
    }

    #[test]
    fn open_shortcut_rejects_plain_k_unrelated_ctrl_and_extra_modifiers() {
        use super::command_palette_open_shortcut_matches;
        use crate::host_event::HostKey;
        use crate::host_mods;

        // Plain K with no modifier is a normal keystroke, not the shortcut.
        assert!(!command_palette_open_shortcut_matches(
            &HostKey::Character("k".to_string()),
            &host_mods(false, false, false, false)
        ));
        // Ctrl with an unrelated letter is not the shortcut.
        assert!(!command_palette_open_shortcut_matches(
            &HostKey::Character("j".to_string()),
            &host_mods(true, false, false, false)
        ));
        // Alt+K and Ctrl+Alt+K must stay distinct (we require exactly the trigger modifier).
        assert!(!command_palette_open_shortcut_matches(
            &HostKey::Character("k".to_string()),
            &host_mods(false, true, false, false)
        ));
        assert!(!command_palette_open_shortcut_matches(
            &HostKey::Character("k".to_string()),
            &host_mods(true, true, false, false)
        ));
        // Ctrl+Super+K (both trigger modifiers) is ambiguous and must not match.
        assert!(!command_palette_open_shortcut_matches(
            &HostKey::Character("k".to_string()),
            &host_mods(true, false, false, true)
        ));
    }

    #[test]
    fn split_shortcut_matches_right_and_down_with_ctrl_or_super() {
        use super::{split_shortcut_matches, RendererTabSplitAxis};
        use crate::host_event::HostKey;
        use crate::host_mods;

        let ctrl = host_mods(true, false, false, false);
        let sup = host_mods(false, false, false, true);
        let ctrl_shift = host_mods(true, false, true, false);
        let super_shift = host_mods(false, false, true, true);

        // Ctrl+D / Cmd+D => split RIGHT, case-insensitive on D.
        assert_eq!(
            split_shortcut_matches(&HostKey::Character("d".to_string()), &ctrl),
            Some(RendererTabSplitAxis::Right)
        );
        assert_eq!(
            split_shortcut_matches(&HostKey::Character("D".to_string()), &sup),
            Some(RendererTabSplitAxis::Right)
        );
        // Ctrl+Shift+D / Cmd+Shift+D => split DOWN.
        assert_eq!(
            split_shortcut_matches(&HostKey::Character("d".to_string()), &ctrl_shift),
            Some(RendererTabSplitAxis::Down)
        );
        assert_eq!(
            split_shortcut_matches(&HostKey::Character("D".to_string()), &super_shift),
            Some(RendererTabSplitAxis::Down)
        );
    }

    #[test]
    fn split_shortcut_rejects_plain_d_unrelated_chords_and_ambiguous_modifiers() {
        use super::split_shortcut_matches;
        use crate::host_event::HostKey;
        use crate::host_mods;

        // Plain D (no chord modifier) is normal typing, never a split.
        assert_eq!(
            split_shortcut_matches(
                &HostKey::Character("d".to_string()),
                &host_mods(false, false, false, false)
            ),
            None
        );
        // Shift+D alone (a capital letter) is not a split either.
        assert_eq!(
            split_shortcut_matches(
                &HostKey::Character("d".to_string()),
                &host_mods(false, false, true, false)
            ),
            None
        );
        // A chord modifier with a different letter never matches.
        assert_eq!(
            split_shortcut_matches(
                &HostKey::Character("k".to_string()),
                &host_mods(true, false, false, false)
            ),
            None
        );
        // Alt disqualifies (Ctrl+Alt+D, Cmd+Alt+D are not splits).
        assert_eq!(
            split_shortcut_matches(
                &HostKey::Character("d".to_string()),
                &host_mods(true, true, false, false)
            ),
            None
        );
        // Ctrl+Super+D (both trigger modifiers) is ambiguous and must not match.
        assert_eq!(
            split_shortcut_matches(
                &HostKey::Character("d".to_string()),
                &host_mods(true, false, false, true)
            ),
            None
        );
    }

    #[test]
    fn emit_split_request_sends_exactly_one_event_per_axis() {
        use super::{emit_split_requested, RendererTabSplitAxis};
        for axis in [RendererTabSplitAxis::Right, RendererTabSplitAxis::Down] {
            let (tx, rx) = std::sync::mpsc::channel();
            assert!(emit_split_requested(
                Some(&tx),
                axis,
                Some("tab-src".to_string())
            ));
            match rx.recv().expect("event round-trips") {
                RendererEvent::SplitRequested {
                    axis: got,
                    from_tab_id,
                } => {
                    assert_eq!(got, axis);
                    assert_eq!(from_tab_id.as_deref(), Some("tab-src"));
                }
                other => panic!("expected one SplitRequested, got {other:?}"),
            }
            assert!(
                rx.try_recv().is_err(),
                "exactly one split-request event is emitted"
            );
        }
        // A closed/absent channel is non-fatal.
        assert!(!emit_split_requested(
            None,
            RendererTabSplitAxis::Right,
            None
        ));
    }

