    #[test]
    fn settings_shortcut_emits_only_when_no_modal_overlay_is_shown() {
        use super::settings_panel_open_shortcut_emits;
        // No modal overlay: the chord opens/refreshes the settings panel.
        assert!(settings_panel_open_shortcut_emits(false, false));
        // Command palette is a modal: the chord defers to it and emits nothing.
        assert!(!settings_panel_open_shortcut_emits(false, true));
        // Picker is a modal: the chord defers to it and emits nothing.
        assert!(!settings_panel_open_shortcut_emits(true, false));
        // Both shown (defensive): still no settings emit.
        assert!(!settings_panel_open_shortcut_emits(true, true));
    }

    #[test]
    fn settings_shortcut_intent_opens_when_no_panel_or_dashboard_panel() {
        use super::{
            settings_panel_shortcut_intent, DashboardPanelSource, SettingsPanelShortcutIntent,
        };
        // No modal, no current panel -> Open (the app resolves + sends the settings panel back).
        assert_eq!(
            settings_panel_shortcut_intent(false, false, None),
            SettingsPanelShortcutIntent::Open
        );
        // No modal, current panel is a DASHBOARD panel -> Open (REPLACE, never clear an unrelated
        // dashboard panel). This is the core safety property: a dashboard panel takes the open branch.
        assert_eq!(
            settings_panel_shortcut_intent(false, false, Some(DashboardPanelSource::Dashboard)),
            SettingsPanelShortcutIntent::Open
        );
    }

    #[test]
    fn settings_shortcut_intent_closes_when_current_panel_is_settings() {
        use super::{
            settings_panel_shortcut_intent, DashboardPanelSource, SettingsPanelShortcutIntent,
        };
        // No modal, current panel is already the SETTINGS panel -> Close (toggle off).
        assert_eq!(
            settings_panel_shortcut_intent(false, false, Some(DashboardPanelSource::Settings)),
            SettingsPanelShortcutIntent::Close
        );
    }

    #[test]
    fn settings_shortcut_intent_is_none_while_a_modal_overlay_is_shown() {
        use super::{
            settings_panel_shortcut_intent, DashboardPanelSource, SettingsPanelShortcutIntent,
        };
        // Command palette shown -> None regardless of the current panel source (modal protection).
        assert_eq!(
            settings_panel_shortcut_intent(false, true, None),
            SettingsPanelShortcutIntent::None
        );
        assert_eq!(
            settings_panel_shortcut_intent(false, true, Some(DashboardPanelSource::Settings)),
            SettingsPanelShortcutIntent::None
        );
        // Picker shown -> None as well.
        assert_eq!(
            settings_panel_shortcut_intent(true, false, Some(DashboardPanelSource::Dashboard)),
            SettingsPanelShortcutIntent::None
        );
    }

