    #[test]
    fn set_command_palette_overlay_command_bridges_to_matching_user_event() {
        // `Some(model)` and `None` both bridge to the matching `UserEvent::SetCommandPaletteOverlay`.
        let model = model_with_three_rows();
        let event = user_event_for_command(RendererCommand::SetCommandPaletteOverlay {
            command_palette: Some(model.clone()),
        });
        match event {
            UserEvent::SetCommandPaletteOverlay {
                command_palette: Some(got),
            } => assert_eq!(got.rows.len(), model.rows.len()),
            other => panic!("expected SetCommandPaletteOverlay(Some), got {other:?}"),
        }
        let cleared = user_event_for_command(RendererCommand::SetCommandPaletteOverlay {
            command_palette: None,
        });
        match cleared {
            UserEvent::SetCommandPaletteOverlay {
                command_palette: None,
            } => {}
            other => panic!("expected SetCommandPaletteOverlay(None), got {other:?}"),
        }
    }

    #[test]
    fn app_seed_command_palette_overlay_shows_deterministic_lines_and_clears_query_result() {
        // Seed a closed App with a stale query+result, then drive a fresh overlay model through the same
        // method the `SetCommandPaletteOverlay { Some(model) }` command uses. It must show the model's
        // rows with a deterministic initial selection and clear any prior query/result.
        let mut app = headless_app_with_command_palette(model_with_three_rows());
        // Dirty the state as if a prior session left a query and result behind.
        app.dismiss_command_palette();
        app.command_palette_query = "stale".to_string();
        app.command_palette_result = Some(RendererCommandPaletteResult {
            text: "old result".to_string(),
        });

        app.seed_command_palette_overlay(model_with_three_rows());

        assert!(
            app.command_palette_model.is_some(),
            "full model is stored on seed"
        );
        let lines = app
            .command_palette_lines
            .as_ref()
            .expect("overlay lines composed on seed");
        // Deterministic initial selection: the first action row is selected.
        let first_action = lines
            .iter()
            .find(|l| l.selectable)
            .expect("at least one action row");
        assert!(
            first_action.selected,
            "first action row is selected deterministically on open"
        );
        assert!(
            app.command_palette_query.is_empty(),
            "stale query is cleared on seed"
        );
        assert!(
            app.command_palette_result.is_none(),
            "stale result is cleared on seed"
        );
    }

    #[test]
    fn app_set_command_palette_overlay_none_clears_like_dismiss() {
        // The `None` arm of `SetCommandPaletteOverlay` must clear exactly like Escape/dismiss.
        let mut app = headless_app_with_command_palette(model_with_three_rows());
        app.command_palette_result = Some(RendererCommandPaletteResult {
            text: "ran a (read-only)".to_string(),
        });
        assert!(app.command_palette_model.is_some());

        // Drive the None path the same way handle_user_event does.
        app.dismiss_command_palette();

        assert!(app.command_palette_lines.is_none());
        assert!(app.command_palette_model.is_none());
        assert!(app.command_palette_query.is_empty());
        assert!(app.command_palette_result.is_none());
    }

    #[test]
    fn set_dashboard_panel_command_bridges_to_matching_user_event() {
        // `Some(panel)` and `None` both bridge to the matching `UserEvent::SetDashboardPanel`.
        let panel = RendererDashboardPanel::settings(vec![
            "Settings".to_string(),
            "font_size_px: 14".to_string(),
        ]);
        let event = user_event_for_command(RendererCommand::SetDashboardPanel {
            dashboard_panel: Some(panel.clone()),
        });
        match event {
            UserEvent::SetDashboardPanel {
                dashboard_panel: Some(got),
            } => assert_eq!(got, panel),
            other => panic!("expected SetDashboardPanel(Some), got {other:?}"),
        }
        let cleared = user_event_for_command(RendererCommand::SetDashboardPanel {
            dashboard_panel: None,
        });
        match cleared {
            UserEvent::SetDashboardPanel {
                dashboard_panel: None,
            } => {}
            other => panic!("expected SetDashboardPanel(None), got {other:?}"),
        }
    }

