    #[test]
    fn validate_settings_edit_draft_value_enforces_conservative_per_key_rules() {
        // appearance.theme accepts ONLY the two persisted theme identifiers (whitespace tolerated).
        assert_eq!(
            validate_settings_edit_draft_value("appearance.theme", "built_in_dark"),
            SettingsEditDraftValidation::Valid
        );
        assert_eq!(
            validate_settings_edit_draft_value("appearance.theme", "  high_contrast_dark  "),
            SettingsEditDraftValidation::Valid
        );
        assert!(matches!(
            validate_settings_edit_draft_value("appearance.theme", "neon"),
            SettingsEditDraftValidation::Invalid { .. }
        ));

        // appearance.font_size_px accepts only decimal integers in 10..=32.
        for ok in ["10", "16", "32", " 24 "] {
            assert_eq!(
                validate_settings_edit_draft_value("appearance.font_size_px", ok),
                SettingsEditDraftValidation::Valid,
                "font size {ok:?} should be valid"
            );
        }
        for bad in ["9", "33", "0", "16.0", "12px", "-5", "", "abc"] {
            assert!(
                matches!(
                    validate_settings_edit_draft_value("appearance.font_size_px", bad),
                    SettingsEditDraftValidation::Invalid { .. }
                ),
                "font size {bad:?} should be invalid"
            );
        }

        // Every chrome.*_default key accepts true/false case-insensitively and nothing else.
        for key in [
            "chrome.top_tab_bar_default",
            "chrome.dashboard_status_default",
            "chrome.dashboard_panel_default",
            "chrome.picker_overlay_default",
        ] {
            for ok in ["true", "false", "TRUE", "False", " True "] {
                assert_eq!(
                    validate_settings_edit_draft_value(key, ok),
                    SettingsEditDraftValidation::Valid,
                    "{key} = {ok:?} should be valid"
                );
            }
            for bad in ["1", "0", "yes", "no", "tru", ""] {
                assert!(
                    matches!(
                        validate_settings_edit_draft_value(key, bad),
                        SettingsEditDraftValidation::Invalid { .. }
                    ),
                    "{key} = {bad:?} should be invalid"
                );
            }
        }

        // shell.default_argv accepts a JSON array of strings with a non-empty first command, and
        // rejects malformed/non-array/non-string/empty-array/empty-command values.
        for ok in ["[\"bash\"]", "[\"/bin/zsh\",\"-l\"]", "  [\"sh\",\"\"]  "] {
            assert_eq!(
                validate_settings_edit_draft_value("shell.default_argv", ok),
                SettingsEditDraftValidation::Valid,
                "shell.default_argv {ok:?} should be valid"
            );
        }
        for bad in [
            "not json", "{}", "[]", "[1]", "[\"\"]", "[\"  \"]", "\"bash\"",
        ] {
            assert!(
                matches!(
                    validate_settings_edit_draft_value("shell.default_argv", bad),
                    SettingsEditDraftValidation::Invalid { .. }
                ),
                "shell.default_argv {bad:?} should be invalid"
            );
        }

        // Any unknown editable key reports Unavailable (never treated as saved).
        assert_eq!(
            validate_settings_edit_draft_value("some.unknown.key", "whatever"),
            SettingsEditDraftValidation::Unavailable
        );
    }

    #[test]
    fn settings_edit_draft_validation_feedback_is_bounded_single_line_and_pending() {
        // Each verdict renders a short, fixed, single-line message; the failure reason is bounded.
        assert_eq!(
            SettingsEditDraftValidation::Valid.feedback(),
            "valid, not saved"
        );
        assert_eq!(
            SettingsEditDraftValidation::Unavailable.feedback(),
            "validation unavailable, not saved"
        );
        let invalid = SettingsEditDraftValidation::Invalid {
            reason: "expected true or false".to_string(),
        }
        .feedback();
        assert_eq!(invalid, "invalid: expected true or false");

        // The draft line shows the verdict but still says pending / not saved, stays single-line, and
        // never carries control characters even if a verdict reason somehow contained them.
        let draft = RendererSettingsPanelEditDraft {
            row_id: "settings.chrome.top_tab_bar_default".to_string(),
            setting_key: "chrome.top_tab_bar_default".to_string(),
            value: "maybe".to_string(),
            validation: Some(SettingsEditDraftValidation::Invalid {
                reason: "expected true or false".to_string(),
            }),
        };
        let line = settings_panel_edit_draft_line(&draft, 4096);
        assert!(
            line.contains("invalid: expected true or false"),
            "draft line shows the failure feedback: {line:?}"
        );
        assert!(
            line.contains("pending") && line.contains("not saved"),
            "draft line stays pending / not saved even with a verdict: {line:?}"
        );

        // A valid verdict still says pending / not saved (validation does NOT mean saved).
        let valid_draft = RendererSettingsPanelEditDraft {
            row_id: "settings.appearance.theme".to_string(),
            setting_key: "appearance.theme".to_string(),
            value: "built_in_dark".to_string(),
            validation: Some(SettingsEditDraftValidation::Valid),
        };
        let valid_line = settings_panel_edit_draft_line(&valid_draft, 4096);
        assert!(valid_line.contains("valid, not saved"));
        assert!(valid_line.contains("pending") && valid_line.contains("not saved"));
        assert!(
            !valid_line.chars().any(|c| c.is_control()),
            "feedback line is control-free: {valid_line:?}"
        );

        // The whole line is clamped to the column budget.
        let narrow = settings_panel_edit_draft_line(&valid_draft, 12);
        assert!(
            narrow.chars().count() <= 12,
            "line clamps to cols: {narrow:?}"
        );
    }

    #[test]
    fn app_validate_settings_edit_draft_stores_verdict_without_mutating_value() {
        // Enter routes to App::validate_settings_edit_draft, which stores a verdict on the draft and
        // leaves everything else (the value, the draft's existence) untouched. It writes NO setting.
        let mut app = headless_app_with_command_palette(model_with_three_rows());

        // No draft: validation is a no-op (false), nothing created.
        assert!(!app.validate_settings_edit_draft());
        assert!(app.settings_edit_draft.is_none());

        app.set_settings_edit_draft(Some(RendererSettingsPanelEditDraft {
            row_id: "settings.appearance.font_size_px".to_string(),
            setting_key: "appearance.font_size_px".to_string(),
            value: "16".to_string(),
            validation: None,
        }));

        assert!(app.validate_settings_edit_draft());
        let draft = app.settings_edit_draft.as_ref().unwrap();
        assert_eq!(draft.value, "16", "validation never mutates the value");
        assert_eq!(
            draft.validation,
            Some(SettingsEditDraftValidation::Valid),
            "a valid value stores a Valid verdict"
        );

        // An invalid value stores an Invalid verdict; the draft survives and stays pending.
        app.set_settings_edit_draft(Some(RendererSettingsPanelEditDraft {
            row_id: "settings.appearance.font_size_px".to_string(),
            setting_key: "appearance.font_size_px".to_string(),
            value: "99".to_string(),
            validation: None,
        }));
        assert!(app.validate_settings_edit_draft());
        assert!(matches!(
            app.settings_edit_draft.as_ref().unwrap().validation,
            Some(SettingsEditDraftValidation::Invalid { .. })
        ));
        assert!(
            app.settings_edit_draft.is_some(),
            "validating does not clear the draft"
        );
    }

    #[test]
    fn app_edit_draft_value_changes_clear_stale_validation_feedback() {
        // Typing or backspacing after a verdict clears the stale feedback so the draft never shows a
        // verdict for a value the user has since edited; a no-op edit leaves the verdict in place.
        let mut app = headless_app_with_command_palette(model_with_three_rows());
        app.set_settings_edit_draft(Some(RendererSettingsPanelEditDraft {
            row_id: "settings.appearance.font_size_px".to_string(),
            setting_key: "appearance.font_size_px".to_string(),
            value: "16".to_string(),
            validation: Some(SettingsEditDraftValidation::Valid),
        }));

        // Typing a real character clears the stale verdict.
        assert!(app.append_settings_edit_draft_value("7"));
        assert!(
            app.settings_edit_draft
                .as_ref()
                .unwrap()
                .validation
                .is_none(),
            "typing clears stale validation feedback"
        );

        // Re-validate, then a no-op append (sanitizes to nothing) keeps the verdict in place.
        app.validate_settings_edit_draft();
        assert!(app
            .settings_edit_draft
            .as_ref()
            .unwrap()
            .validation
            .is_some());
        assert!(!app.append_settings_edit_draft_value("\n\r"));
        assert!(
            app.settings_edit_draft
                .as_ref()
                .unwrap()
                .validation
                .is_some(),
            "a no-op edit does not clear the verdict"
        );

        // Backspace that changes the value clears the verdict.
        assert!(app.backspace_settings_edit_draft_value());
        assert!(
            app.settings_edit_draft
                .as_ref()
                .unwrap()
                .validation
                .is_none(),
            "backspace that changes the value clears stale validation feedback"
        );

        // Re-validate, then empty the value and confirm backspace-on-empty is a no-op that leaves the
        // verdict untouched (no underflow, no misleading clear/relabel).
        while app.backspace_settings_edit_draft_value() {}
        assert_eq!(app.settings_edit_draft.as_ref().unwrap().value, "");
        app.validate_settings_edit_draft();
        let verdict = app.settings_edit_draft.as_ref().unwrap().validation.clone();
        assert!(verdict.is_some());
        assert!(
            !app.backspace_settings_edit_draft_value(),
            "backspace on empty is a no-op"
        );
        assert_eq!(
            app.settings_edit_draft.as_ref().unwrap().validation,
            verdict,
            "a no-op backspace does not change the verdict"
        );
    }

    #[test]
    fn app_set_settings_edit_draft_validation_does_not_shift_settings_row_indexes() {
        // Validating the draft must not change settings-row hit-testing or selection: the draft line is
        // drawn after the settings rows and excluded from the selectable set, so the reserved row count
        // is identical before and after a verdict is stored.
        let mut app = headless_app_with_command_palette(model_with_three_rows());
        app.set_dashboard_panel(Some(RendererDashboardPanel::settings(vec![
            "Settings".to_string(),
            "appearance.font_size_px: 16".to_string(),
        ])));
        app.set_settings_edit_draft(Some(RendererSettingsPanelEditDraft {
            row_id: "settings.appearance.font_size_px".to_string(),
            setting_key: "appearance.font_size_px".to_string(),
            value: "16".to_string(),
            validation: None,
        }));
        let own_rows_before = dashboard_panel_rows(app.dashboard_panel.as_ref());
        let effective_before = app.effective_dashboard_panel_rows();

        app.validate_settings_edit_draft();

        assert_eq!(
            dashboard_panel_rows(app.dashboard_panel.as_ref()),
            own_rows_before,
            "validating does not change the panel's own reserved rows"
        );
        assert_eq!(
            app.effective_dashboard_panel_rows(),
            effective_before,
            "validating does not add or remove a reserved row"
        );
    }

    #[test]
    fn app_set_dashboard_panel_some_stores_panel_and_recomputes_offset() {
        // `Some(panel)` stores/replaces the top panel; the grid-origin chrome offset keys off
        // `dashboard_panel_rows`, so storing a 2-line panel makes it reserve exactly 2 rows.
        let mut app = headless_app_with_command_palette(model_with_three_rows());
        assert_eq!(
            dashboard_panel_rows(app.dashboard_panel.as_ref()),
            0,
            "no panel reserves zero rows"
        );

        let panel = RendererDashboardPanel::settings(vec![
            "Settings".to_string(),
            "font_size_px: 14".to_string(),
        ]);
        app.set_dashboard_panel(Some(panel.clone()));

        assert_eq!(
            app.dashboard_panel.as_ref(),
            Some(&panel),
            "panel is stored"
        );
        assert_eq!(
            dashboard_panel_rows(app.dashboard_panel.as_ref()),
            2,
            "grid-origin offset recomputes to the stored panel's line count"
        );

        // Replacing with a different panel swaps it (and the recomputed offset) wholesale.
        let replacement = RendererDashboardPanel::dashboard(vec![
            "A".to_string(),
            "B".to_string(),
            "C".to_string(),
        ]);
        app.set_dashboard_panel(Some(replacement.clone()));
        assert_eq!(app.dashboard_panel.as_ref(), Some(&replacement));
        assert_eq!(dashboard_panel_rows(app.dashboard_panel.as_ref()), 3);
    }

    #[test]
    fn app_set_dashboard_panel_none_clears_panel() {
        // `None` clears the top panel and the reserved chrome offset returns to zero.
        let mut app = headless_app_with_command_palette(model_with_three_rows());
        app.set_dashboard_panel(Some(RendererDashboardPanel::settings(vec![
            "Settings".to_string()
        ])));
        assert_eq!(dashboard_panel_rows(app.dashboard_panel.as_ref()), 1);

        app.set_dashboard_panel(None);

        assert!(app.dashboard_panel.is_none(), "None clears the panel");
        assert_eq!(dashboard_panel_rows(app.dashboard_panel.as_ref()), 0);
    }

