    #[test]
    fn current_modes_follow_focused_split_pane_grid_not_only_active_grid() {
        let shared = Arc::new(Shared::default());
        *shared.grid.lock().unwrap() = Some(Arc::new(grid_with_modes(
            "active", 21, 10, false, false, false, false,
        )));
        let sibling_epoch = shared.set_sibling_session("sid-src");
        assert!(shared.apply_sibling_grid(
            "sid-src",
            sibling_epoch,
            Arc::new(grid_with_modes("sibling", 10, 10, true, true, true, true)),
        ));

        let mut app = App::new(
            shared,
            "sid-child".to_string(),
            super::DEFAULT_WINDOW_TITLE.to_string(),
            None,
            None,
            false,
            None,
            None,
            None,
            None,
            None,
            None,
            None,
            None,
            None,
        );
        app.tab_strip_source = Some(RendererTabStrip {
            window_id: "win".to_string(),
            tabs: vec![
                renderer_tab("src", "sid-src", false, None),
                renderer_tab(
                    "child",
                    "sid-child",
                    true,
                    Some(("src", RendererTabSplitAxis::Right)),
                ),
            ],
        });

        let active_modes = app.current_modes();
        assert!(!active_modes.app_cursor);
        assert!(!active_modes.bracketed_paste);
        assert!(!active_modes.focus_reporting);
        assert!(!active_modes.mouse.any());

        app.focused_pane_session = Some("sid-src".to_string());
        let focused_modes = app.current_modes();
        assert!(focused_modes.app_cursor);
        assert!(focused_modes.bracketed_paste);
        assert!(focused_modes.focus_reporting);
        assert!(focused_modes.mouse.any());
    }

    /// Build a headless App wired to an outbound event channel, with a settings panel already
    /// active so an edit draft is considered "shown". Returns the app and the receiver so tests can
    /// assert which `RendererEvent` (if any) the submit path emitted.
    fn headless_app_with_events_and_settings_panel(
    ) -> (App, std::sync::mpsc::Receiver<RendererEvent>) {
        let (tx, rx) = std::sync::mpsc::channel();
        let mut app = App::new(
            Arc::new(Shared::default()),
            "submit-test".to_string(),
            super::DEFAULT_WINDOW_TITLE.to_string(),
            None,
            None,
            false,
            None,
            None,
            None,
            None,
            None,
            Some(tx),
            None,
            None,
            None,
        );
        app.set_dashboard_panel(Some(RendererDashboardPanel::settings(vec![
            "Settings".to_string(),
            "top_tab_bar_default: false".to_string(),
        ])));
        (app, rx)
    }

    fn submit_draft(setting_key: &str, value: &str) -> RendererSettingsPanelEditDraft {
        RendererSettingsPanelEditDraft {
            row_id: format!("settings.{setting_key}"),
            setting_key: setting_key.to_string(),
            value: value.to_string(),
            validation: None,
        }
    }

    #[test]
    fn submit_emits_for_every_valid_chrome_boolean_draft() {
        // Enter on a VALID draft for ANY of the four chrome boolean keys emits exactly one bounded
        // submit event carrying only row_id/setting_key/value, returns true, and KEEPS the draft
        // visible (the app clears it after the write). Case-insensitivity and surrounding whitespace
        // are tolerated by the existing validation rules.
        for key in SETTINGS_CHROME_BOOL_KEYS {
            for value in ["true", "false", "  TRUE  ", "False"] {
                let (mut app, rx) = headless_app_with_events_and_settings_panel();
                app.set_settings_edit_draft(Some(submit_draft(key, value)));
                assert!(
                    app.submit_settings_edit_draft(),
                    "valid {key} submits for {value:?}"
                );
                match rx.try_recv() {
                    Ok(RendererEvent::SettingsPanelEditDraftSubmitted {
                        row_id,
                        setting_key,
                        value: emitted,
                    }) => {
                        assert_eq!(row_id, format!("settings.{key}"));
                        assert_eq!(setting_key, key);
                        assert_eq!(emitted, value, "the raw (unparsed) draft value is sent");
                    }
                    other => panic!("expected one submit event for {key}, got {other:?}"),
                }
                assert!(
                    rx.try_recv().is_err(),
                    "exactly one submit event is emitted for {key}"
                );
                assert!(
                    app.settings_edit_draft.is_some(),
                    "the draft stays visible until the app responds for {key}"
                );
            }
        }
    }

    #[test]
    fn submit_does_not_emit_for_invalid_boolean_value() {
        // An invalid boolean for a writable chrome key does NOT submit; it falls back to storing the
        // renderer-local verdict, emits nothing, and keeps the draft.
        for value in ["maybe", "1", "yes", "tru", ""] {
            let (mut app, rx) = headless_app_with_events_and_settings_panel();
            app.set_settings_edit_draft(Some(submit_draft(
                "chrome.dashboard_status_default",
                value,
            )));
            assert!(
                !app.submit_settings_edit_draft(),
                "invalid boolean {value:?} does not submit"
            );
            assert!(
                rx.try_recv().is_err(),
                "no submit event for invalid value {value:?}"
            );
            assert!(
                matches!(
                    app.settings_edit_draft.as_ref().unwrap().validation,
                    Some(SettingsEditDraftValidation::Invalid { .. })
                ),
                "invalid submit falls back to the local invalid verdict for {value:?}"
            );
        }
    }

